{
  "name": "ProjectFlow Linear Mindmap",
  "description": "A sophisticated project tracking tool that visualizes project lifecycles as interactive linear mindmaps with parallel paths, milestone pie charts, and AI-assisted project structure generation.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum SubtaskStatus {
  COMPLETE = 'Complete',
  NOT_COMPLETE = 'Not Complete',
  STARTED = 'Started',
  HELD = 'Held'
}

export enum ProjectType {
  SUBDIVISION = 'Subdivision',
  GREENFIELD = 'Greenfield Development',
  OTHER = 'Other'
}

export interface Subtask {
  id: string;
  name: string;
  assignedTo: string;
  description: string;
  notes: string;
  status: SubtaskStatus;
}

export interface Milestone {
  id: string;
  name: string;
  subtasks: Subtask[];
  dependsOn: string[]; // List of IDs of milestones this milestone depends on
  x?: number; // Visual coordinates (calculated)
  y?: number;
}

export interface Project {
  id: string;
  name: string;
  company: string;
  type: ProjectType;
  milestones: Milestone[];
  createdAt: number;
}

export interface AppState {
  projects: Project[];
  selectedProjectId: string | null;
  showSubtasks: boolean;
}

import React from 'react';
import { SubtaskStatus } from './types';

export const STATUS_COLORS: Record<SubtaskStatus, string> = {
  [SubtaskStatus.COMPLETE]: '#dcfce7', // light green-100
  [SubtaskStatus.STARTED]: '#dbeafe',  // light blue-100
  [SubtaskStatus.HELD]: '#fef9c3',     // light yellow-100
  [SubtaskStatus.NOT_COMPLETE]: '#f1f5f9' // light slate-100
};

export const STATUS_BORDER_COLORS: Record<SubtaskStatus, string> = {
  [SubtaskStatus.COMPLETE]: '#22c55e',
  [SubtaskStatus.STARTED]: '#3b82f6',
  [SubtaskStatus.HELD]: '#eab308',
  [SubtaskStatus.NOT_COMPLETE]: '#94a3b8'
};

import { GoogleGenAI, Type } from "@google/genai";
import { ProjectType, SubtaskStatus } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateProjectStructure(name: string, type: ProjectType) {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a logical project structure for a project named "${name}" of type "${type}". 
      The response must be a JSON object containing milestones. 
      Each milestone must have a unique ID, a name, a list of subtasks, and an array of 'dependsOn' milestone IDs to form a sequence or parallel paths.
      Ensure there is at least one start milestone (empty dependsOn).
      Each subtask needs a name, description, and status.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            milestones: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  name: { type: Type.STRING },
                  dependsOn: { type: Type.ARRAY, items: { type: Type.STRING } },
                  subtasks: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        description: { type: Type.STRING }
                      },
                      required: ["name", "description"]
                    }
                  }
                },
                required: ["id", "name", "dependsOn", "subtasks"]
              }
            }
          }
        }
      }
    });

    try {
      return JSON.parse(response.text);
    } catch (e) {
      console.error("Failed to parse AI response", e);
      return null;
    }
  }
}

export const geminiService = new GeminiService();

import React from 'react';
import { PieChart as RePieChart, Pie, Cell, ResponsiveContainer } from 'recharts';
import { Subtask, SubtaskStatus } from '../types';
import { STATUS_COLORS } from '../constants';

interface PieChartProps {
  subtasks: Subtask[];
  size?: number;
}

export const MilestonePieChart: React.FC<PieChartProps> = ({ subtasks, size = 120 }) => {
  const dataMap = subtasks.reduce((acc, sub) => {
    acc[sub.status] = (acc[sub.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const data = Object.values(SubtaskStatus).map(status => ({
    name: status,
    value: dataMap[status] || 0,
    color: STATUS_COLORS[status]
  })).filter(d => d.value > 0);

  // If no subtasks, show a full gray circle
  if (data.length === 0) {
    data.push({ name: 'Empty', value: 1, color: '#f1f5f9' });
  }

  return (
    <div style={{ width: size, height: size }} className="relative">
      <ResponsiveContainer width="100%" height="100%">
        <RePieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={size * 0.25}
            outerRadius={size * 0.45}
            paddingAngle={2}
            dataKey="value"
            stroke="none"
          >
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} />
            ))}
          </Pie>
        </RePieChart>
      </ResponsiveContainer>
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <span className="text-[10px] font-bold text-slate-500">
          {Math.round((dataMap[SubtaskStatus.COMPLETE] || 0) / (subtasks.length || 1) * 100)}%
        </span>
      </div>
    </div>
  );
};

import React from 'react';
import { Milestone, SubtaskStatus } from '../types';
import { MilestonePieChart } from './PieChart';
import { Plus, ChevronDown, ChevronRight, User, MoreVertical } from 'lucide-react';

interface MilestoneNodeProps {
  milestone: Milestone;
  showSubtasks: boolean;
  onAddSubtask: (milestoneId: string) => void;
  onAddSequence: (milestoneId: string) => void;
  onAddParallel: (milestoneId: string) => void;
  onEditSubtask: (milestoneId: string, subtaskIndex: number) => void;
  onClick: () => void;
}

export const MilestoneNode: React.FC<MilestoneNodeProps> = ({
  milestone,
  showSubtasks,
  onAddSubtask,
  onAddSequence,
  onAddParallel,
  onEditSubtask,
  onClick
}) => {
  return (
    <div 
      className="absolute flex flex-col items-center group"
      style={{ left: milestone.x, top: milestone.y, transform: 'translate(-50%, -50%)' }}
    >
      <span className="mb-2 text-sm font-semibold text-slate-700 whitespace-nowrap bg-white/80 px-2 py-0.5 rounded-full shadow-sm">
        {milestone.name}
      </span>

      <div 
        className="relative cursor-pointer transition-transform hover:scale-105 active:scale-95"
        onClick={onClick}
      >
        <div className="rounded-full bg-white shadow-lg ring-1 ring-slate-200">
          <MilestonePieChart subtasks={milestone.subtasks} size={100} />
        </div>

        {/* Action Buttons (Visible on hover) */}
        <div className="absolute -right-12 top-0 flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => { e.stopPropagation(); onAddSequence(milestone.id); }}
            className="p-1.5 bg-blue-600 text-white rounded-full shadow-md hover:bg-blue-700"
            title="Add Sequence Milestone"
          >
            <ChevronRight size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onAddParallel(milestone.id); }}
            className="p-1.5 bg-indigo-600 text-white rounded-full shadow-md hover:bg-indigo-700"
            title="Add Parallel Milestone"
          >
            <Plus size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onAddSubtask(milestone.id); }}
            className="p-1.5 bg-emerald-600 text-white rounded-full shadow-md hover:bg-emerald-700"
            title="Add Subtask"
          >
            <Plus size={14} />
          </button>
        </div>
      </div>

      {showSubtasks && milestone.subtasks.length > 0 && (
        <div className="mt-4 w-48 bg-white rounded-lg shadow-md border border-slate-100 p-2 z-10">
          <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 border-b pb-1">
            Subtasks ({milestone.subtasks.length})
          </div>
          <div className="flex flex-col gap-1">
            {milestone.subtasks.map((task, idx) => (
              <div 
                key={task.id} 
                onClick={(e) => { e.stopPropagation(); onEditSubtask(milestone.id, idx); }}
                className="text-xs p-1.5 rounded bg-slate-50 hover:bg-slate-100 cursor-pointer flex items-center justify-between group/task"
              >
                <div className="flex flex-col flex-1 min-w-0">
                  <span className="font-medium truncate text-slate-700">{task.name}</span>
                  <span className="text-[9px] text-slate-400 flex items-center gap-1">
                    <User size={8} /> {task.assignedTo || 'Unassigned'}
                  </span>
                </div>
                <div 
                  className="w-2 h-2 rounded-full shrink-0" 
                  style={{ backgroundColor: 
                    task.status === SubtaskStatus.COMPLETE ? '#22c55e' : 
                    task.status === SubtaskStatus.STARTED ? '#3b82f6' : 
                    task.status === SubtaskStatus.HELD ? '#eab308' : '#cbd5e1'
                  }} 
                />
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { 
  Project, 
  ProjectType, 
  Milestone, 
  Subtask, 
  SubtaskStatus 
} from './types';
import { MilestoneNode } from './components/MilestoneNode';
import { 
  Plus, 
  Layers, 
  Copy, 
  Layout, 
  Filter, 
  Eye, 
  EyeOff, 
  ChevronLeft,
  Search,
  Settings,
  Briefcase,
  Building,
  Wand2
} from 'lucide-react';
import { geminiService } from './services/geminiService';

const STORAGE_KEY = 'projectflow_data_v1';

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [showSubtasks, setShowSubtasks] = useState(true);
  const [filterType, setFilterType] = useState<ProjectType | 'ALL'>('ALL');
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [isEditingSubtask, setIsEditingSubtask] = useState<{ mId: string, sIdx: number | null } | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);

  // New project state
  const [newProject, setNewProject] = useState({ name: '', company: '', type: ProjectType.OTHER });

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProjects(JSON.parse(saved));
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(projects));
  }, [projects]);

  const activeProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
    [projects, selectedProjectId]
  );

  const handleCreateProject = async (useAI = false) => {
    if (!newProject.name) return;
    setIsGenerating(true);

    let milestones: Milestone[] = [];

    if (useAI) {
      const res = await geminiService.generateProjectStructure(newProject.name, newProject.type);
      if (res && res.milestones) {
        milestones = res.milestones.map((m: any) => ({
          ...m,
          subtasks: m.subtasks.map((s: any) => ({
            id: Math.random().toString(36).substr(2, 9),
            name: s.name,
            description: s.description,
            assignedTo: '',
            notes: '',
            status: SubtaskStatus.NOT_COMPLETE
          }))
        }));
      }
    } else {
      milestones = [{
        id: 'm1',
        name: 'Initial Concept',
        dependsOn: [],
        subtasks: [{
          id: 's1',
          name: 'Define Scope',
          description: 'Basic requirements gather',
          assignedTo: '',
          notes: '',
          status: SubtaskStatus.NOT_COMPLETE
        }]
      }];
    }

    const project: Project = {
      id: Date.now().toString(),
      name: newProject.name,
      company: newProject.company,
      type: newProject.type,
      milestones,
      createdAt: Date.now()
    };

    setProjects([...projects, project]);
    setSelectedProjectId(project.id);
    setIsCreatingProject(false);
    setIsGenerating(false);
    setNewProject({ name: '', company: '', type: ProjectType.OTHER });
  };

  const handleDuplicateProject = (id: string) => {
    const p = projects.find(proj => proj.id === id);
    if (!p) return;
    const newP = { ...p, id: Date.now().toString(), name: `${p.name} (Copy)`, createdAt: Date.now() };
    setProjects([...projects, newP]);
  };

  const handleDeleteProject = (id: string) => {
    if (confirm('Delete this project?')) {
      setProjects(projects.filter(p => p.id !== id));
      if (selectedProjectId === id) setSelectedProjectId(null);
    }
  };

  const handleAddMilestone = (pId: string, parentId: string | null, isParallel: boolean) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== pId) return p;
      const newId = `m-${Date.now()}`;
      const newMilestone: Milestone = {
        id: newId,
        name: isParallel ? 'New Parallel Branch' : 'Next Milestone',
        dependsOn: parentId ? [parentId] : [],
        subtasks: [{
          id: `s-${Date.now()}`,
          name: 'Default Subtask',
          description: '',
          assignedTo: '',
          notes: '',
          status: SubtaskStatus.NOT_COMPLETE
        }]
      };
      return { ...p, milestones: [...p.milestones, newMilestone] };
    }));
  };

  const handleAddSubtask = (mId: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          return {
            ...m,
            subtasks: [...m.subtasks, {
              id: `s-${Date.now()}`,
              name: 'New Subtask',
              description: '',
              assignedTo: '',
              notes: '',
              status: SubtaskStatus.NOT_COMPLETE
            }]
          };
        })
      };
    }));
  };

  const updateSubtask = (mId: string, sIdx: number, updates: Partial<Subtask>) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          const newSubtasks = [...m.subtasks];
          newSubtasks[sIdx] = { ...newSubtasks[sIdx], ...updates };
          return { ...m, subtasks: newSubtasks };
        })
      };
    }));
  };

  // Layout logic
  const positionedMilestones = useMemo(() => {
    if (!activeProject) return [];

    const levels: Record<string, number> = {};
    const processed = new Set<string>();

    const getLevel = (id: string): number => {
      if (levels[id] !== undefined) return levels[id];
      const m = activeProject.milestones.find(mil => mil.id === id);
      if (!m || m.dependsOn.length === 0) {
        levels[id] = 0;
        return 0;
      }
      const maxParentLevel = Math.max(...m.dependsOn.map(parentId => getLevel(parentId)));
      levels[id] = maxParentLevel + 1;
      return levels[id];
    };

    activeProject.milestones.forEach(m => getLevel(m.id));

    const groupedByLevel: Record<number, string[]> = {};
    Object.entries(levels).forEach(([id, level]) => {
      if (!groupedByLevel[level]) groupedByLevel[level] = [];
      groupedByLevel[level].push(id);
    });

    const HORIZONTAL_GAP = 280;
    const VERTICAL_GAP = 200;
    const START_X = 150;
    const START_Y = 300;

    return activeProject.milestones.map(m => {
      const level = levels[m.id];
      const indexInLevel = groupedByLevel[level].indexOf(m.id);
      const totalInLevel = groupedByLevel[level].length;

      const x = START_X + level * HORIZONTAL_GAP;
      const y = START_Y + (indexInLevel - (totalInLevel - 1) / 2) * VERTICAL_GAP;

      return { ...m, x, y };
    });
  }, [activeProject]);

  const filteredProjects = projects.filter(p => filterType === 'ALL' || p.type === filterType);

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg text-white">
            <Layers size={24} />
          </div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">ProjectFlow</h1>
        </div>

        <div className="flex items-center gap-4">
          {selectedProjectId && (
            <button 
              onClick={() => setSelectedProjectId(null)}
              className="flex items-center gap-2 text-slate-500 hover:text-slate-800 font-medium px-3 py-1.5 rounded-lg"
            >
              <ChevronLeft size={18} /> Back to Dashboard
            </button>
          )}
          <button 
            onClick={() => setIsCreatingProject(true)}
            className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all"
          >
            <Plus size={18} /> New Project
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative">
        {!selectedProjectId ? (
          <div className="p-8 max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-2xl font-bold text-slate-800">Your Projects</h2>
              <div className="flex items-center gap-2">
                <Filter size={18} className="text-slate-400" />
                <select 
                  className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-sm outline-none"
                  value={filterType}
                  onChange={(e) => setFilterType(e.target.value as any)}
                >
                  <option value="ALL">All Types</option>
                  {Object.values(ProjectType).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredProjects.map(p => (
                <div 
                  key={p.id}
                  className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow group relative"
                >
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="text-lg font-bold text-slate-900 leading-tight mb-1">{p.name}</h3>
                      <div className="flex items-center gap-1.5 text-slate-500 text-sm">
                        <Building size={14} />
                        <span>{p.company}</span>
                      </div>
                    </div>
                    <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-full ${
                      p.type === ProjectType.SUBDIVISION ? 'bg-amber-50 text-amber-700' :
                      p.type === ProjectType.GREENFIELD ? 'bg-emerald-50 text-emerald-700' :
                      'bg-slate-50 text-slate-600'
                    }`}>
                      {p.type}
                    </span>
                  </div>

                  <div className="flex gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
                    {p.milestones.slice(0, 4).map(m => (
                      <div key={m.id} className="shrink-0 flex flex-col items-center">
                        <div className="w-8 h-8 rounded-full bg-slate-50 ring-1 ring-slate-100 flex items-center justify-center">
                          <div 
                            className="w-5 h-5 rounded-full" 
                            style={{ 
                              background: `conic-gradient(#22c55e ${Math.round((m.subtasks.filter(s => s.status === SubtaskStatus.COMPLETE).length / m.subtasks.length) * 360)}deg, #f1f5f9 0deg)`
                            }}
                          />
                        </div>
                      </div>
                    ))}
                    {p.milestones.length > 4 && (
                      <div className="shrink-0 w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-[10px] font-bold text-slate-400">
                        +{p.milestones.length - 4}
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => setSelectedProjectId(p.id)}
                      className="flex-1 bg-slate-50 hover:bg-indigo-50 hover:text-indigo-600 text-slate-700 font-semibold py-2 rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
                    >
                      <Eye size={16} /> Open
                    </button>
                    <button 
                      onClick={() => handleDuplicateProject(p.id)}
                      className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg"
                      title="Duplicate"
                    >
                      <Copy size={16} />
                    </button>
                    <button 
                      onClick={() => handleDeleteProject(p.id)}
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg"
                      title="Delete"
                    >
                      <Plus className="rotate-45" size={16} />
                    </button>
                  </div>
                </div>
              ))}
              {filteredProjects.length === 0 && (
                <div className="col-span-full py-20 text-center">
                  <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300">
                    <Briefcase size={32} />
                  </div>
                  <h3 className="text-lg font-semibold text-slate-900 mb-1">No projects found</h3>
                  <p className="text-slate-500">Create your first project to get started</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="h-full w-full flex flex-col bg-slate-50 overflow-hidden">
            {/* Toolbar for Active Project */}
            <div className="bg-white border-b border-slate-200 px-6 py-3 flex items-center justify-between shadow-sm z-20">
              <div>
                <h2 className="text-lg font-bold text-slate-900">{activeProject?.name}</h2>
                <p className="text-xs text-slate-500">{activeProject?.company} • {activeProject?.type}</p>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => setShowSubtasks(!showSubtasks)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold transition-colors ${
                    showSubtasks ? 'bg-indigo-50 text-indigo-700' : 'bg-slate-50 text-slate-600'
                  }`}
                >
                  {showSubtasks ? <Eye size={16} /> : <EyeOff size={16} />}
                  {showSubtasks ? 'Hide Subtasks' : 'Show Subtasks'}
                </button>
                <button 
                   onClick={() => activeProject && handleAddMilestone(activeProject.id, null, false)}
                   className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-4 py-1.5 rounded-lg text-sm flex items-center gap-2"
                >
                  <Plus size={16} /> Add Start Milestone
                </button>
              </div>
            </div>

            {/* Canvas */}
            <div className="flex-1 relative overflow-auto mindmap-container bg-[#fcfcfd]">
              <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ minWidth: 3000, minHeight: 2000 }}>
                <defs>
                  <marker id="arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
                    <path d="M 0 0 L 10 5 L 0 10 z" fill="#cbd5e1" />
                  </marker>
                </defs>
                {positionedMilestones.map(m => (
                  m.dependsOn.map(parentId => {
                    const parent = positionedMilestones.find(mil => mil.id === parentId);
                    if (!parent) return null;

                    const dx = m.x! - parent.x!;
                    const dy = m.y! - parent.y!;
                    const controlX = parent.x! + dx / 2;

                    return (
                      <path
                        key={`${parentId}-${m.id}`}
