import React from 'react';
import { PieChart as RePieChart, Pie, Cell, ResponsiveContainer } from 'recharts';
import { Subtask, SubtaskStatus } from '../types';
import { STATUS_COLORS } from '../constants';

interface PieChartProps {
  subtasks: Subtask[];
  size?: number;
}

export const MilestonePieChart: React.FC<PieChartProps> = ({ subtasks, size = 120 }) => {
  const dataMap = subtasks.reduce((acc, sub) => {
    acc[sub.status] = (acc[sub.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Fix: Explicitly define the data type as string for the name to allow for placeholder entries like 'Empty'
  const data: { name: string; value: number; color: string }[] = Object.values(SubtaskStatus).map(status => ({
    name: status as string,
    value: dataMap[status] || 0,
    color: STATUS_COLORS[status]
  })).filter(d => d.value > 0);

  // If no subtasks, show a full gray circle
  if (data.length === 0) {
    data.push({ name: 'Empty', value: 1, color: '#f1f5f9' });
  }

  return (
    <div style={{ width: size, height: size }} className="relative">
      <ResponsiveContainer width="100%" height="100%">
        <RePieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={size * 0.25}
            outerRadius={size * 0.45}
            paddingAngle={2}
            dataKey="value"
            stroke="none"
          >
            {data.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} />
            ))}
          </Pie>
        </RePieChart>
      </ResponsiveContainer>
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
        <span className="text-[10px] font-bold text-slate-500">
          {Math.round((dataMap[SubtaskStatus.COMPLETE] || 0) / (subtasks.length || 1) * 100)}%
        </span>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { ProjectType } from "../types";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    // Correctly initialize with the API key from environment variables as per guidelines
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async generateProjectStructure(name: string, type: ProjectType) {
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a logical project structure for a project named "${name}" of type "${type}". 
      The response must be a JSON object containing milestones. 
      Each milestone must have a unique ID, a name, a list of subtasks, and an array of 'dependsOn' milestone IDs to form a sequence or parallel paths.
      Ensure there is at least one start milestone (empty dependsOn).
      Each subtask needs a name, description, and status.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            milestones: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  name: { type: Type.STRING },
                  dependsOn: { type: Type.ARRAY, items: { type: Type.STRING } },
                  subtasks: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        description: { type: Type.STRING }
                      },
                      required: ["name", "description"]
                    }
                  }
                },
                required: ["id", "name", "dependsOn", "subtasks"]
              }
            }
          }
        }
      }
    });

    try {
      // Accessing the .text property directly as it is a getter (not a method)
      const text = response.text;
      if (!text) return null;
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse AI response", e);
      return null;
    }
  }
}

