import { Plus, ChevronRight, User, Edit2 } from 'lucide-react';
import { getStatusBorderColor } from '../constants';

interface MilestoneNodeProps {
  milestone: Milestone;
  showSubtasks: boolean;
  onAddSubtask: (milestoneId: string) => void;
  onAddSequence: (milestoneId: string) => void;
  onAddParallel: (milestoneId: string) => void;
  onEditSubtask: (milestoneId: string, subtaskIndex: number) => void;
  onUpdateName: (milestoneId: string, newName: string) => void;
  onClick: () => void;
}

export const MilestoneNode: React.FC<MilestoneNodeProps> = ({
  milestone,
  showSubtasks,
  onAddSubtask,
  onAddSequence,
  onAddParallel,
  onEditSubtask,
  onUpdateName,
  onClick
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempName, setTempName] = useState(milestone.name);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [isEditing]);

  const handleBlur = () => {
    setIsEditing(false);
    if (tempName.trim() && tempName !== milestone.name) {
      onUpdateName(milestone.id, tempName);
    } else {
      setTempName(milestone.name);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleBlur();
    if (e.key === 'Escape') {
      setIsEditing(false);
      setTempName(milestone.name);
    }
  };

  return (
    <div 
      className="absolute flex flex-col items-center group"
      style={{ left: milestone.x, top: milestone.y, transform: 'translate(-50%, -50%)' }}
    >
      <div className="mb-2 h-7 flex items-center justify-center">
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            className="text-sm font-semibold text-slate-900 bg-white border border-indigo-300 rounded px-2 py-0.5 shadow-sm outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px]"
            value={tempName}
            onChange={(e) => setTempName(e.target.value)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
          />
        ) : (
          <div 
            onClick={() => setIsEditing(true)}
            className="flex items-center gap-1.5 cursor-pointer hover:bg-slate-100 px-2 py-0.5 rounded-full transition-colors group/name"
          >
            <span className="text-sm font-semibold text-slate-700 whitespace-nowrap">
              {milestone.name}
            </span>
            <Edit2 size={10} className="text-slate-400 opacity-0 group-hover/name:opacity-100 transition-opacity" />
          </div>
        )}
      </div>

      <div 
        className="relative cursor-pointer transition-transform hover:scale-105 active:scale-95"
        onClick={onClick}
      >
        <div className="rounded-full bg-white shadow-lg ring-1 ring-slate-200">
          <MilestonePieChart subtasks={milestone.subtasks} size={100} />
        </div>

        <div className="absolute -right-12 top-0 flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => { e.stopPropagation(); onAddSequence(milestone.id); }}
            className="p-1.5 bg-blue-600 text-white rounded-full shadow-md hover:bg-blue-700"
            title="Add Sequence Milestone"
          >
            <ChevronRight size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onAddParallel(milestone.id); }}
            className="p-1.5 bg-indigo-600 text-white rounded-full shadow-md hover:bg-indigo-700"
            title="Add Parallel Milestone"
          >
            <Plus size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onAddSubtask(milestone.id); }}
            className="p-1.5 bg-emerald-600 text-white rounded-full shadow-md hover:bg-emerald-700"
            title="Add Subtask"
          >
            <Plus size={14} />
          </button>
        </div>
      </div>

      {showSubtasks && milestone.subtasks.length > 0 && (
        <div className="mt-4 w-48 bg-white rounded-lg shadow-md border border-slate-100 p-2 z-10">
          <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 border-b pb-1">
            Subtasks ({milestone.subtasks.length})
          </div>
          <div className="flex flex-col gap-1">
            {milestone.subtasks.map((task, idx) => (
              <div 
                key={task.id} 
                onClick={(e) => { e.stopPropagation(); onEditSubtask(milestone.id, idx); }}
                className="text-xs p-1.5 rounded bg-slate-50 hover:bg-slate-100 cursor-pointer flex items-center justify-between group/task"
              >
                <div className="flex flex-col flex-1 min-w-0">
                  <span className="font-medium truncate text-slate-700">{task.name}</span>
                  <span className="text-[9px] text-slate-400 flex items-center gap-1">
                    <User size={8} /> {task.assignedTo || 'Unassigned'}
                  </span>
                </div>
                <div 
                  className="w-2 h-2 rounded-full shrink-0" 
                  style={{ backgroundColor: getStatusBorderColor(task.status) }} 
                />
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

