                  <div className="flex gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
                    {p.milestones.slice(0, 4).map(m => (
                      <div key={m.id} className="shrink-0 flex flex-col items-center">
                        <div className="w-8 h-8 rounded-full bg-slate-50 ring-1 ring-slate-100 flex items-center justify-center">
                          <div 
                            className="w-5 h-5 rounded-full" 
                            style={{ 
                              background: `conic-gradient(#22c55e ${Math.round((m.subtasks.filter(s => s.status === 'Complete').length / (m.subtasks.length || 1)) * 360)}deg, #f1f5f9 0deg)`
                            }}
                          />
                        </div>
                      </div>
                    ))}
                    {p.milestones.length > 4 && (
                      <div className="shrink-0 w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-[10px] font-bold text-slate-400">
                        +{p.milestones.length - 4}
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => setSelectedProjectId(p.id)}
                      className="flex-1 bg-slate-50 hover:bg-indigo-50 hover:text-indigo-600 text-slate-700 font-semibold py-2 rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
                    >
                      <Eye size={16} /> Open
                    </button>
                    <button 
                      onClick={() => handleDuplicateProject(p.id)}
                      className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                      title="Duplicate"
                    >
                      <Copy size={16} />
                    </button>
                    <button 
                      onClick={() => handleDeleteProject(p.id)}
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <X size={16} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="h-full w-full flex flex-col bg-slate-50 overflow-hidden">
            <div className="bg-white border-b border-slate-200 px-6 py-3 flex items-center justify-between shadow-sm z-20">
              <div>
                <h2 className="text-lg font-bold text-slate-900">{activeProject?.name}</h2>
                <p className="text-xs text-slate-500">{activeProject?.company} • {activeProject?.type}</p>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => setShowSubtasks(!showSubtasks)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold transition-colors ${
                    showSubtasks ? 'bg-indigo-50 text-indigo-700' : 'bg-slate-50 text-slate-600'
                  }`}
                >
                  {showSubtasks ? <Eye size={16} /> : <EyeOff size={16} />}
                  {showSubtasks ? 'Hide Subtasks' : 'Show Subtasks'}
                </button>
                <button 
                   onClick={() => activeProject && handleAddMilestone(activeProject.id, null, false)}
                   className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-4 py-1.5 rounded-lg text-sm flex items-center gap-2 shadow-sm transition-all"
                >
                  <Plus size={16} /> Add Start Milestone
                </button>
              </div>
            </div>

            <div className="flex-1 relative overflow-auto mindmap-container bg-[#fcfcfd]">
              <div 
                className="relative" 
                style={{ 
                  width: canvasData.width, 
                  height: canvasData.height 
                }}
              >
                <svg 
                  className="absolute inset-0 pointer-events-none" 
                  width={canvasData.width} 
                  height={canvasData.height}
                >
                  <defs>
                    <marker id="arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
                      <path d="M 0 0 L 10 5 L 0 10 z" fill="#cbd5e1" />
                    </marker>
                  </defs>
                  {canvasData.milestones.map(m => (
                    m.dependsOn.map(parentId => {
                      const parent = canvasData.milestones.find(mil => mil.id === parentId);
                      if (!parent) return null;
                      const dx = m.x! - parent.x!;
                      const controlX = parent.x! + dx / 2;
                      return (
                        <path
                          key={`${parentId}-${m.id}`}
                          d={`M ${parent.x! + 50} ${parent.y!} C ${controlX} ${parent.y!}, ${controlX} ${m.y!}, ${m.x! - 50} ${m.y!}`}
                          stroke="#cbd5e1"
                          strokeWidth="2"
                          fill="transparent"
                          markerEnd="url(#arrow)"
                        />
                      );
                    })
                  ))}
                </svg>

                <div className="absolute inset-0 pointer-events-none">
                  {canvasData.milestones.map(m => (
                    <div key={m.id} className="pointer-events-auto">
                      <MilestoneNode 
                        milestone={m}
                        showSubtasks={showSubtasks}
                        onAddSubtask={handleAddSubtask}
                        onAddSequence={(id) => handleAddMilestone(activeProject!.id, id, false)}
                        onAddParallel={(id) => handleAddMilestone(activeProject!.id, id, true)}
                        onEditSubtask={(mId, sIdx) => setIsEditingSubtask({ mId, sIdx })}
                        onUpdateName={handleUpdateMilestoneName}
                        onClick={() => {}}
                      />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Global Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Settings className="text-indigo-600" />
                <h3 className="text-xl font-bold text-slate-900">Global Settings</h3>
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-lg transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="flex-1 overflow-auto p-8 grid grid-cols-1 md:grid-cols-2 gap-8">
              <SettingsSection 
                title="Project Types" 
                icon={<Tags size={18} />}
                items={settings.projectTypes} 
                onAdd={(v) => updateSettingsList('projectTypes', v, 'add')} 
                onRemove={(v) => updateSettingsList('projectTypes', v, 'remove')} 
              />
              <SettingsSection 
                title="Companies" 
                icon={<Building size={18} />}
                items={settings.companies} 
                onAdd={(v) => updateSettingsList('companies', v, 'add')} 
                onRemove={(v) => updateSettingsList('companies', v, 'remove')} 
              />
              <SettingsSection 
                title="Team Members" 
                icon={<User size={18} />}
                items={settings.people} 
                onAdd={(v) => updateSettingsList('people', v, 'add')} 
                onRemove={(v) => updateSettingsList('people', v, 'remove')} 
              />
              <SettingsSection 
                title="Task Statuses" 
                icon={<CheckCircle2 size={18} />}
                items={settings.statuses} 
                onAdd={(v) => updateSettingsList('statuses', v, 'add')} 
                onRemove={(v) => updateSettingsList('statuses', v, 'remove')} 
              />
            </div>
          </div>
        </div>
      )}

      {/* New Project Modal */}
      {isCreatingProject && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-8 overflow-hidden relative border border-slate-200">
            {isGenerating && (
              <div className="absolute inset-0 bg-white/80 z-10 flex flex-col items-center justify-center">
                <Wand2 className="w-12 h-12 text-indigo-600 animate-pulse mb-4" />
                <p className="text-indigo-900 font-bold">Gemini is brainstorming...</p>
                <p className="text-slate-500 text-sm">Drafting milestones and subtasks</p>
              </div>
            )}
            <h3 className="text-2xl font-bold text-slate-900 mb-6">Create New Project</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Project Name</label>
                <input 
                  type="text" 
                  className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                  value={newProject.name}
                  onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                  placeholder="e.g. Skyline Towers Phase 1"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Company</label>
                <select 
                  className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                  value={newProject.company}
                  onChange={(e) => setNewProject({ ...newProject, company: e.target.value })}
                >
                  <option value="">Select Company...</option>
                  {settings.companies.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Project Type</label>
                <select 
                  className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                  value={newProject.type}
                  onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}
                >
                  <option value="">Select Type...</option>
                  {settings.projectTypes.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4 mt-8">
                <button 
                  onClick={() => setIsCreatingProject(false)}
                  className="bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-3 rounded-xl transition-colors shadow-sm"
                >
                  Cancel
                </button>
                <div className="flex flex-col gap-2">
                  <button 
                    onClick={() => handleCreateProject(false)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2 shadow-md transition-all active:scale-95"
                  >
                    Manual
                  </button>
                  <button 
                    onClick={() => handleCreateProject(true)}
                    className="bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold py-2 rounded-xl text-[10px] flex items-center justify-center gap-2 border border-amber-200 transition-colors shadow-sm"
                  >
                    <Wand2 size={12} /> AI Assisted
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Subtask Editor Modal */}
      {isEditingSubtask && activeProject && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg p-8 border border-slate-200">
            {(() => {
              const { mId, sIdx } = isEditingSubtask;
              if (sIdx === null) return null;
              const milestone = activeProject.milestones.find(m => m.id === mId);
              const subtask = milestone?.subtasks[sIdx];
              if (!subtask) return null;

              return (
                <>
                  <h3 className="text-xl font-bold text-slate-900 mb-6">Edit Subtask</h3>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">Name</label>
                      <input 
                        type="text" 
                        className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                        value={subtask.name}
                        onChange={(e) => updateSubtask(mId, sIdx, { name: e.target.value })}
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-semibold text-slate-700 mb-1">Assignee</label>
                        <select 
                          className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                          value={subtask.assignedTo}
                          onChange={(e) => updateSubtask(mId, sIdx, { assignedTo: e.target.value })}
                        >
                          <option value="">Unassigned</option>
                          {settings.people.map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-semibold text-slate-700 mb-1">Status</label>
                        <select 
                          className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                          value={subtask.status}
                          onChange={(e) => updateSubtask(mId, sIdx, { status: e.target.value })}
                        >
                          {settings.statuses.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">Description</label>
                      <textarea 
                        className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 h-24 outline-none focus:ring-2 focus:ring-indigo-500 resize-none text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                        value={subtask.description}
                        onChange={(e) => updateSubtask(mId, sIdx, { description: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">Notes</label>
                      <textarea 
                        className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 h-20 outline-none focus:ring-2 focus:ring-indigo-500 resize-none text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                        value={subtask.notes}
                        onChange={(e) => updateSubtask(mId, sIdx, { notes: e.target.value })}
                      />
                    </div>
                    <div className="flex gap-4 mt-8">
                      <button 
                        onClick={() => {
                          if (confirm('Delete this subtask?')) {
                            setProjects(prev => prev.map(p => {
                              if (p.id !== selectedProjectId) return p;
                              return {
                                ...p,
                                milestones: p.milestones.map(m => {
                                  if (m.id !== mId) return m;
                                  return { ...m, subtasks: m.subtasks.filter((_, i) => i !== sIdx) };
                                })
                              };
                            }));
                            setIsEditingSubtask(null);
                          }
                        }}
                        className="bg-red-50 text-red-600 hover:bg-red-100 font-bold py-3 px-6 rounded-xl transition-colors shadow-sm"
                      >
                        Delete
                      </button>
                      <button 
                        onClick={() => setIsEditingSubtask(null)}
                        className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-md transition-all active:scale-95"
                      >
                        Done
                      </button>
                    </div>
                  </div>
                </>
              );
            })()}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Project, 
  Milestone, 
  Subtask, 
  AppSettings 
} from './types';
import { MilestoneNode } from './components/MilestoneNode';
import { 
  Plus, 
  Layers, 
  Copy, 
  Filter, 
  Eye, 
  EyeOff, 
  ChevronLeft,
  Search,
  Settings,
  Briefcase,
  Building,
  Wand2,
  X,
  User,
  Tags,
  CheckCircle2,
  Download,
  Upload,
  AlertTriangle
} from 'lucide-react';
import { geminiService } from './services/geminiService';
import { getStatusBorderColor } from './constants';

const STORAGE_KEY = 'projectflow_data_v2';

const DEFAULT_SETTINGS: AppSettings = {
  projectTypes: ['Subdivision', 'Greenfield Development', 'Commercial', 'Residential', 'Other'],
  companies: ['Vertex Holdings', 'Global Assets', 'Skyline Partners'],
  people: ['John Doe', 'Jane Smith', 'Alex Johnson'],
  statuses: ['Not Complete', 'Started', 'Held', 'Complete']
};

const SettingsSection: React.FC<{ 
  title: string; 
  icon: React.ReactNode;
  items: string[]; 
  onAdd: (v: string) => void; 
  onRemove: (v: string) => void 
}> = ({ title, icon, items, onAdd, onRemove }) => {
  const [inputValue, setInputValue] = useState('');
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center gap-2 text-slate-800 font-bold mb-1 border-b border-slate-100 pb-2">
        {icon}
        {title}
      </div>
      <div className="flex gap-2">
        <input 
          type="text" 
          className="flex-1 bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-900 placeholder-slate-400 outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          placeholder={`Add new ${title.toLowerCase()}...`}
          onKeyDown={(e) => { if(e.key === 'Enter') { onAdd(inputValue); setInputValue(''); }}}
        />
        <button 
          onClick={() => { onAdd(inputValue); setInputValue(''); }}
          className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 transition-colors shadow-sm"
        >
          <Plus size={20} />
        </button>
      </div>
      <div className="flex flex-wrap gap-2 mt-1">
        {items.map(item => (
          <div key={item} className="bg-slate-100 text-slate-700 text-xs px-2 py-1 rounded-md flex items-center gap-2 group border border-slate-200">
            {item}
            <button onClick={() => onRemove(item)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all">
              <X size={12} />
            </button>
          </div>
        ))}
        {items.length === 0 && <span className="text-xs text-slate-400 italic">No items defined</span>}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [showSubtasks, setShowSubtasks] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Filtering
  const [filterType, setFilterType] = useState<string>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  // Modals
  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [isEditingSubtask, setIsEditingSubtask] = useState<{ mId: string, sIdx: number | null } | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  // New project state
  const [newProject, setNewProject] = useState({ name: '', company: '', type: '' });

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setProjects(parsed.projects || []);
        setSettings(parsed.settings || DEFAULT_SETTINGS);
      } catch (e) {
        console.error("Failed to load state", e);
      }
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, settings }));
  }, [projects, settings]);

  const activeProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
    [projects, selectedProjectId]
  );

  const handleExportBackup = () => {
    const data = { projects, settings, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `projectflow-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImportBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parsed = JSON.parse(content);

        if (!parsed.projects || !parsed.settings) {
          throw new Error("Invalid backup file format.");
        }

        if (confirm("This will overwrite all current projects and settings with the backup data. Are you sure?")) {
          setProjects(parsed.projects);
          setSettings(parsed.settings);
          alert("Backup restored successfully!");
        }
      } catch (err) {
        alert("Failed to restore backup: " + (err instanceof Error ? err.message : "Unknown error"));
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleCreateProject = async (useAI = false) => {
    if (!newProject.name) return;
    setIsGenerating(true);

    let milestones: Milestone[] = [];

    if (useAI) {
      const res = await geminiService.generateProjectStructure(newProject.name, newProject.type as any);
      if (res && res.milestones) {
        milestones = res.milestones.map((m: any) => ({
          ...m,
          subtasks: m.subtasks.map((s: any) => ({
            id: Math.random().toString(36).substr(2, 9),
            name: s.name,
            description: s.description,
            assignedTo: '',
            notes: '',
            status: 'Not Complete'
          }))
        }));
      }
    } else {
      milestones = [{
        id: 'm1',
        name: 'Initial Concept',
        dependsOn: [],
        subtasks: [{
          id: 's1',
          name: 'Define Scope',
          description: 'Basic requirements gather',
          assignedTo: '',
          notes: '',
          status: 'Not Complete'
        }]
      }];
    }

    const project: Project = {
      id: Date.now().toString(),
      name: newProject.name,
      company: newProject.company || settings.companies[0],
      type: newProject.type || settings.projectTypes[0],
      milestones,
      createdAt: Date.now()
    };

    setProjects([...projects, project]);
    setSelectedProjectId(project.id);
    setIsCreatingProject(false);
    setIsGenerating(false);
    setNewProject({ name: '', company: '', type: '' });
  };

  const handleUpdateMilestoneName = (mId: string, newName: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        milestones: p.milestones.map(m => m.id === mId ? { ...m, name: newName } : m)
      };
    }));
  };

  const handleDuplicateProject = (id: string) => {
    const p = projects.find(proj => proj.id === id);
    if (!p) return;
    const newP = { ...p, id: Date.now().toString(), name: `${p.name} (Copy)`, createdAt: Date.now() };
    setProjects([...projects, newP]);
  };

  const handleDeleteProject = (id: string) => {
    if (confirm('Delete this project?')) {
      setProjects(projects.filter(p => p.id !== id));
      if (selectedProjectId === id) setSelectedProjectId(null);
    }
  };

  const handleAddMilestone = (pId: string, parentId: string | null, isParallel: boolean) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== pId) return p;
      const newId = `m-${Date.now()}`;
      const newMilestone: Milestone = {
        id: newId,
        name: isParallel ? 'New Parallel Branch' : 'Next Milestone',
        dependsOn: parentId ? [parentId] : [],
        subtasks: [{
          id: `s-${Date.now()}`,
          name: 'Default Subtask',
          description: '',
          assignedTo: '',
          notes: '',
          status: 'Not Complete'
        }]
      };
      return { ...p, milestones: [...p.milestones, newMilestone] };
    }));
  };

  const handleAddSubtask = (mId: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          return {
            ...m,
            subtasks: [...m.subtasks, {
              id: `s-${Date.now()}`,
              name: 'New Subtask',
              description: '',
              assignedTo: '',
              notes: '',
              status: 'Not Complete'
            }]
          };
        })
      };
    }));
  };

  const updateSubtask = (mId: string, sIdx: number, updates: Partial<Subtask>) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          const newSubtasks = [...m.subtasks];
          newSubtasks[sIdx] = { ...newSubtasks[sIdx], ...updates };
          return { ...m, subtasks: newSubtasks };
        })
      };
    }));
  };

  const canvasData = useMemo(() => {
    if (!activeProject) return { milestones: [], width: 0, height: 0 };

    const levels: Record<string, number> = {};
    const getLevel = (id: string): number => {
      if (levels[id] !== undefined) return levels[id];
      const m = activeProject.milestones.find(mil => mil.id === id);
      if (!m || m.dependsOn.length === 0) {
        levels[id] = 0;
        return 0;
      }
      const parentLevels = m.dependsOn.map(parentId => getLevel(parentId));
      levels[id] = Math.max(...parentLevels) + 1;
      return levels[id];
    };

    activeProject.milestones.forEach(m => getLevel(m.id));

    const groupedByLevel: Record<number, string[]> = {};
    Object.entries(levels).forEach(([id, level]) => {
      if (!groupedByLevel[level]) groupedByLevel[level] = [];
      groupedByLevel[level].push(id);
    });

    const HORIZONTAL_GAP = 320;
    const VERTICAL_GAP = 220;
    const PADDING_X = 200;
    const PADDING_Y = 200;

    const maxLevel = Math.max(...Object.values(levels), 0);
    const maxInLevel = Math.max(...Object.values(groupedByLevel).map(g => g.length), 0);

    const calculatedWidth = (maxLevel + 1) * HORIZONTAL_GAP + PADDING_X * 2;
    const calculatedHeight = (maxInLevel + 1) * VERTICAL_GAP + PADDING_Y * 2;

    const width = Math.max(calculatedWidth, 1800);
    const height = Math.max(calculatedHeight, 1000);

    const startX = PADDING_X;
    const centerY = height / 2;

    const milestones = activeProject.milestones.map(m => {
      const level = levels[m.id];
      const indexInLevel = groupedByLevel[level].indexOf(m.id);
      const totalInLevel = groupedByLevel[level].length;

      const x = startX + level * HORIZONTAL_GAP;
      const y = centerY + (indexInLevel - (totalInLevel - 1) / 2) * VERTICAL_GAP;

      return { ...m, x, y };
    });

    return { milestones, width, height };
  }, [activeProject]);

  const filteredProjects = projects.filter(p => {
    const matchesType = filterType === 'ALL' || p.type === filterType;
    const matchesSearch = p.company.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         p.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesType && matchesSearch;
  });

  const updateSettingsList = (key: keyof AppSettings, value: string, action: 'add' | 'remove') => {
    setSettings(prev => {
      const list = [...prev[key]];
      if (action === 'add' && value.trim() && !list.includes(value)) {
        list.push(value);
      } else if (action === 'remove') {
        const index = list.indexOf(value);
        if (index > -1) list.splice(index, 1);
      }
      return { ...prev, [key]: list };
    });
  };

  return (
    <div className="min-h-screen flex flex-col text-slate-900 bg-slate-50">
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-50 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg text-white">
            <Layers size={24} />
          </div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">ProjectFlow</h1>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
            title="Global Settings"
          >
            <Settings size={20} />
          </button>
          {selectedProjectId && (
            <button 
              onClick={() => setSelectedProjectId(null)}
              className="flex items-center gap-2 text-slate-500 hover:text-slate-800 font-medium px-3 py-1.5 rounded-lg transition-colors"
            >
              <ChevronLeft size={18} /> Dashboard
            </button>
          )}
          <button 
            onClick={() => setIsCreatingProject(true)}
            className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all active:scale-95"
          >
            <Plus size={18} /> New Project
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative">
        {!selectedProjectId ? (
          <div className="p-8 max-w-7xl mx-auto h-full overflow-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
              <h2 className="text-2xl font-bold text-slate-800">Your Projects</h2>
              <div className="flex flex-wrap items-center gap-3">
                <div className="relative">
                  <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input 
                    type="text"
                    placeholder="Search company or name..."
                    className="bg-white border border-slate-300 rounded-lg pl-9 pr-4 py-1.5 text-sm text-slate-900 placeholder-slate-400 outline-none focus:ring-2 focus:ring-indigo-500 w-64 shadow-sm"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                </div>
                <div className="flex items-center gap-2">
                  <Filter size={18} className="text-slate-400" />
                  <select 
                    className="bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-sm text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
                    value={filterType}
                    onChange={(e) => setFilterType(e.target.value)}
                  >
                    <option value="ALL">All Types</option>
                    {settings.projectTypes.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredProjects.map(p => (
                <div 
                  key={p.id}
                  className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow group relative"
                >
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="text-lg font-bold text-slate-900 leading-tight mb-1">{p.name}</h3>
                      <div className="flex items-center gap-1.5 text-slate-500 text-sm">
                        <Building size={14} />
                        <span>{p.company}</span>
                      </div>
                    </div>
                    <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-100">
                      {p.type}
                    </span>
                  </div>

                  <div className="flex gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
                    {p.milestones.slice(0, 4).map(m => (
                      <div key={m.id} className="shrink-0 flex flex-col items-center">
                        <div className="w-8 h-8 rounded-full bg-slate-50 ring-1 ring-slate-100 flex items-center justify-center">
                          <div 
                            className="w-5 h-5 rounded-full" 
                            style={{ 
                              background: `conic-gradient(#22c55e ${Math.round((m.subtasks.filter(s => s.status === 'Complete').length / (m.subtasks.length || 1)) * 360)}deg, #f1f5f9 0deg)`
                            }}
                          />
                        </div>
                      </div>
                    ))}
                    {p.milestones.length > 4 && (
                      <div className="shrink-0 w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-[10px] font-bold text-slate-400">
                        +{p.milestones.length - 4}
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => setSelectedProjectId(p.id)}
                      className="flex-1 bg-slate-50 hover:bg-indigo-50 hover:text-indigo-600 text-slate-700 font-semibold py-2 rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
                    >
                      <Eye size={16} /> Open
                    </button>
                    <button 
                      onClick={() => handleDuplicateProject(p.id)}
                      className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"
                      title="Duplicate"
                    >
                      <Copy size={16} />
                    </button>
                    <button 
                      onClick={() => handleDeleteProject(p.id)}
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                      title="Delete"
                    >
                      <X size={16} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="h-full w-full flex flex-col bg-slate-50 overflow-hidden">
            <div className="bg-white border-b border-slate-200 px-6 py-3 flex items-center justify-between shadow-sm z-20">
              <div>
                <h2 className="text-lg font-bold text-slate-900">{activeProject?.name}</h2>
                <p className="text-xs text-slate-500">{activeProject?.company} • {activeProject?.type}</p>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => setShowSubtasks(!showSubtasks)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold transition-colors ${
                    showSubtasks ? 'bg-indigo-50 text-indigo-700' : 'bg-slate-50 text-slate-600'
                  }`}
                >
                  {showSubtasks ? <Eye size={16} /> : <EyeOff size={16} />}
                  {showSubtasks ? 'Hide Subtasks' : 'Show Subtasks'}
                </button>
                <button 
                   onClick={() => activeProject && handleAddMilestone(activeProject.id, null, false)}
                   className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-4 py-1.5 rounded-lg text-sm flex items-center gap-2 shadow-sm transition-all"
                >
                  <Plus size={16} /> Add Start Milestone
                </button>
              </div>
            </div>

            <div className="flex-1 relative overflow-auto mindmap-container bg-[#fcfcfd]">
              <div 
                className="relative" 
                style={{ 
                  width: canvasData.width, 
                  height: canvasData.height 
                }}
              >
                <svg 
                  className="absolute inset-0 pointer-events-none" 
                  width={canvasData.width} 
                  height={canvasData.height}
                >
                  <defs>
                    <marker id="arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
                      <path d="M 0 0 L 10 5 L 0 10 z" fill="#cbd5e1" />
                    </marker>
                  </defs>
                  {canvasData.milestones.map(m => (
                    m.dependsOn.map(parentId => {
                      const parent = canvasData.milestones.find(mil => mil.id === parentId);
                      if (!parent) return null;
                      const dx = m.x! - parent.x!;
                      const controlX = parent.x! + dx / 2;
                      return (
                        <path
                          key={`${parentId}-${m.id}`}
                          d={`M ${parent.x! + 50} ${parent.y!} C ${controlX} ${parent.y!}, ${controlX} ${m.y!}, ${m.x! - 50} ${m.y!}`}
                          stroke="#cbd5e1"
                          strokeWidth="2"
                          fill="transparent"
                          markerEnd="url(#arrow)"
                        />
                      );
                    })
                  ))}
                </svg>

                <div className="absolute inset-0 pointer-events-none">
                  {canvasData.milestones.map(m => (
                    <div key={m.id} className="pointer-events-auto">
                      <MilestoneNode 
                        milestone={m}
                        showSubtasks={showSubtasks}
                        onAddSubtask={handleAddSubtask}
                        onAddSequence={(id) => handleAddMilestone(activeProject!.id, id, false)}
                        onAddParallel={(id) => handleAddMilestone(activeProject!.id, id, true)}
                        onEditSubtask={(mId, sIdx) => setIsEditingSubtask({ mId, sIdx })}
                        onUpdateName={handleUpdateMilestoneName}
                        onClick={() => {}}
                      />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Global Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Settings className="text-indigo-600" />
                <h3 className="text-xl font-bold text-slate-900">Global Settings</h3>
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-lg transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="flex-1 overflow-auto p-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                <SettingsSection 
                  title="Project Types" 
                  icon={<Tags size={18} />}
                  items={settings.projectTypes} 
                  onAdd={(v) => updateSettingsList('projectTypes', v, 'add')} 
                  onRemove={(v) => updateSettingsList('projectTypes', v, 'remove')} 
                />
                <SettingsSection 
                  title="Companies" 
                  icon={<Building size={18} />}
                  items={settings.companies} 
                  onAdd={(v) => updateSettingsList('companies', v, 'add')} 
                  onRemove={(v) => updateSettingsList('companies', v, 'remove')} 
                />
                <SettingsSection 
                  title="Team Members" 
                  icon={<User size={18} />}
                  items={settings.people} 
                  onAdd={(v) => updateSettingsList('people', v, 'add')} 
                  onRemove={(v) => updateSettingsList('people', v, 'remove')} 
                />
                <SettingsSection 
                  title="Task Statuses" 
                  icon={<CheckCircle2 size={18} />}
                  items={settings.statuses} 
                  onAdd={(v) => updateSettingsList('statuses', v, 'add')} 
                  onRemove={(v) => updateSettingsList('statuses', v, 'remove')} 
                />
              </div>

              {/* Data Management Section */}
              <div className="border-t border-slate-100 pt-8 mt-4">
                <h4 className="text-slate-800 font-bold mb-4 flex items-center gap-2">
                  <Download size={18} className="text-indigo-600" /> Data Management
                </h4>
                <div className="bg-slate-50 rounded-xl p-6 border border-slate-200">
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div className="max-w-md">
                      <p className="text-sm text-slate-600 mb-1">Backup your projects and configuration.</p>
                      <p className="text-xs text-slate-400 italic flex items-center gap-1">
                        <AlertTriangle size={12} className="text-amber-500" />
                        Restoring from a backup will overwrite your current local data.
                      </p>
                    </div>
                    <div className="flex items-center gap-3">
                      <button 
                        onClick={handleExportBackup}
                        className="bg-white border border-slate-300 text-slate-700 font-bold px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-slate-50 transition-colors shadow-sm"
                      >
                        <Download size={18} /> Export Backup
                      </button>

                      <input 
                        type="file" 
                        ref={fileInputRef}
                        onChange={handleImportBackup}
                        accept=".json"
                        className="hidden" 
                      />
                      <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="bg-indigo-600 text-white font-bold px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-indigo-700 transition-colors shadow-sm"
                      >
                        <Upload size={18} /> Import Backup
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* New Project Modal */}
      {isCreatingProject && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-8 overflow-hidden relative border border-slate-200">
            {isGenerating && (
              <div className="absolute inset-0 bg-white/80 z-10 flex flex-col items-center justify-center">
                <Wand2 className="w-12 h-12 text-indigo-600 animate-pulse mb-4" />
                <p className="text-indigo-900 font-bold">Gemini is brainstorming...</p>
                <p className="text-slate-500 text-sm">Drafting milestones and subtasks</p>
              </div>
            )}
            <h3 className="text-2xl font-bold text-slate-900 mb-6">Create New Project</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Project Name</label>
                <input 
                  type="text" 
                  className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                  value={newProject.name}
                  onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                  placeholder="e.g. Skyline Towers Phase 1"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Company</label>
                <select 
                  className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                  value={newProject.company}
                  onChange={(e) => setNewProject({ ...newProject, company: e.target.value })}
                >
                  <option value="">Select Company...</option>
                  {settings.companies.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Project Type</label>
                <select 
                  className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                  value={newProject.type}
                  onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}
                >
                  <option value="">Select Type...</option>
                  {settings.projectTypes.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4 mt-8">
                <button 
                  onClick={() => setIsCreatingProject(false)}
                  className="bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-3 rounded-xl transition-colors shadow-sm"
                >
                  Cancel
                </button>
                <div className="flex flex-col gap-2">
                  <button 
                    onClick={() => handleCreateProject(false)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2 shadow-md transition-all active:scale-95"
                  >
                    Manual
                  </button>
                  <button 
                    onClick={() => handleCreateProject(true)}
                    className="bg-amber-100 hover:bg-amber-200 text-amber-800 font-bold py-2 rounded-xl text-[10px] flex items-center justify-center gap-2 border border-amber-200 transition-colors shadow-sm"
                  >
                    <Wand2 size={12} /> AI Assisted
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Subtask Editor Modal */}
      {isEditingSubtask && activeProject && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg p-8 border border-slate-200">
            {(() => {
              const { mId, sIdx } = isEditingSubtask;
              if (sIdx === null) return null;
              const milestone = activeProject.milestones.find(m => m.id === mId);
              const subtask = milestone?.subtasks[sIdx];
              if (!subtask) return null;

              return (
                <>
                  <h3 className="text-xl font-bold text-slate-900 mb-6">Edit Subtask</h3>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">Name</label>
                      <input 
                        type="text" 
                        className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                        value={subtask.name}
                        onChange={(e) => updateSubtask(mId, sIdx, { name: e.target.value })}
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-semibold text-slate-700 mb-1">Assignee</label>
                        <select 
                          className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                          value={subtask.assignedTo}
                          onChange={(e) => updateSubtask(mId, sIdx, { assignedTo: e.target.value })}
                        >
                          <option value="">Unassigned</option>
                          {settings.people.map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-semibold text-slate-700 mb-1">Status</label>
                        <select 
                          className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-slate-900 font-medium shadow-sm"
                          value={subtask.status}
                          onChange={(e) => updateSubtask(mId, sIdx, { status: e.target.value })}
                        >
                          {settings.statuses.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">Description</label>
                      <textarea 
                        className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 h-24 outline-none focus:ring-2 focus:ring-indigo-500 resize-none text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                        value={subtask.description}
                        onChange={(e) => updateSubtask(mId, sIdx, { description: e.target.value })}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-semibold text-slate-700 mb-1">Notes</label>
                      <textarea 
                        className="w-full bg-white border border-slate-300 rounded-lg px-4 py-2 h-20 outline-none focus:ring-2 focus:ring-indigo-500 resize-none text-slate-900 font-medium placeholder-slate-400 shadow-sm"
                        value={subtask.notes}
                        onChange={(e) => updateSubtask(mId, sIdx, { notes: e.target.value })}
                      />
                    </div>
                    <div className="flex gap-4 mt-8">
                      <button 
                        onClick={() => {
                          if (confirm('Delete this subtask?')) {
                            setProjects(prev => prev.map(p => {
                              if (p.id !== selectedProjectId) return p;
                              return {
                                ...p,
                                milestones: p.milestones.map(m => {
                                  if (m.id !== mId) return m;
                                  return { ...m, subtasks: m.subtasks.filter((_, i) => i !== sIdx) };
                                })
                              };
                            }));
                            setIsEditingSubtask(null);
                          }
                        }}
                        className="bg-red-50 text-red-600 hover:bg-red-100 font-bold py-3 px-6 rounded-xl transition-colors shadow-sm"
                      >
                        Delete
                      </button>
                      <button 
                        onClick={() => setIsEditingSubtask(null)}
                        className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl shadow-md transition-all active:scale-95"
                      >
                        Done
                      </button>
                    </div>
                  </div>
                </>
              );
            })()}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { ProjectType } from "../types";

export class GeminiService {
  async generateProjectStructure(name: string, type: ProjectType) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a logical project structure for a project named "${name}" of type "${type}". 
      The response must be a JSON object containing milestones. 
      Each milestone must have a unique ID, a name, a list of subtasks, and an array of 'dependsOn' milestone IDs to form a sequence or parallel paths.
      Ensure there is at least one start milestone (empty dependsOn).
      Each subtask needs a name, description, and status.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            milestones: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  name: { type: Type.STRING },
                  dependsOn: { type: Type.ARRAY, items: { type: Type.STRING } },
                  subtasks: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        name: { type: Type.STRING },
                        description: { type: Type.STRING }
                      },
                      required: ["name", "description"]
                    }
                  }
                },
                required: ["id", "name", "dependsOn", "subtasks"]
              }
            }
          }
        }
      }
    });

    try {
      const text = response.text;
      if (!text) return null;
      return JSON.parse(text);
    } catch (e) {
      console.error("Failed to parse AI response", e);
      return null;
    }
  }

  async brainstormSubtasks(milestoneName: string, projectContext: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Given a milestone called "${milestoneName}" in a project described as "${projectContext}", suggest 5 critical subtasks that might be required.
      Return a JSON array of objects, each with 'name' and 'description'.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["name", "description"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || "[]");
    } catch (e) {
      return [];
    }
  }
}

