  GREENFIELD = 'Greenfield Development',
  OTHER = 'Other'
}

export interface AppSettings {
  projectTypes: string[];
  companies: string[];
  people: string[];
  statuses: string[];
}

export interface Subtask {
  id: string;
  name: string;
  assignedTo: string;
