import React, { useState, useEffect, useRef } from 'react';
import { Milestone } from '../types';
import { MilestonePieChart } from './PieChart';
import { Plus, ChevronRight, User, Edit2, Wand2, Clock, CalendarCheck, Trash2 } from 'lucide-react';
import { getStatusBorderColor } from '../constants';

interface MilestoneNodeProps {
  milestone: Milestone;
  showSubtasks: boolean;
  onAddSubtask: (milestoneId: string) => void;
  onAddSequence: (milestoneId: string) => void;
  onAddParallel: (milestoneId: string) => void;
  onEditSubtask: (milestoneId: string, subtaskIndex: number) => void;
  onUpdateName: (milestoneId: string, newName: string) => void;
  onUpdateDuration: (milestoneId: string, days: number) => void;
  onDeleteMilestone: (milestoneId: string) => void;
  onBrainstorm: (milestoneId: string) => void;
  onHover: (milestoneId: string | null) => void;
  targetDate?: Date;
  dateFormat: 'DD/MM/YY' | 'MM/DD/YY';
  onClick: () => void;
}

export const MilestoneNode: React.FC<MilestoneNodeProps> = ({
  milestone,
  showSubtasks,
  onAddSubtask,
  onAddSequence,
  onAddParallel,
  onEditSubtask,
  onUpdateName,
  onUpdateDuration,
  onDeleteMilestone,
  onBrainstorm,
  onHover,
  targetDate,
  dateFormat,
  onClick
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempName, setTempName] = useState(milestone.name);
  const [isThinking, setIsThinking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [isEditing]);

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const handleBlur = () => {
    setIsEditing(false);
    if (tempName.trim() && tempName !== milestone.name) {
      onUpdateName(milestone.id, tempName);
    } else {
      setTempName(milestone.name);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleBlur();
    if (e.key === 'Escape') {
      setIsEditing(false);
      setTempName(milestone.name);
    }
  };

  const handleBrainstorm = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsThinking(true);
    await onBrainstorm(milestone.id);
    setIsThinking(false);
  };

  const isComplete = milestone.subtasks.length > 0 && milestone.subtasks.every(s => s.status === 'Complete');

  return (
    <div 
      className="absolute flex flex-col items-center group z-10"
      style={{ left: milestone.x, top: milestone.y, transform: 'translate(-50%, -50%)' }}
      onMouseEnter={() => onHover(milestone.id)}
      onMouseLeave={() => onHover(null)}
    >
      <div className="mb-2 h-7 flex flex-col items-center justify-center">
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            className="text-sm font-semibold text-slate-900 bg-white border border-indigo-300 rounded px-2 py-0.5 shadow-sm outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px]"
            value={tempName}
            onChange={(e) => setTempName(e.target.value)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
          />
        ) : (
          <div 
            onClick={() => setIsEditing(true)}
            className="flex items-center gap-1.5 cursor-pointer hover:bg-white hover:shadow-sm px-2 py-0.5 rounded-full transition-all group/name"
          >
            <span className="text-sm font-semibold text-slate-700 whitespace-nowrap">
              {milestone.name}
            </span>
            <Edit2 size={10} className="text-slate-400 opacity-0 group-hover/name:opacity-100 transition-opacity" />
          </div>
        )}
      </div>

      <div 
        className="relative cursor-pointer transition-all duration-300 hover:scale-110 active:scale-95"
        onClick={onClick}
      >
        <div className={`rounded-full bg-white shadow-xl ring-2 transition-all duration-300 ${isThinking ? 'ring-indigo-400 animate-pulse' : 'ring-slate-100 group-hover:ring-indigo-300'}`}>
          <MilestonePieChart subtasks={milestone.subtasks} size={100} />
        </div>

        {/* Floating Tooltip for Timeline */}
        <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[10px] px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-50 pointer-events-none flex flex-col items-center shadow-lg">
          <div className="flex items-center gap-1">
            <Clock size={10} className="text-indigo-400" />
            <span>Target: {formatDate(targetDate)}</span>
          </div>
          {isComplete && milestone.completedAt && (
            <div className="flex items-center gap-1 mt-1 text-emerald-400">
              <CalendarCheck size={10} />
              <span>Actual: {formatDate(milestone.completedAt)}</span>
            </div>
          )}
          <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-900" />
        </div>

        {/* Quick Actions Panel - Moved further right to avoid task list overlap */}
        <div className="absolute -right-16 top-0 flex flex-col gap-1.5 opacity-0 group-hover:opacity-100 transition-all transform group-hover:translate-x-1 duration-300 z-20">
          <button 
            onClick={handleBrainstorm}
            disabled={isThinking}
            className="p-2 bg-gradient-to-tr from-amber-400 to-amber-500 text-white rounded-full shadow-lg hover:from-amber-500 hover:to-amber-600 active:scale-90 transition-all border border-amber-300/50"
            title="AI Brainstorm Subtasks"
          >
            {/* Fix: Using uppercase Wand2 component */}
            <Wand2 size={14} className={isThinking ? 'animate-spin' : ''} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onAddSequence(milestone.id); }}
            className="p-2 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 active:scale-90 transition-all border border-blue-500"
            title="Next Step"
          >
            <ChevronRight size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onAddParallel(milestone.id); }}
            className="p-2 bg-indigo-600 text-white rounded-full shadow-lg hover:bg-indigo-700 active:scale-90 transition-all border border-indigo-500"
            title="Parallel Step"
          >
            <Plus size={14} />
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onDeleteMilestone(milestone.id); }}
            className="p-2 bg-red-100 text-red-600 rounded-full shadow-lg hover:bg-red-200 active:scale-90 transition-all border border-red-200"
            title="Delete Milestone"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      {showSubtasks && (
        <div className="mt-4 w-52 bg-white rounded-xl shadow-xl border border-slate-100 p-2 z-10 animate-in fade-in slide-in-from-top-2 duration-200">
          <div className="flex items-center justify-between border-b border-slate-50 pb-1.5 px-1 mb-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              Tasks ({milestone.subtasks.length})
            </div>
            <div className="flex items-center gap-1">
               <input 
                type="number" 
                className="w-8 bg-slate-100 rounded text-[9px] font-bold text-slate-600 text-center outline-none focus:ring-1 focus:ring-indigo-500"
                value={milestone.estimatedDuration || 0}
                onChange={(e) => onUpdateDuration(milestone.id, parseInt(e.target.value) || 0)}
                onClick={(e) => e.stopPropagation()}
                title="Estimated Days"
              />
              <span className="text-[9px] font-bold text-slate-400">DAYS</span>
            </div>
          </div>
          <div className="flex flex-col gap-1.5 max-h-48 overflow-y-auto pr-1">
            {milestone.subtasks.map((task, idx) => (
              <div 
                key={task.id} 
                onClick={(e) => { e.stopPropagation(); onEditSubtask(milestone.id, idx); }}
                className="text-xs p-2 rounded-lg bg-slate-50 hover:bg-indigo-50 hover:shadow-sm cursor-pointer flex items-center justify-between group/task transition-all"
              >
                <div className="flex flex-col flex-1 min-w-0 pr-2">
                  <div className="flex items-center justify-between">
                    <span className="font-semibold truncate text-slate-800">{task.name}</span>
                  </div>
                  <span className="text-[9px] text-slate-500 flex items-center gap-1 mt-0.5">
                    <User size={9} /> {task.assignedTo || 'Unassigned'}
                  </span>
                  {task.status === 'Complete' && task.completedAt && (
                    <span className="text-[8px] text-emerald-600 font-medium">Done {formatDate(task.completedAt)}</span>
                  )}
                </div>
                <div 
                  className="w-2.5 h-2.5 rounded-full shrink-0 shadow-sm border border-white" 
                  style={{ backgroundColor: getStatusBorderColor(task.status) }} 
                />
              </div>
            ))}
            <button 
              onClick={(e) => { e.stopPropagation(); onAddSubtask(milestone.id); }}
              className="mt-1 w-full py-1.5 border border-dashed border-slate-200 rounded-lg text-[10px] text-slate-400 font-bold hover:border-indigo-300 hover:text-indigo-500 transition-colors flex items-center justify-center gap-1"
            >
              <Plus size={10} /> NEW TASK
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Project, 
  Milestone, 
  Subtask, 
  AppSettings 
} from './types';
import { MilestoneNode } from './components/MilestoneNode';
import { 
  Plus, 
  Layers, 
  Copy, 
  Filter, 
  Eye, 
  EyeOff, 
  ChevronLeft,
  Search,
  Settings,
  Building,
  Wand2,
  X,
  User,
  Tags,
  CheckCircle2,
  Download,
  Upload,
  AlertTriangle,
  Info,
  Activity,
  Calendar,
  Clock,
  RefreshCw,
  Maximize,
  Type as LucideType
} from 'lucide-react';
import { geminiService } from './services/geminiService';
import { getStatusBorderColor } from './constants';

const STORAGE_KEY = 'projectflow_data_v6';

const DEFAULT_SETTINGS: AppSettings = {
  projectTypes: ['Subdivision', 'Greenfield Development', 'Commercial', 'Residential', 'Other'],
  companies: ['Vertex Holdings', 'Global Assets', 'Skyline Partners'],
  people: ['John Doe', 'Jane Smith', 'Alex Johnson'],
  statuses: ['Not Complete', 'Started', 'Held', 'Complete'],
  dateFormat: 'DD/MM/YY'
};

const SettingsSection: React.FC<{ 
  title: string; 
  icon: React.ReactNode;
  items: string[]; 
  onAdd: (v: string) => void; 
  onRemove: (v: string) => void 
}> = ({ title, icon, items, onAdd, onRemove }) => {
  const [inputValue, setInputValue] = useState('');
  return (
    <div className="flex flex-col gap-3">
      <div className="flex items-center gap-2 text-slate-800 font-bold mb-1 border-b border-slate-100 pb-2">
        {icon}
        {title}
      </div>
      <div className="flex gap-2">
        <input 
          type="text" 
          className="flex-1 bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-900 placeholder-slate-400 outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          placeholder={`Add new ${title.toLowerCase()}...`}
          onKeyDown={(e) => { if(e.key === 'Enter') { onAdd(inputValue); setInputValue(''); }}}
        />
        <button 
          onClick={() => { onAdd(inputValue); setInputValue(''); }}
          className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 transition-colors shadow-sm"
        >
          <Plus size={20} />
        </button>
      </div>
      <div className="flex flex-wrap gap-2 mt-1">
        {items.map(item => (
          <div key={item} className="bg-slate-100 text-slate-700 text-xs px-2 py-1 rounded-md flex items-center gap-2 group border border-slate-200">
            {item}
            <button onClick={() => onRemove(item)} className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all">
              <X size={12} />
            </button>
          </div>
        ))}
        {items.length === 0 && <span className="text-xs text-slate-400 italic">No items defined</span>}
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [showSubtasks, setShowSubtasks] = useState(true);
  const [hoveredMilestoneId, setHoveredMilestoneId] = useState<string | null>(null);

  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [filterType, setFilterType] = useState<string>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [isEditingSubtask, setIsEditingSubtask] = useState<{ mId: string, sIdx: number | null } | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  const [newProject, setNewProject] = useState({ 
    name: '', 
    company: '', 
    type: '', 
    startDate: new Date().toISOString().split('T')[0] 
  });

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return settings.dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setProjects(parsed.projects || []);
        // Merge with DEFAULT_SETTINGS to ensure new keys like dateFormat exist
        setSettings({ ...DEFAULT_SETTINGS, ...parsed.settings });
      } catch (e) {
        console.error("Failed to load state", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, settings }));
  }, [projects, settings]);

  // Fix: Added filteredProjects memo to resolve compilation error and provide dashboard filtering
  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            p.company.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesType = filterType === 'ALL' || p.type === filterType;
      return matchesSearch && matchesType;
    });
  }, [projects, searchQuery, filterType]);

  const activeProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
    [projects, selectedProjectId]
  );

  const canvasData = useMemo(() => {
    if (!activeProject) return { milestones: [], width: 0, height: 0 };
    const levels: Record<string, number> = {};
    const getLevel = (id: string): number => {
      if (levels[id] !== undefined) return levels[id];
      const m = activeProject.milestones.find(mil => mil.id === id);
      if (!m || m.dependsOn.length === 0) {
        levels[id] = 0;
        return 0;
      }
      const parentLevels = m.dependsOn.map(parentId => getLevel(parentId));
      levels[id] = Math.max(...parentLevels) + 1;
      return levels[id];
    };
    activeProject.milestones.forEach(m => getLevel(m.id));
    const groupedByLevel: Record<number, string[]> = {};
    Object.entries(levels).forEach(([id, level]) => {
      if (!groupedByLevel[level]) groupedByLevel[level] = [];
      groupedByLevel[level].push(id);
    });
    const HORIZONTAL_GAP = 360;
    const VERTICAL_GAP = 280;
    const PADDING_X = 400;
    const PADDING_Y = 400;
    const maxLevel = Math.max(...Object.values(levels), 0);
    const maxInLevel = Math.max(...Object.values(groupedByLevel).map(g => g.length), 0);
    const width = Math.max((maxLevel + 1) * HORIZONTAL_GAP + PADDING_X * 2, 2500);
    const height = Math.max((maxInLevel + 1) * VERTICAL_GAP + PADDING_Y * 2, 1800);
    const startX = PADDING_X;
    const centerY = height / 2;

    const milestones = activeProject.milestones.map(m => {
      const level = levels[m.id];
      const indexInLevel = groupedByLevel[level].indexOf(m.id);
      const totalInLevel = groupedByLevel[level].length;
      const x = startX + level * HORIZONTAL_GAP;
      const y = centerY + (indexInLevel - (totalInLevel - 1) / 2) * VERTICAL_GAP;
      return { ...m, x, y };
    });
    return { milestones, width, height };
  }, [activeProject]);

  const centerView = () => {
    if (!containerRef.current || !canvasData.milestones.length) return;
    const containerWidth = containerRef.current.clientWidth;
    const containerHeight = containerRef.current.clientHeight;
    const firstM = canvasData.milestones[0];
    if (firstM) {
      const targetX = containerWidth * 0.2;
      const targetY = containerHeight / 2;
      setPan({
        x: targetX - (firstM.x || 0),
        y: targetY - (firstM.y || 0)
      });
    }
  };

  useEffect(() => {
    if (selectedProjectId) {
      setTimeout(centerView, 50);
    }
  }, [selectedProjectId]);

  const milestoneTimeline = useMemo(() => {
    if (!activeProject) return new Map<string, { targetDate: Date }>();
    const results = new Map<string, { targetDate: Date }>();
    const calculate = (mId: string): Date => {
      const milestone = activeProject.milestones.find(m => m.id === mId);
      if (!milestone) return new Date(activeProject.startDate);
      if (results.has(mId)) return results.get(mId)!.targetDate;

      let maxParentDate = new Date(activeProject.startDate);
      milestone.dependsOn.forEach(parentId => {
        const parentDate = calculate(parentId);
        if (parentDate > maxParentDate) maxParentDate = parentDate;
      });

      const finishDate = new Date(maxParentDate);
      finishDate.setDate(finishDate.getDate() + (milestone.estimatedDuration || 0));
      results.set(mId, { targetDate: finishDate });
      return finishDate;
    };
    activeProject.milestones.forEach(m => calculate(m.id));
    return results;
  }, [activeProject]);

  const projectStats = useMemo(() => {
    if (!activeProject) return null;
    let totalTasks = 0;
    let completedTasks = 0;
    let totalEstimatedDays = 0;
    const statusCount: Record<string, number> = {};

    activeProject.milestones.forEach(m => {
      totalEstimatedDays += (m.estimatedDuration || 0);
      m.subtasks.forEach(s => {
        totalTasks++;
        if (s.status === 'Complete') completedTasks++;
        statusCount[s.status] = (statusCount[s.status] || 0) + 1;
      });
    });

    const finishDate = new Date(activeProject.startDate);
    finishDate.setDate(finishDate.getDate() + totalEstimatedDays);

    return { totalTasks, completedTasks, statusCount, totalEstimatedDays, finishDate };
  }, [activeProject]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if ((e.target as HTMLElement).closest('.pointer-events-auto')) return;
    setIsPanning(true);
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isPanning) return;
    const dx = e.clientX - lastMousePos.current.x;
    const dy = e.clientY - lastMousePos.current.y;
    setPan(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseUp = () => setIsPanning(false);

  const handleExportBackup = () => {
    const data = { projects, settings, timestamp: Date.now() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `projectflow-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImportBackup = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parsed = JSON.parse(content);
        if (!parsed.projects || !parsed.settings) throw new Error("Invalid backup file format.");
        if (confirm("This will overwrite all current projects and settings with the backup data. Are you sure?")) {
          setProjects(parsed.projects);
          setSettings(parsed.settings);
          alert("Backup restored successfully!");
        }
      } catch (err) {
        alert("Failed to restore backup: " + (err instanceof Error ? err.message : "Unknown error"));
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleBrainstormSubtasks = async (mId: string) => {
    if (!activeProject) return;
    const milestone = activeProject.milestones.find(m => m.id === mId);
    if (!milestone) return;
    const newTasks = await geminiService.brainstormSubtasks(milestone.name, activeProject.name);
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          const formattedTasks = newTasks.map((t: any) => ({
            id: Math.random().toString(36).substr(2, 9),
            name: t.name,
            description: t.description,
            assignedTo: '',
            notes: '',
            status: 'Not Complete'
          }));
          return { ...m, subtasks: [...m.subtasks, ...formattedTasks] };
        })
      };
    }));
  };

  const handleCreateProject = async (useAI = false) => {
    if (!newProject.name) return;
    setIsGenerating(true);
    let milestones: Milestone[] = [];
    if (useAI) {
      const res = await geminiService.generateProjectStructure(newProject.name, newProject.type as any);
      if (res && res.milestones) {
        milestones = res.milestones.map((m: any) => ({
          ...m,
          estimatedDuration: 5,
          subtasks: m.subtasks.map((s: any) => ({
            id: Math.random().toString(36).substr(2, 9),
            name: s.name,
            description: s.description,
            assignedTo: '',
            notes: '',
            status: 'Not Complete'
          }))
        }));
      }
    } else {
      milestones = [{
        id: 'm1',
        name: 'Initial Concept',
        dependsOn: [],
        estimatedDuration: 7,
        subtasks: [{
          id: 's1',
          name: 'Define Scope',
          description: 'Basic requirements gather',
          assignedTo: '',
          notes: '',
          status: 'Not Complete'
        }]
      }];
    }

    const now = Date.now();
    const project: Project = {
      id: now.toString(),
      name: newProject.name,
      company: newProject.company || settings.companies[0],
      type: newProject.type || settings.projectTypes[0],
      startDate: new Date(newProject.startDate).getTime(),
      milestones,
      createdAt: now,
      updatedAt: now
    };

    setProjects([...projects, project]);
    setSelectedProjectId(project.id);
    setIsCreatingProject(false);
    setIsGenerating(false);
    setNewProject({ name: '', company: '', type: '', startDate: new Date().toISOString().split('T')[0] });
  };

  const handleUpdateMilestoneName = (mId: string, newName: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones.map(m => m.id === mId ? { ...m, name: newName } : m)
      };
    }));
  };

  const handleUpdateMilestoneDuration = (mId: string, days: number) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones.map(m => m.id === mId ? { ...m, estimatedDuration: days } : m)
      };
    }));
  };

  const handleDeleteMilestone = (mId: string) => {
    if (!confirm('Delete this milestone and all its subtasks? Dependencies will be recalculated.')) return;
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones
          .filter(m => m.id !== mId)
          .map(m => ({
            ...m,
            dependsOn: m.dependsOn.filter(depId => depId !== mId)
          }))
      };
    }));
  };

  const handleDuplicateProject = (id: string) => {
    const p = projects.find(proj => proj.id === id);
    if (!p) return;
    const now = Date.now();
    const newP = { ...p, id: now.toString(), name: `${p.name} (Copy)`, createdAt: now, updatedAt: now };
    setProjects([...projects, newP]);
  };

  const handleDeleteProject = (id: string) => {
    if (confirm('Delete this project?')) {
      setProjects(projects.filter(p => p.id !== id));
      if (selectedProjectId === id) setSelectedProjectId(null);
    }
  };

  const handleAddMilestone = (pId: string, parentId: string | null, isParallel: boolean) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== pId) return p;
      const newId = `m-${Date.now()}`;
      const newMilestone: Milestone = {
        id: newId,
        name: isParallel ? 'New Parallel Branch' : 'Next Milestone',
        dependsOn: parentId ? [parentId] : [],
        estimatedDuration: 5,
        subtasks: []
      };
      return { ...p, updatedAt: Date.now(), milestones: [...p.milestones, newMilestone] };
    }));
  };

  const handleAddSubtask = (mId: string) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          return {
            ...m,
            subtasks: [...m.subtasks, {
              id: `s-${Date.now()}`,
              name: 'New Subtask',
              description: '',
              assignedTo: '',
              notes: '',
              status: 'Not Complete'
            }]
          };
        })
      };
    }));
  };

  const updateSubtask = (mId: string, sIdx: number, updates: Partial<Subtask>) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          const newSubtasks = [...m.subtasks];
          const oldStatus = newSubtasks[sIdx].status;
          const newStatus = updates.status || oldStatus;

          let subtaskCompletedAt = newSubtasks[sIdx].completedAt;
          if (newStatus === 'Complete' && oldStatus !== 'Complete') {
            subtaskCompletedAt = Date.now();
          } else if (newStatus !== 'Complete') {
            subtaskCompletedAt = undefined;
          }

          newSubtasks[sIdx] = { ...newSubtasks[sIdx], ...updates, completedAt: subtaskCompletedAt };

          const allComplete = newSubtasks.length > 0 && newSubtasks.every(s => s.status === 'Complete');
          const milestoneCompletedAt = allComplete ? (m.completedAt || Date.now()) : undefined;

          return { ...m, subtasks: newSubtasks, completedAt: milestoneCompletedAt };
        })
      };
    }));
  };

  const updateSettingsList = (key: keyof AppSettings, value: string, action: 'add' | 'remove') => {
    setSettings(prev => {
      const list = prev[key] as string[];
      let newList = [...list];
      if (action === 'add' && value.trim() && !newList.includes(value)) newList.push(value);
      else if (action === 'remove') {
        const index = newList.indexOf(value);
        if (index > -1) newList.splice(index, 1);
      }
      return { ...prev, [key]: newList };
    });
  };

  return (
    <div className="h-screen w-screen flex flex-col text-slate-900 bg-slate-50 overflow-hidden">
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-50 shadow-sm shrink-0">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg text-white">
            <Layers size={24} />
          </div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">ProjectFlow</h1>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
            title="Global Settings"
          >
            <Settings size={20} />
          </button>
          {selectedProjectId && (
            <button 
              onClick={() => setSelectedProjectId(null)}
