                          const parent = canvasData.milestones.find(mil => mil.id === parentId);
                          if (!parent) return null;
                          const isActive = hoveredMilestoneId === m.id || hoveredMilestoneId === parentId;
                          const dx = (m.x || 0) - (parent.x || 0);
