                <div className="bg-slate-50 rounded-3xl p-8 border border-slate-200">
                  <div className="flex flex-col md:flex-row md:items-center justify-between gap-8">
                    <div className="max-w-md">
                      <p className="text-slate-700 font-semibold mb-2">Full Project Backup</p>
                      <p className="text-sm text-slate-500 leading-relaxed">Download your entire project history and configurations as a secure JSON file. You can restore this at any time to recover your work.</p>
                      <div className="mt-4 flex items-center gap-2 text-amber-600 font-bold text-[10px] bg-amber-50 px-3 py-1.5 rounded-full w-fit border border-amber-100">
                        <AlertTriangle size={14} /> WARNING: IMPORT OVERWRITES ALL LOCAL DATA
                      </div>
                    </div>
                    <div className="flex flex-col gap-3 min-w-[200px]">
                      <button onClick={handleExportBackup} className="bg-white border-2 border-slate-200 text-slate-700 font-black py-3 rounded-2xl flex items-center justify-center gap-2 hover:bg-slate-50 hover:border-indigo-200 transition-all shadow-sm active:scale-95"><Download size={20} /> Export (.json)</button>
                      <input type="file" ref={fileInputRef} onChange={handleImportBackup} accept=".json" className="hidden" />
                      <button onClick={() => fileInputRef.current?.click()} className="bg-indigo-600 text-white font-black py-3 rounded-2xl flex items-center justify-center gap-2 hover:bg-indigo-700 transition-all shadow-indigo-200 shadow-lg active:scale-95"><Upload size={20} /> Import Backup</button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* New Project Modal ... unchanged */}
      {isCreatingProject && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md p-10 overflow-hidden relative border border-slate-200">
            {isGenerating && (
              <div className="absolute inset-0 bg-white/90 z-10 flex flex-col items-center justify-center p-8 text-center animate-in zoom-in duration-300">
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 border border-indigo-100 relative">
                  <Wand2 className="w-10 h-10 text-indigo-600 animate-bounce" />
                  <div className="absolute inset-0 rounded-3xl ring-4 ring-indigo-500/20 animate-ping" />
                </div>
                <p className="text-slate-900 font-black text-xl mb-2">Gemini is Strategizing...</p>
                <p className="text-slate-500 text-sm font-medium">Constructing a dependency map and detailed subtask hierarchy for your project.</p>
              </div>
            )}
            <h3 className="text-2xl font-black text-slate-900 mb-8">Start New Project</h3>
            <div className="space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Project Identity</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 text-slate-900 font-bold placeholder-slate-300 transition-all"
                  value={newProject.name}
                  onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                  placeholder="e.g. Skyline Towers Phase 1"
                />
              </div>
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Project Start Date</label>
                <input 
                  type="date" 
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm transition-all"
                  value={newProject.startDate}
                  onChange={(e) => setNewProject({ ...newProject, startDate: e.target.value })}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Company</label>
                  <select className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm transition-all" value={newProject.company} onChange={(e) => setNewProject({ ...newProject, company: e.target.value })}>
                    <option value="">Select...</option>
                    {settings.companies.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Category</label>
                  <select className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm transition-all" value={newProject.type} onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}>
                    <option value="">Select...</option>
                    {settings.projectTypes.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4 mt-10">
                <button onClick={() => setIsCreatingProject(false)} className="bg-slate-100 hover:bg-slate-200 text-slate-700 font-black py-4 rounded-2xl transition-all active:scale-95 shadow-sm">Cancel</button>
                <div className="flex flex-col gap-2">
                  <button onClick={() => handleCreateProject(false)} className="bg-slate-900 hover:bg-black text-white font-black py-3 rounded-2xl flex items-center justify-center gap-2 shadow-lg transition-all active:scale-95">Manual Setup</button>
                  <button onClick={() => handleCreateProject(true)} className="bg-indigo-600 hover:bg-indigo-700 text-white font-black py-3 rounded-2xl flex items-center justify-center gap-2 shadow-indigo-200 shadow-xl transition-all active:scale-95 border-b-4 border-indigo-800"><Wand2 size={16} /> AI Build</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Edit Subtask Modal ... unchanged */}
      {isEditingSubtask && activeProject && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg p-10 border border-slate-200 animate-in zoom-in duration-200">
            {(() => {
              const { mId, sIdx } = isEditingSubtask;
              if (sIdx === null) return null;
              const milestone = activeProject.milestones.find(m => m.id === mId);
              const subtask = milestone?.subtasks[sIdx];
              if (!subtask) return null;
              return (
                <>
                  <h3 className="text-2xl font-black text-slate-900 mb-8">Edit Task Details</h3>
                  <div className="space-y-5">
                    <div>
                      <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Title</label>
                      <input type="text" className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm transition-all" value={subtask.name} onChange={(e) => updateSubtask(mId, sIdx, { name: e.target.value })} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Owner</label>
                        <select className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm" value={subtask.assignedTo} onChange={(e) => updateSubtask(mId, sIdx, { assignedTo: e.target.value })}>
                          <option value="">Unassigned</option>
                          {settings.people.map(p => <option key={p} value={p}>{p}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Status</label>
                        <select className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm" value={subtask.status} onChange={(e) => updateSubtask(mId, sIdx, { status: e.target.value })}>
                          {settings.statuses.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Description</label>
                      <textarea className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 h-24 outline-none focus:border-indigo-500 resize-none text-slate-900 font-medium shadow-sm" value={subtask.description} onChange={(e) => updateSubtask(mId, sIdx, { description: e.target.value })} />
                    </div>
                    <div>
                      <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Resource Link</label>
                      <input 
                        type="text" 
                        className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold shadow-sm transition-all text-sm" 
                        value={subtask.link || ''} 
                        onChange={(e) => updateSubtask(mId, sIdx, { link: e.target.value })} 
                        placeholder="https://..."
                      />
                    </div>
                    <div className="flex gap-4 mt-10">
                      <button 
                        onClick={() => { 
                          if (window.confirm('Delete this task?')) { 
                            setProjects(prev => prev.map(p => {
                              if (p.id !== selectedProjectId) return p;
                              return {
                                ...p,
                                updatedAt: Date.now(),
                                milestones: p.milestones.map(m => {
                                  if (m.id !== mId) return m;
                                  return {
                                    ...m,
                                    subtasks: m.subtasks.filter((_, i) => i !== sIdx)
                                  };
                                })
                              };
                            }));
                            setIsEditingSubtask(null); 
                          } 
                        }} 
                        className="bg-red-50 text-red-600 hover:bg-red-100 font-black py-4 px-8 rounded-2xl transition-all shadow-sm"
                      >
                        Delete
                      </button>
                      <button onClick={() => setIsEditingSubtask(null)} className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-black py-4 rounded-2xl shadow-indigo-200 shadow-xl transition-all active:scale-95">Save & Close</button>
                    </div>
                  </div>
                </>
              );
            })()}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Milestone } from '../types';
import { MilestonePieChart } from './PieChart';
import { Plus, ChevronRight, User, Edit2, Wand2, Clock, CalendarCheck, Trash2, ExternalLink, Link as LinkIcon } from 'lucide-react';
import { getStatusBorderColor } from '../constants';

interface MilestoneNodeProps {
  milestone: Milestone;
  showSubtasks: boolean;
  onAddSubtask: (milestoneId: string) => void;
  onAddSequence: (milestoneId: string) => void;
  onAddParallel: (milestoneId: string) => void;
  onEditSubtask: (milestoneId: string, subtaskIndex: number) => void;
  onUpdateName: (milestoneId: string, newName: string) => void;
  onUpdateDuration: (milestoneId: string, days: number) => void;
  onDeleteMilestone: (milestoneId: string) => void;
  onBrainstorm: (milestoneId: string) => void;
  onHover: (milestoneId: string | null) => void;

  // Linking props
  onStartLinking: (milestoneId: string) => void;
  onCompleteLinking: (milestoneId: string) => void;
  isLinkingMode: boolean;
  isSource: boolean;

  targetDate?: Date;
  dateFormat: 'DD/MM/YY' | 'MM/DD/YY';
  onClick: () => void;
}

export const MilestoneNode: React.FC<MilestoneNodeProps> = ({
  milestone,
  showSubtasks,
  onAddSubtask,
  onAddSequence,
  onAddParallel,
  onEditSubtask,
  onUpdateName,
  onUpdateDuration,
  onDeleteMilestone,
  onBrainstorm,
  onHover,
  onStartLinking,
  onCompleteLinking,
  isLinkingMode,
  isSource,
  targetDate,
  dateFormat,
  onClick
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempName, setTempName] = useState(milestone.name);
  const [isThinking, setIsThinking] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [isEditing]);

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const handleBlur = () => {
    setIsEditing(false);
    if (tempName.trim() && tempName !== milestone.name) {
      onUpdateName(milestone.id, tempName);
    } else {
      setTempName(milestone.name);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleBlur();
    if (e.key === 'Escape') {
      setIsEditing(false);
      setTempName(milestone.name);
    }
  };

  const handleBrainstorm = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsThinking(true);
    await onBrainstorm(milestone.id);
    setIsThinking(false);
  };

  const handleClick = (e: React.MouseEvent) => {
    if (isLinkingMode) {
      e.stopPropagation();
      // If we are in linking mode, clicking this node means we want to complete the link here
      if (!isSource) {
        onCompleteLinking(milestone.id);
      }
    } else {
      onClick();
    }
  };

  const isComplete = milestone.subtasks.length > 0 && milestone.subtasks.every(s => s.status === 'Complete');

  return (
    <div 
      className={`absolute flex flex-col items-center group z-10 transition-opacity ${isLinkingMode && !isSource ? 'opacity-90 hover:opacity-100' : ''}`}
      style={{ left: milestone.x, top: milestone.y, transform: 'translate(-50%, -50%)' }}
      onMouseEnter={() => onHover(milestone.id)}
      onMouseLeave={() => onHover(null)}
    >
      <div className="mb-2 h-7 flex flex-col items-center justify-center">
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            className="text-sm font-semibold text-slate-900 bg-white border border-indigo-300 rounded px-2 py-0.5 shadow-sm outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px]"
            value={tempName}
            onChange={(e) => setTempName(e.target.value)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
          />
        ) : (
          <div 
            onClick={() => setIsEditing(true)}
            className="flex items-center gap-1.5 cursor-pointer hover:bg-white hover:shadow-sm px-2 py-0.5 rounded-full transition-all group/name"
          >
            <span className="text-sm font-semibold text-slate-700 whitespace-nowrap">
              {milestone.name}
            </span>
            <Edit2 size={10} className="text-slate-400 opacity-0 group-hover/name:opacity-100 transition-opacity" />
          </div>
        )}
      </div>

      {/* Wrapper for Circle and Buttons - Added group/circle to control hover effects more precisely */}
      <div className="relative z-50 group/circle">

        {/* The Circle - Moved interactions here to prevent buttons from scaling on click */}
        <div 
          className={`rounded-full bg-white shadow-xl ring-2 transition-all duration-300 cursor-pointer active:scale-95 
            ${isThinking ? 'ring-indigo-400 animate-pulse' : ''}
            ${isLinkingMode && isSource ? 'ring-4 ring-indigo-500 scale-110' : ''}
            ${isLinkingMode && !isSource ? 'ring-slate-100 hover:ring-indigo-400 hover:scale-110' : 'ring-slate-100 group-hover:ring-indigo-300 group-hover:scale-110'}
          `}
          onClick={handleClick}
        >
          <MilestonePieChart subtasks={milestone.subtasks} size={100} />

          {/* Visual indicator for valid drop target during linking */}
          {isLinkingMode && !isSource && (
            <div className="absolute inset-0 rounded-full bg-indigo-500/10 animate-pulse pointer-events-none" />
          )}
        </div>

        {/* Floating Tooltip for Timeline */}
        {!isLinkingMode && (
          <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[10px] px-2 py-1 rounded opacity-0 group-hover/circle:opacity-100 transition-opacity whitespace-nowrap z-50 pointer-events-none flex flex-col items-center shadow-lg">
            <div className="flex items-center gap-1">
              <Clock size={10} className="text-indigo-400" />
              <span>Target: {formatDate(targetDate)}</span>
            </div>
            {isComplete && milestone.completedAt && (
              <div className="flex items-center gap-1 mt-1 text-emerald-400">
                <CalendarCheck size={10} />
                <span>Actual: {formatDate(milestone.completedAt)}</span>
              </div>
            )}
            <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-900" />
          </div>
        )}

        {/* Quick Actions Panel - Hide during linking mode to prevent confusion */}
        {!isLinkingMode && (
          <div className="absolute left-full top-1/2 -translate-y-1/2 pl-3 flex flex-col gap-1.5 opacity-0 group-hover/circle:opacity-100 transition-all transform group-hover/circle:translate-x-1 duration-300 z-50">
            <button 
              onClick={handleBrainstorm}
              disabled={isThinking}
              className="p-2 bg-gradient-to-tr from-amber-400 to-amber-500 text-white rounded-full shadow-lg hover:from-amber-500 hover:to-amber-600 active:scale-90 transition-all border border-amber-300/50"
              title="AI Brainstorm Subtasks"
            >
              <Wand2 size={14} className={`pointer-events-none ${isThinking ? 'animate-spin' : ''}`} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onAddSequence(milestone.id); }}
              className="p-2 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 active:scale-90 transition-all border border-blue-500"
              title="Next Step"
            >
              <ChevronRight size={14} className="pointer-events-none" />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onAddParallel(milestone.id); }}
              className="p-2 bg-indigo-600 text-white rounded-full shadow-lg hover:bg-indigo-700 active:scale-90 transition-all border border-indigo-500"
              title="Parallel Step"
            >
              <Plus size={14} className="pointer-events-none" />
            </button>
            <button 
              onClick={(e) => { 
                  e.stopPropagation();
                  onStartLinking(milestone.id); 
              }}
              className="p-2 bg-violet-600 text-white rounded-full shadow-lg hover:bg-violet-700 active:scale-90 transition-all border border-violet-500"
              title="Link to Another Milestone"
            >
              <LinkIcon size={14} className="pointer-events-none" />
            </button>
            <button 
              onClick={(e) => { 
                  e.preventDefault();
                  e.stopPropagation(); 
                  onDeleteMilestone(milestone.id); 
              }}
              className="p-2 bg-red-100 text-red-600 rounded-full shadow-lg hover:bg-red-200 active:scale-90 transition-all border border-red-200"
              title="Delete Milestone"
            >
              <Trash2 size={14} className="pointer-events-none" />
            </button>
          </div>
        )}
      </div>

      {showSubtasks && !isLinkingMode && (
        <div className="mt-4 w-52 bg-white rounded-xl shadow-xl border border-slate-100 p-2 z-10 animate-in fade-in slide-in-from-top-2 duration-200">
          <div className="flex items-center justify-between border-b border-slate-50 pb-1.5 px-1 mb-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              Tasks ({milestone.subtasks.length})
            </div>
            <div className="flex items-center gap-1">
               <input 
                type="number" 
                className="w-8 bg-slate-100 rounded text-[9px] font-bold text-slate-600 text-center outline-none focus:ring-1 focus:ring-indigo-500"
                value={milestone.estimatedDuration || 0}
                onChange={(e) => onUpdateDuration(milestone.id, parseInt(e.target.value) || 0)}
                onClick={(e) => e.stopPropagation()}
                title="Estimated Days"
              />
              <span className="text-[9px] font-bold text-slate-400">DAYS</span>
            </div>
          </div>
          <div className="flex flex-col gap-1.5 max-h-48 overflow-y-auto pr-1">
            {milestone.subtasks.map((task, idx) => (
              <div 
                key={task.id} 
                onClick={(e) => { e.stopPropagation(); onEditSubtask(milestone.id, idx); }}
                className="text-xs p-2 rounded-lg bg-slate-50 hover:bg-indigo-50 hover:shadow-sm cursor-pointer flex items-center justify-between group/task transition-all"
              >
                <div className="flex flex-col flex-1 min-w-0 pr-2">
                  <div className="flex items-center justify-between">
                    <span className="font-semibold truncate text-slate-800">{task.name}</span>
                    {task.link && (
                      <a 
                        href={task.link.startsWith('http') ? task.link : `https://${task.link}`} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        onClick={(e) => e.stopPropagation()}
                        className="text-indigo-400 hover:text-indigo-600 transition-colors p-1"
                        title="Open Resource Link"
                      >
                        <ExternalLink size={10} />
                      </a>
                    )}
                  </div>
                  <span className="text-[9px] text-slate-500 flex items-center gap-1 mt-0.5">
                    <User size={9} /> {task.assignedTo || 'Unassigned'}
                  </span>
                  {task.status === 'Complete' && task.completedAt && (
                    <span className="text-[8px] text-emerald-600 font-medium">Done {formatDate(task.completedAt)}</span>
                  )}
                </div>
                <div 
                  className="w-2.5 h-2.5 rounded-full shrink-0 shadow-sm border border-white" 
                  style={{ backgroundColor: getStatusBorderColor(task.status) }} 
                />
              </div>
            ))}
            <button 
              onClick={(e) => { e.stopPropagation(); onAddSubtask(milestone.id); }}
              className="mt-1 w-full py-1.5 border border-dashed border-slate-200 rounded-lg text-[10px] text-slate-400 font-bold hover:border-indigo-300 hover:text-indigo-500 transition-colors flex items-center justify-center gap-1"
            >
              <Plus size={10} /> NEW TASK
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export enum SubtaskStatus {
  COMPLETE = 'Complete',
  NOT_COMPLETE = 'Not Complete',
  NOT_STARTED = 'Not started',
  STARTED = 'Started',
  HELD = 'Held'
}

export enum ProjectType {
  SUBDIVISION = 'Subdivision',
  GREENFIELD = 'Greenfield Development',
  OTHER = 'Other'
}

export interface AppSettings {
  projectTypes: string[];
  companies: string[];
  people: string[];
  statuses: string[];
  dateFormat: 'DD/MM/YY' | 'MM/DD/YY';
}

export interface Subtask {
  id: string;
  name: string;
  assignedTo: string;
  description: string;
  notes: string;
  status: string;
  link?: string; // optional external resource link
  completedAt?: number; // timestamp when status became 'Complete'
}

export interface Milestone {
  id: string;
  name: string;
  subtasks: Subtask[];
  dependsOn: string[];
  estimatedDuration: number; // in days
  completedAt?: number; // timestamp when all subtasks are complete
  x?: number;
  y?: number;
}

export interface Project {
  id: string;
  name: string;
  company: string;
  type: string;
  startDate: number; // timestamp
  milestones: Milestone[];
  createdAt: number;
  updatedAt: number; // tracks any modification to the project
}

export interface AppState {
  projects: Project[];
  selectedProjectId: string | null;
  showSubtasks: boolean;
  settings: AppSettings;
}

import React from 'react';

// Default mappings for the initial statuses
export const DEFAULT_STATUS_COLORS: Record<string, string> = {
  'Complete': '#dcfce7',
  'Started': '#dbeafe',
  'Held': '#fef9c3',
  'Not Complete': '#f1f5f9',
  'Not started': '#f1f5f9'
};

export const getStatusColor = (status: string) => DEFAULT_STATUS_COLORS[status] || '#f1f5f9';

export const getStatusBorderColor = (status: string) => {
  const borders: Record<string, string> = {
    'Complete': '#22c55e',
    'Started': '#3b82f6',
    'Held': '#eab308',
    'Not Complete': '#94a3b8',
    'Not started': '#94a3b8'
  };
  return borders[status] || '#94a3b8';
};

