      const list = prev[key] as string[];
      let newList = [...list];
      if (action === 'add' && value.trim() && !newList.includes(value)) newList.push(value);
      else if (action === 'remove') {
        const index = newList.indexOf(value);
        if (index > -1) newList.splice(index, 1);
