import { initializeApp } from 'firebase/app';
import { getDatabase, ref, set, onValue } from 'firebase/database';
import { Project, AppSettings } from '../types';

const CONFIG_STORAGE_KEY = 'projectflow_firebase_config';

let db: any = null;
let isConfigured = false;

// specific parsing to handle the user pasting the raw JS object from Firebase console
// which looks like "const firebaseConfig = { ... }" or just "{ ... }"
const parseConfig = (raw: string | null) => {
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (e) {
    // If straight JSON fails, try to strip "const firebaseConfig =" and typical JS syntax
    try {
      const cleaned = raw
        .replace(/const\s+\w+\s*=\s*/, '') // remove const x = 
        .replace(/;/g, '') // remove semicolons
        .replace(/(\w+):/g, '"$1":') // quote keys
        .replace(/'/g, '"'); // replace single quotes
      return JSON.parse(cleaned);
    } catch (e2) {
      return null;
    }
  }
};

try {
  const saved = localStorage.getItem(CONFIG_STORAGE_KEY);
  const config = parseConfig(saved);

  if (config && config.databaseURL) {
    const app = initializeApp(config);
    db = getDatabase(app);
    isConfigured = true;
  }
} catch (e) {
  console.error("Firebase Initialization Error:", e);
}

export const firebaseService = {
  isConfigured: () => isConfigured,

  // Save config and reload to initialize
  configure: (configString: string) => {
    // Validate by trying to parse
    const config = parseConfig(configString);
    if (config && config.databaseURL) {
      localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(config));
      window.location.reload();
      return true;
    }
    return false;
  },

  disconnect: () => {
    localStorage.removeItem(CONFIG_STORAGE_KEY);
    window.location.reload();
  },

  subscribe: (callback: (data: { projects: Project[], settings: AppSettings } | null) => void) => {
    if (!db) return () => {};

    const dataRef = ref(db, 'projectflow_v1');
    return onValue(dataRef, (snapshot) => {
      const data = snapshot.val();
      callback(data);
    });
  },

  save: async (data: { projects: Project[], settings: AppSettings }) => {
    if (!db) return;
    const dataRef = ref(db, 'projectflow_v1');
    await set(dataRef, {
      projects: data.projects || [],
      settings: data.settings,
      lastUpdated: Date.now()
    });
  }
};

