                                    <rect
                                      x={viewportX}
                                      y={viewportY}
                                      width={viewportW}
                                      height={viewportH}
                                      fill="none"
                                      stroke="#6366f1"
                                      strokeWidth="2"
                                      className="transition-all duration-75"
                                    />
                                  </svg>
                                );
