const DEFAULT_SETTINGS: AppSettings = {
  projectTypes: Object.values(ProjectType),
  companies: ['Acme Corp', 'Global Ind', 'TechStart'],
  people: ['Alice', 'Bob', 'Charlie', 'David'],
  statuses: Object.values(SubtaskStatus),
  dateFormat: 'DD/MM/YY'
};

const App: React.FC = () => {
  // --- State ---
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Dashboard State
  const [searchQuery, setSearchQuery] = useState('');
  const [showNewProjectModal, setShowNewProjectModal] = useState(false);
  const [newProjectName, setNewProjectName] = useState('');
  const [newProjectType, setNewProjectType] = useState<ProjectType>(ProjectType.OTHER);
  const [isGenerating, setIsGenerating] = useState(false);

  // Canvas/Project View State
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [isPanning, setIsPanning] = useState(false);
  const [showSubtasks, setShowSubtasks] = useState(true);
  const [linkingSourceId, setLinkingSourceId] = useState<string | null>(null);

  const canvasRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });

  // --- Effects ---

  // Load data from Firebase
  useEffect(() => {
    const unsubscribe = firebaseService.subscribe((data) => {
      if (data) {
        setProjects(data.projects || []);
        if (data.settings) setSettings(data.settings);
      }
    });
    return () => unsubscribe();
  }, []);

  // Save data to Firebase on change (debounced could be better, but simple for now)
  useEffect(() => {
    if (projects.length > 0) {
      firebaseService.save({ projects, settings });
    }
  }, [projects, settings]);

  // --- Computed ---

  const selectedProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
    [projects, selectedProjectId]
  );

  const filteredProjects = useMemo(() => {
    if (!searchQuery) return projects;
    const lower = searchQuery.toLowerCase();
    return projects.filter(p => 
      p.name.toLowerCase().includes(lower) || 
      p.company.toLowerCase().includes(lower)
    );
  }, [projects, searchQuery]);

  // --- Helpers ---

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return settings.dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const updateProject = (projectId: string, updates: Partial<Project>) => {
    setProjects(prev => prev.map(p => 
      p.id === projectId 
        ? { ...p, ...updates, updatedAt: Date.now() } 
        : p
    ));
  };

  // --- Handlers ---

  const handleCreateProject = async () => {
    if (!newProjectName.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const structure = await geminiService.generateProjectStructure(newProjectName, newProjectType);

      if (!structure || !structure.milestones) {
        throw new Error("Failed to generate project structure");
      }

      // Layout milestones in a simple grid initially if no positions
      const milestonesWithPos = structure.milestones.map((m: any, idx: number) => ({
        ...m,
        id: m.id || generateId(),
        subtasks: m.subtasks?.map((s: any) => ({
          ...s,
          id: generateId(),
          status: 'Not started',
          assignedTo: ''
        })) || [],
        dependsOn: m.dependsOn || [],
        x: (idx % 3) * 300,
        y: Math.floor(idx / 3) * 200,
        completedAt: undefined
      }));

      const newProject: Project = {
        id: generateId(),
        name: newProjectName,
        company: settings.companies[0] || 'Unknown',
        type: newProjectType,
        startDate: Date.now(),
        createdAt: Date.now(),
        updatedAt: Date.now(),
        milestones: milestonesWithPos
      };

      setProjects(prev => [...prev, newProject]);
      setShowNewProjectModal(false);
      setNewProjectName('');
    } catch (err) {
      setError("Failed to generate project. Please check your API key and try again.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDuplicateProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    const newProject = {
      ...project,
      id: generateId(),
      name: `${project.name} (Copy)`,
      createdAt: Date.now(),
      updatedAt: Date.now()
    };

    setProjects(prev => [...prev, newProject]);
  };

  const handleDeleteProject = (projectId: string) => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      setProjects(prev => prev.filter(p => p.id !== projectId));
      if (selectedProjectId === projectId) setSelectedProjectId(null);
    }
  };

  // --- Canvas Handlers ---

  const handleCanvasMouseDown = (e: React.MouseEvent) => {
    if (e.button === 0) { // Left click
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleCanvasMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;
      setPan(p => ({ x: p.x + dx, y: p.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleCanvasMouseUp = () => {
    setIsPanning(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey) {
      e.preventDefault();
      const delta = -e.deltaY * 0.001;
      setZoom(z => Math.min(Math.max(0.1, z + delta), 3));
    }
  };

  // --- Milestone Logic ---

  const handleMoveMilestone = (id: string, x: number, y: number) => {
    if (!selectedProjectId) return;

    // Update local state for smooth drag
    const project = projects.find(p => p.id === selectedProjectId);
    if (!project) return;

    const updatedMilestones = project.milestones.map(m => 
      m.id === id ? { ...m, x, y } : m
    );

    updateProject(selectedProjectId, { milestones: updatedMilestones });
  };

  const handleUpdateMilestone = (milestoneId: string, updates: Partial<Milestone>) => {
    if (!selectedProjectId) return;
    const project = projects.find(p => p.id === selectedProjectId);
    if (!project) return;

    const updatedMilestones = project.milestones.map(m => 
      m.id === milestoneId ? { ...m, ...updates } : m
    );

    updateProject(selectedProjectId, { milestones: updatedMilestones });
  };

  const handleBrainstormSubtasks = async (milestoneId: string) => {
    if (!selectedProjectId || !selectedProject) return;

    const milestone = selectedProject.milestones.find(m => m.id === milestoneId);
    if (!milestone) return;

    const suggestions = await geminiService.brainstormSubtasks(
      milestone.name, 
      `${selectedProject.name} (${selectedProject.type})`
    );

    if (suggestions && suggestions.length > 0) {
      const newSubtasks = suggestions.map((s: any) => ({
        id: generateId(),
        name: s.name,
        description: s.description,
        assignedTo: '',
        status: 'Not started',
        notes: ''
      }));

      handleUpdateMilestone(milestoneId, {
        subtasks: [...(milestone.subtasks || []), ...newSubtasks]
      });
    }
  };

  const handleAddMilestone = () => {
    if (!selectedProjectId) return;

    // Calculate center of current view
    const centerX = (-pan.x + (window.innerWidth / 2)) / zoom;
    const centerY = (-pan.y + (window.innerHeight / 2)) / zoom;

    const newMilestone: Milestone = {
      id: generateId(),
      name: 'New Milestone',
      subtasks: [],
      dependsOn: [],
      estimatedDuration: 1,
      x: centerX,
      y: centerY
    };

    const project = projects.find(p => p.id === selectedProjectId);
    if (project) {
      updateProject(selectedProjectId, { milestones: [...project.milestones, newMilestone] });
    }
  };

  // Linking
  const handleStartLinking = (id: string) => setLinkingSourceId(id);
  const handleCompleteLinking = (targetId: string) => {
    if (linkingSourceId && linkingSourceId !== targetId && selectedProjectId) {
      const project = projects.find(p => p.id === selectedProjectId);
      if (project) {
        const targetMilestone = project.milestones.find(m => m.id === targetId);
        if (targetMilestone && !targetMilestone.dependsOn.includes(linkingSourceId)) {
          handleUpdateMilestone(targetId, {
            dependsOn: [...targetMilestone.dependsOn, linkingSourceId]
          });
        }
      }
    }
    setLinkingSourceId(null);
  };

  // --- Render ---

  if (!firebaseService.isConfigured()) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full">
          <h2 className="text-2xl font-bold mb-4 text-slate-900">Configure Firebase</h2>
          <p className="text-slate-600 mb-4">Paste your Firebase configuration object below to get started.</p>
          <textarea 
            className="w-full h-40 border border-slate-300 rounded p-2 text-xs font-mono mb-4"
            placeholder="{ apiKey: ... }"
            onBlur={(e) => firebaseService.configure(e.target.value)}
          />
        </div>
      </div>
    );
  }

  // Project View
  if (selectedProject) {
    return (
      <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
        {/* Header */}
        <div className="bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between z-20 shadow-sm">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setSelectedProjectId(null)}
              className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"
            >
              <ChevronLeft size={20} />
            </button>
            <div>
              <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
                {selectedProject.name}
                <span className="text-xs font-normal text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                  {selectedProject.type}
                </span>
              </h1>
              <div className="flex items-center gap-3 text-xs text-slate-500 mt-0.5">
                <span className="flex items-center gap-1"><Building size={12} /> {selectedProject.company}</span>
                <span className="flex items-center gap-1"><Clock size={12} /> Started {formatDate(selectedProject.startDate)}</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button 
                onClick={() => setZoom(z => Math.max(0.1, z - 0.1))}
                className="p-1.5 hover:bg-white rounded text-slate-600 shadow-sm transition-all"
              ><ZoomOut size={16} /></button>
              <span className="px-2 flex items-center text-xs font-bold text-slate-500 w-12 justify-center">
                {Math.round(zoom * 100)}%
              </span>
              <button 
                onClick={() => setZoom(z => Math.min(3, z + 0.1))}
                className="p-1.5 hover:bg-white rounded text-slate-600 shadow-sm transition-all"
              ><ZoomIn size={16} /></button>
            </div>

            <button 
              onClick={() => setShowSubtasks(!showSubtasks)}
              className={`p-2 rounded-lg border text-sm font-medium transition-all flex items-center gap-2
                ${showSubtasks ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
            >
              <Layout size={16} /> {showSubtasks ? 'Hide Tasks' : 'Show Tasks'}
            </button>

            <button 
              onClick={handleAddMilestone}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-sm transition-all flex items-center gap-2"
            >
              <Plus size={16} /> Add Milestone
            </button>
          </div>
        </div>

        {/* Canvas */}
        <div 
          className="flex-1 relative overflow-hidden bg-slate-50 cursor-move"
          ref={canvasRef}
          onMouseDown={handleCanvasMouseDown}
          onMouseMove={(e) => {
            handleCanvasMouseMove(e);
            // Also pass generic mouse move for dragging nodes logic if needed globally
          }}
          onMouseUp={handleCanvasMouseUp}
          onMouseLeave={handleCanvasMouseUp}
          onWheel={handleWheel}
        >
          {/* Background Grid */}
          <div 
            className="absolute inset-0 pointer-events-none opacity-5"
            style={{
              backgroundImage: 'radial-gradient(#64748b 1px, transparent 1px)',
              backgroundSize: `${20 * zoom}px ${20 * zoom}px`,
              transform: `translate(${pan.x}px, ${pan.y}px)`
            }}
          />

          <div 
            className="absolute inset-0 transform-gpu origin-top-left"
            style={{
              transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`
            }}
          >
            {/* Connection Lines */}
            <svg className="absolute top-0 left-0 w-[5000px] h-[5000px] pointer-events-none overflow-visible">
              <defs>
                <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                  <polygon points="0 0, 10 3.5, 0 7" fill="#cbd5e1" />
                </marker>
              </defs>
              {selectedProject.milestones.map(m => 
                m.dependsOn?.map(targetId => {
                  const target = selectedProject.milestones.find(t => t.id === targetId);
                  if (!target) return null;
                  return (
                    <path
                      key={`${m.id}-${targetId}`}
                      d={`M ${target.x} ${target.y} C ${target.x! + 50} ${target.y}, ${m.x! - 50} ${m.y}, ${m.x} ${m.y}`}
                      stroke="#cbd5e1"
                      strokeWidth="2"
                      fill="none"
                      markerEnd="url(#arrowhead)"
                    />
                  );
                })
              )}
              {linkingSourceId && (
                (() => {
                   // Draw temp line from source to mouse? (Simplified: just highlight nodes)
                   return null;
                })()
              )}
            </svg>

            {/* Nodes */}
            {selectedProject.milestones.map(milestone => (
              <MilestoneNode
                key={milestone.id}
                milestone={milestone}
                showSubtasks={showSubtasks}
                onAddSubtask={(id) => {
                   const m = selectedProject.milestones.find(x => x.id === id);
                   if (m) {
                     const newTask = { 
                       id: generateId(), 
                       name: 'New Task', 
                       description: '', 
                       status: 'Not started', 
                       assignedTo: '',
                       notes: '' 
                     };
                     handleUpdateMilestone(id, { subtasks: [...(m.subtasks || []), newTask] });
                   }
                }}
                onAddSequence={(id) => {
                  const source = selectedProject.milestones.find(x => x.id === id);
                  if (!source) return;
                  const newM: Milestone = {
                    id: generateId(),
                    name: 'New Milestone',
                    subtasks: [],
                    dependsOn: [id],
                    estimatedDuration: 1,
                    x: (source.x || 0) + 300,
                    y: source.y || 0
                  };
                  updateProject(selectedProjectId!, { milestones: [...selectedProject.milestones, newM] });
                }}
                onAddPrevious={(id) => {
                   const source = selectedProject.milestones.find(x => x.id === id);
                   if (!source) return;
                   const newM: Milestone = {
                    id: generateId(),
                    name: 'Previous Step',
                    subtasks: [],
                    dependsOn: [],
                    estimatedDuration: 1,
                    x: (source.x || 0) - 300,
                    y: source.y || 0
                  };
                  // Update current to depend on new
                  const updatedCurrent = { ...source, dependsOn: [...source.dependsOn, newM.id] };
                  const otherMilestones = selectedProject.milestones.filter(m => m.id !== id);
                  updateProject(selectedProjectId!, { milestones: [...otherMilestones, updatedCurrent, newM] });
                }}
                onAddParallel={(id) => {
                   const source = selectedProject.milestones.find(x => x.id === id);
                   if (!source) return;
                   const newM: Milestone = {
                    id: generateId(),
                    name: 'Parallel Step',
                    subtasks: [],
                    dependsOn: source.dependsOn, // Same parent dependencies
                    estimatedDuration: 1,
                    x: (source.x || 0),
                    y: (source.y || 0) + 200
                  };
                  updateProject(selectedProjectId!, { milestones: [...selectedProject.milestones, newM] });
                }}
                onEditSubtask={(mId, sIndex) => {
                   // Simple toggle status for now or prompt name
                   const m = selectedProject.milestones.find(x => x.id === mId);
                   if (!m) return;
                   const task = m.subtasks[sIndex];
                   const nextStatus = task.status === 'Complete' ? 'Not started' : 'Complete';
                   const newSubtasks = [...m.subtasks];
                   newSubtasks[sIndex] = { 
                     ...task, 
                     status: nextStatus, 
                     completedAt: nextStatus === 'Complete' ? Date.now() : undefined 
                   };
                   handleUpdateMilestone(mId, { subtasks: newSubtasks });
                }}
                onUpdateName={(id, name) => handleUpdateMilestone(id, { name })}
                onUpdateDuration={(id, days) => handleUpdateMilestone(id, { estimatedDuration: days })}
                onDeleteMilestone={(id) => {
                   if (window.confirm("Delete this milestone?")) {
                      const updated = selectedProject.milestones.filter(m => m.id !== id);
                      // Remove dependencies on this
                      const cleaned = updated.map(m => ({
                        ...m,
                        dependsOn: m.dependsOn.filter(d => d !== id)
                      }));
                      updateProject(selectedProjectId!, { milestones: cleaned });
                   }
                }}
                onMove={handleMoveMilestone}
                onBrainstorm={handleBrainstormSubtasks}
                onHover={() => {}}
                onStartLinking={handleStartLinking}
                onCompleteLinking={handleCompleteLinking}
                isLinkingMode={!!linkingSourceId}
                isSource={linkingSourceId === milestone.id}
                dateFormat={settings.dateFormat}
                onClick={() => {}}
              />
            ))}
          </div>

          {linkingSourceId && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-indigo-600 text-white px-4 py-2 rounded-full shadow-lg text-sm font-semibold animate-bounce z-50">
              Select a target milestone to link
              <button onClick={() => setLinkingSourceId(null)} className="ml-3 opacity-75 hover:opacity-100 border-l border-indigo-400 pl-2">Cancel</button>
            </div>
          )}
        </div>
      </div>
    );
  }

  // Dashboard View
  return (
    <div className="min-h-screen bg-slate-50 p-6 md:p-8">
      <div className="max-w-7xl mx-auto">

        {/* Dashboard Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">ProjectFlow</h1>
            <p className="text-slate-500 mt-1">Manage your development milestones with AI assistance</p>
          </div>
          <div className="flex items-center gap-3">
             <div className="relative">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
               <input 
                 type="text" 
                 placeholder="Search projects..." 
                 className="pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none w-64 transition-all"
                 value={searchQuery}
                 onChange={(e) => setSearchQuery(e.target.value)}
               />
             </div>
             <button 
               onClick={() => setShowNewProjectModal(true)}
               className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-semibold shadow-sm flex items-center gap-2 transition-all hover:scale-105 active:scale-95"
             >
               <Plus size={18} /> New Project
             </button>
          </div>
        </div>

        {/* Project List */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProjects.map(p => {
            const allTasks = p.milestones.flatMap(m => m.subtasks || []);
            const totalTasks = allTasks.length;
            const completedTasks = allTasks.filter(t => t.status === 'Complete').length;
            const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
            const nextTask = allTasks.find(t => t.status === 'Not started');

            return (
              <div 
                key={p.id}
                className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow group relative flex flex-col"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex-1">
                    <h3 className="text-lg font-bold text-slate-900 leading-tight mb-1">{p.name}</h3>
                    <div className="flex items-center gap-1.5 text-slate-500 text-sm">
                      <Building size={14} />
                      <span>{p.company}</span>
                    </div>
                  </div>
                  <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {p.type}
                  </span>
                </div>

                <div className="flex items-center gap-2 text-[10px] text-slate-400 mb-4">
                  <RefreshCw size={10} />
                  <span>Last updated {formatDate(p.updatedAt)}</span>
                </div>

                {/* Progress & Next Task */}
                <div className="mb-5 space-y-3">
                  <div>
                    <div className="flex justify-between text-xs mb-1.5">
                        <span className="font-bold text-slate-500">Progress</span>
                        <span className="font-bold text-slate-900">{progress}%</span>
                    </div>
                    <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
                      <div 
                          className="bg-gradient-to-r from-indigo-500 to-emerald-500 h-full transition-all duration-500" 
                          style={{ width: `${progress}%` }}
                      />
                    </div>
                  </div>

                  {nextTask ? (
                    <div className="bg-slate-50 border border-slate-100 rounded-lg p-2.5">
                      <div className="flex items-center gap-1.5 text-[10px] font-bold text-indigo-600 uppercase tracking-wider mb-1">
                        <Clock size={10} /> Next Action
                      </div>
                      <div className="flex justify-between items-start gap-2">
                          <span className="text-xs font-semibold text-slate-800 line-clamp-2 leading-tight">
                            {nextTask.name}
                          </span>
                          {nextTask.assignedTo && (
                            <span className="shrink-0 text-[10px] px-2 py-0.5 bg-white border border-slate-200 rounded-full text-slate-500 flex items-center gap-1 shadow-sm">
                              <User size={10} /> {nextTask.assignedTo}
                            </span>
                          )}
                      </div>
                    </div>
                  ) : totalTasks > 0 && progress === 100 ? (
                      <div className="bg-emerald-50 border border-emerald-100 rounded-lg p-2.5 flex items-center gap-2 text-emerald-700">
                        <CheckCircle2 size={14} />
                        <span className="text-xs font-bold">Project Complete</span>
                      </div>
                  ) : (
                      <div className="bg-slate-50 border border-slate-100 rounded-lg p-2.5 text-xs text-slate-400 italic text-center">
                        No tasks pending
                      </div>
                  )}
                </div>

                <div className="flex gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide flex-1">
                  {(p.milestones || []).slice(0, 4).map(m => {
                    const safeSubtasks = m.subtasks || [];
                    const complete = safeSubtasks.filter((s: any) => s.status === 'Complete').length;
                    const total = safeSubtasks.length || 1;
                    const progressDeg = (complete / total) * 360;
                    return (
                      <div key={m.id} className="shrink-0 flex flex-col items-center">
                        <div className="w-8 h-8 rounded-full bg-slate-50 ring-1 ring-slate-100 flex items-center justify-center" title={m.name}>
                          <div 
                            className="w-5 h-5 rounded-full" 
                            style={{ background: `conic-gradient(#22c55e ${progressDeg}deg, #f1f5f9 0deg)` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="flex items-center gap-2 mt-auto">
                  <button 
                    onClick={() => { setSelectedProjectId(p.id); setPan({ x: 0, y: 0 }); }}
                    className="flex-1 bg-slate-50 hover:bg-indigo-50 hover:text-indigo-600 text-slate-700 font-semibold py-2 rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
                  >
                    <Eye size={16} /> Open
                  </button>
                  <button onClick={() => handleDuplicateProject(p.id)} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"><Copy size={16} /></button>
                  <button onClick={() => handleDeleteProject(p.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"><X size={16} /></button>
                </div>
              </div>
            );
          })}

          {/* Empty State */}
          {filteredProjects.length === 0 && (
            <div className="col-span-full py-12 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="font-semibold text-lg">No projects found</p>
              <p className="text-sm">Try creating a new project or adjust your search</p>
            </div>
          )}
        </div>
      </div>

      {/* New Project Modal */}
      {showNewProjectModal && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-xl font-bold text-slate-900">Create New Project</h2>
              <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1.5">Project Name</label>
                <input 
                  type="text" 
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="e.g. Downtown Office Complex"
                  value={newProjectName}
                  onChange={e => setNewProjectName(e.target.value)}
                  autoFocus
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1.5">Project Type</label>
                <div className="grid grid-cols-1 gap-2">
                  {settings.projectTypes.map(t => (
                    <label 
                      key={t}
                      className={`flex items-center px-3 py-2 rounded-lg border cursor-pointer transition-all ${newProjectType === t ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-200 hover:border-slate-300'}`}
                    >
                      <input 
                        type="radio" 
                        name="projectType" 
                        className="sr-only"
                        checked={newProjectType === t}
                        onChange={() => setNewProjectType(t as ProjectType)}
                      />
                      <span className="text-sm font-medium">{t}</span>
                      {newProjectType === t && <CheckCircle2 size={16} className="ml-auto" />}
                    </label>
                  ))}
                </div>
              </div>

              {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-start gap-2">
                  <AlertCircle size={16} className="mt-0.5 shrink-0" />
                  {error}
                </div>
              )}
            </div>

            <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
              <button 
                onClick={() => setShowNewProjectModal(false)}
                className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg"
              >
                Cancel
              </button>
              <button 
                onClick={handleCreateProject}
                disabled={isGenerating || !newProjectName}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-medium rounded-lg shadow-sm flex items-center gap-2"
              >
                {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Wand2Icon />}
                {isGenerating ? 'Generating Structure...' : 'Generate Project'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper component for the button icon
const Wand2Icon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="m21.64 3.64-1.28-1.28a1.21 1.21 0 0 0-1.72 0L2.36 18.64a1.21 1.21 0 0 0 0 1.72l1.28 1.28a1.2 1.2 0 0 0 1.72 0L21.64 5.36a1.2 1.2 0 0 0 0-1.72Z"/>
    <path d="m14 7 3 3"/>
    <path d="M5 6v4"/>
    <path d="M19 14v4"/>
    <path d="M10 2v2"/>
    <path d="M7 8H3"/>
    <path d="M21 16h-4"/>
  </svg>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Building, RefreshCw, Clock, User, CheckCircle2, Eye, Copy, X, 
  Plus, Search, Settings, Layout, Trash2, ChevronLeft, Save, 
  Share2, ZoomIn, ZoomOut, Maximize, AlertCircle, Loader2, Move 
} from 'lucide-react';
import { Project, Milestone, Subtask, AppSettings, ProjectType, SubtaskStatus, AppState } from './types';
import { geminiService } from './services/geminiService';
import { firebaseService } from './services/firebaseService';
import { MilestoneNode } from './components/MilestoneNode';
import { getStatusColor } from './constants';

// Helper to generate IDs
const generateId = () => Math.random().toString(36).substr(2, 9);

const DEFAULT_SETTINGS: AppSettings = {
  projectTypes: Object.values(ProjectType),
  companies: ['Acme Corp', 'Global Ind', 'TechStart'],
  people: ['Alice', 'Bob', 'Charlie', 'David'],
  statuses: Object.values(SubtaskStatus),
  dateFormat: 'DD/MM/YY'
};

const App: React.FC = () => {
  // --- State ---
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Dashboard State
  const [searchQuery, setSearchQuery] = useState('');
  const [showNewProjectModal, setShowNewProjectModal] = useState(false);
  const [newProjectName, setNewProjectName] = useState('');
  const [newProjectType, setNewProjectType] = useState<ProjectType>(ProjectType.OTHER);
  const [isGenerating, setIsGenerating] = useState(false);

  // Canvas/Project View State
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [isPanning, setIsPanning] = useState(false);
  const [showSubtasks, setShowSubtasks] = useState(true);
  const [linkingSourceId, setLinkingSourceId] = useState<string | null>(null);

  const canvasRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const isRemoteUpdate = useRef(false);

  // --- Effects ---

  // Load data from Firebase
  useEffect(() => {
    const unsubscribe = firebaseService.subscribe((data) => {
      if (data) {
        isRemoteUpdate.current = true;
        setProjects(data.projects || []);
        if (data.settings) setSettings(data.settings);
      }
    });
    return () => unsubscribe();
  }, []);

  // Save data to Firebase on change (debounced could be better, but simple for now)
  useEffect(() => {
    if (isRemoteUpdate.current) {
      isRemoteUpdate.current = false;
      return;
    }

    if (projects.length > 0) {
      const timer = setTimeout(() => {
        firebaseService.save({ projects, settings });
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [projects, settings]);

  // --- Computed ---

  const selectedProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
    [projects, selectedProjectId]
  );

  const filteredProjects = useMemo(() => {
    if (!searchQuery) return projects;
    const lower = searchQuery.toLowerCase();
    return projects.filter(p => 
      p.name.toLowerCase().includes(lower) || 
      p.company.toLowerCase().includes(lower)
    );
  }, [projects, searchQuery]);

  // --- Helpers ---

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return settings.dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const updateProject = (projectId: string, updates: Partial<Project>) => {
    setProjects(prev => prev.map(p => 
      p.id === projectId 
        ? { ...p, ...updates, updatedAt: Date.now() } 
        : p
    ));
  };

  // --- Handlers ---

  const handleCreateProject = async () => {
    if (!newProjectName.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const structure = await geminiService.generateProjectStructure(newProjectName, newProjectType);

      if (!structure || !structure.milestones) {
        throw new Error("Failed to generate project structure");
      }

      // Layout milestones in a simple grid initially if no positions
      const milestonesWithPos = structure.milestones.map((m: any, idx: number) => ({
        ...m,
        id: m.id || generateId(),
        subtasks: m.subtasks?.map((s: any) => ({
          ...s,
          id: generateId(),
          status: 'Not started',
          assignedTo: ''
        })) || [],
        dependsOn: m.dependsOn || [],
        x: (idx % 3) * 300,
        y: Math.floor(idx / 3) * 200,
        completedAt: undefined
      }));

      const newProject: Project = {
        id: generateId(),
        name: newProjectName,
        company: settings.companies[0] || 'Unknown',
        type: newProjectType,
        startDate: Date.now(),
        createdAt: Date.now(),
        updatedAt: Date.now(),
        milestones: milestonesWithPos
      };

      setProjects(prev => [...prev, newProject]);
      setShowNewProjectModal(false);
      setNewProjectName('');
    } catch (err) {
      setError("Failed to generate project. Please check your API key and try again.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDuplicateProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    const newProject = {
      ...project,
      id: generateId(),
      name: `${project.name} (Copy)`,
      createdAt: Date.now(),
      updatedAt: Date.now()
    };

    setProjects(prev => [...prev, newProject]);
  };

  const handleDeleteProject = (projectId: string) => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      setProjects(prev => prev.filter(p => p.id !== projectId));
      if (selectedProjectId === projectId) setSelectedProjectId(null);
    }
  };

  // --- Canvas Handlers ---

  const handleCanvasMouseDown = (e: React.MouseEvent) => {
    if (e.button === 0) { // Left click
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleCanvasMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;
      setPan(p => ({ x: p.x + dx, y: p.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleCanvasMouseUp = () => {
    setIsPanning(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey) {
      e.preventDefault();
      const delta = -e.deltaY * 0.001;
      setZoom(z => Math.min(Math.max(0.1, z + delta), 3));
    }
  };

  // --- Milestone Logic ---

  const handleMoveMilestone = (id: string, x: number, y: number) => {
    if (!selectedProjectId) return;

    // Update local state for smooth drag
    const project = projects.find(p => p.id === selectedProjectId);
    if (!project) return;

    const updatedMilestones = project.milestones.map(m => 
      m.id === id ? { ...m, x, y } : m
    );

    updateProject(selectedProjectId, { milestones: updatedMilestones });
  };

  const handleUpdateMilestone = (milestoneId: string, updates: Partial<Milestone>) => {
    if (!selectedProjectId) return;
    const project = projects.find(p => p.id === selectedProjectId);
    if (!project) return;

    const updatedMilestones = project.milestones.map(m => 
      m.id === milestoneId ? { ...m, ...updates } : m
    );

    updateProject(selectedProjectId, { milestones: updatedMilestones });
  };

  const handleBrainstormSubtasks = async (milestoneId: string) => {
    if (!selectedProjectId || !selectedProject) return;

    const milestone = selectedProject.milestones.find(m => m.id === milestoneId);
    if (!milestone) return;

    const suggestions = await geminiService.brainstormSubtasks(
      milestone.name, 
      `${selectedProject.name} (${selectedProject.type})`
    );

    if (suggestions && suggestions.length > 0) {
      const newSubtasks = suggestions.map((s: any) => ({
        id: generateId(),
        name: s.name,
        description: s.description,
        assignedTo: '',
        status: 'Not started',
        notes: ''
      }));

      handleUpdateMilestone(milestoneId, {
        subtasks: [...(milestone.subtasks || []), ...newSubtasks]
      });
    }
  };

  const handleAddMilestone = () => {
    if (!selectedProjectId) return;

    // Calculate center of current view
    const centerX = (-pan.x + (window.innerWidth / 2)) / zoom;
    const centerY = (-pan.y + (window.innerHeight / 2)) / zoom;

    const newMilestone: Milestone = {
      id: generateId(),
      name: 'New Milestone',
      subtasks: [],
      dependsOn: [],
      estimatedDuration: 1,
      x: centerX,
      y: centerY
    };

    const project = projects.find(p => p.id === selectedProjectId);
    if (project) {
      updateProject(selectedProjectId, { milestones: [...project.milestones, newMilestone] });
    }
  };

  // Linking
  const handleStartLinking = (id: string) => setLinkingSourceId(id);
  const handleCompleteLinking = (targetId: string) => {
    if (linkingSourceId && linkingSourceId !== targetId && selectedProjectId) {
      const project = projects.find(p => p.id === selectedProjectId);
      if (project) {
        const targetMilestone = project.milestones.find(m => m.id === targetId);
        if (targetMilestone && !targetMilestone.dependsOn.includes(linkingSourceId)) {
          handleUpdateMilestone(targetId, {
            dependsOn: [...targetMilestone.dependsOn, linkingSourceId]
          });
        }
      }
    }
    setLinkingSourceId(null);
  };

  // --- Render ---

  if (!firebaseService.isConfigured()) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full">
          <h2 className="text-2xl font-bold mb-4 text-slate-900">Configure Firebase</h2>
          <p className="text-slate-600 mb-4">Paste your Firebase configuration object below to get started.</p>
          <textarea 
            className="w-full h-40 border border-slate-300 rounded p-2 text-xs font-mono mb-4"
            placeholder="{ apiKey: ... }"
            onBlur={(e) => firebaseService.configure(e.target.value)}
          />
        </div>
      </div>
    );
  }

  // Project View
  if (selectedProject) {
    return (
      <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
        {/* Header */}
        <div className="bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between z-20 shadow-sm">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setSelectedProjectId(null)}
              className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"
            >
              <ChevronLeft size={20} />
            </button>
            <div>
              <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
                {selectedProject.name}
                <span className="text-xs font-normal text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                  {selectedProject.type}
                </span>
              </h1>
              <div className="flex items-center gap-3 text-xs text-slate-500 mt-0.5">
                <span className="flex items-center gap-1"><Building size={12} /> {selectedProject.company}</span>
                <span className="flex items-center gap-1"><Clock size={12} /> Started {formatDate(selectedProject.startDate)}</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="flex bg-slate-100 p-1 rounded-lg">
              <button 
                onClick={() => setZoom(z => Math.max(0.1, z - 0.1))}
                className="p-1.5 hover:bg-white rounded text-slate-600 shadow-sm transition-all"
              ><ZoomOut size={16} /></button>
              <span className="px-2 flex items-center text-xs font-bold text-slate-500 w-12 justify-center">
                {Math.round(zoom * 100)}%
              </span>
              <button 
                onClick={() => setZoom(z => Math.min(3, z + 0.1))}
                className="p-1.5 hover:bg-white rounded text-slate-600 shadow-sm transition-all"
              ><ZoomIn size={16} /></button>
            </div>

            <button 
              onClick={() => setShowSubtasks(!showSubtasks)}
              className={`p-2 rounded-lg border text-sm font-medium transition-all flex items-center gap-2
                ${showSubtasks ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
            >
              <Layout size={16} /> {showSubtasks ? 'Hide Tasks' : 'Show Tasks'}
            </button>

            <button 
              onClick={handleAddMilestone}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-sm transition-all flex items-center gap-2"
            >
              <Plus size={16} /> Add Milestone
            </button>
          </div>
        </div>

        {/* Canvas */}
        <div 
          className="flex-1 relative overflow-hidden bg-slate-50 cursor-move"
          ref={canvasRef}
          onMouseDown={handleCanvasMouseDown}
          onMouseMove={(e) => {
            handleCanvasMouseMove(e);
            // Also pass generic mouse move for dragging nodes logic if needed globally
          }}
          onMouseUp={handleCanvasMouseUp}
          onMouseLeave={handleCanvasMouseUp}
          onWheel={handleWheel}
        >
          {/* Background Grid */}
          <div 
            className="absolute inset-0 pointer-events-none opacity-5"
            style={{
              backgroundImage: 'radial-gradient(#64748b 1px, transparent 1px)',
              backgroundSize: `${20 * zoom}px ${20 * zoom}px`,
              transform: `translate(${pan.x}px, ${pan.y}px)`
            }}
          />

          <div 
            className="absolute inset-0 transform-gpu origin-top-left"
            style={{
              transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`
            }}
          >
            {/* Connection Lines */}
            <svg className="absolute top-0 left-0 w-[5000px] h-[5000px] pointer-events-none overflow-visible">
              <defs>
                <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                  <polygon points="0 0, 10 3.5, 0 7" fill="#cbd5e1" />
                </marker>
              </defs>
              {selectedProject.milestones.map(m => 
                m.dependsOn?.map(targetId => {
                  const target = selectedProject.milestones.find(t => t.id === targetId);
                  if (!target) return null;

                  // Safe accessors to prevent NaN in SVG path
                  const mx = m.x || 0;
                  const my = m.y || 0;
                  const tx = target.x || 0;
                  const ty = target.y || 0;

                  return (
                    <path
                      key={`${m.id}-${targetId}`}
                      d={`M ${tx} ${ty} C ${tx + 50} ${ty}, ${mx - 50} ${my}, ${mx} ${my}`}
                      stroke="#cbd5e1"
                      strokeWidth="2"
                      fill="none"
                      markerEnd="url(#arrowhead)"
                    />
                  );
                })
              )}
              {linkingSourceId && (
                (() => {
                   // Draw temp line from source to mouse? (Simplified: just highlight nodes)
                   return null;
                })()
              )}
            </svg>

            {/* Nodes */}
            {selectedProject.milestones.map(milestone => (
              <MilestoneNode
                key={milestone.id}
                milestone={milestone}
                showSubtasks={showSubtasks}
                onAddSubtask={(id) => {
                   const m = selectedProject.milestones.find(x => x.id === id);
                   if (m) {
                     const newTask = { 
                       id: generateId(), 
                       name: 'New Task', 
                       description: '', 
                       status: 'Not started', 
                       assignedTo: '',
                       notes: '' 
                     };
                     handleUpdateMilestone(id, { subtasks: [...(m.subtasks || []), newTask] });
                   }
                }}
                onAddSequence={(id) => {
                  const source = selectedProject.milestones.find(x => x.id === id);
                  if (!source) return;
                  const newM: Milestone = {
                    id: generateId(),
                    name: 'New Milestone',
                    subtasks: [],
                    dependsOn: [id],
                    estimatedDuration: 1,
                    x: (source.x || 0) + 300,
                    y: source.y || 0
                  };
                  updateProject(selectedProjectId!, { milestones: [...selectedProject.milestones, newM] });
                }}
                onAddPrevious={(id) => {
                   const source = selectedProject.milestones.find(x => x.id === id);
                   if (!source) return;
                   const newM: Milestone = {
                    id: generateId(),
                    name: 'Previous Step',
                    subtasks: [],
                    dependsOn: [],
                    estimatedDuration: 1,
                    x: (source.x || 0) - 300,
                    y: source.y || 0
                  };
                  // Update current to depend on new
                  const updatedCurrent = { ...source, dependsOn: [...source.dependsOn, newM.id] };
                  const otherMilestones = selectedProject.milestones.filter(m => m.id !== id);
                  updateProject(selectedProjectId!, { milestones: [...otherMilestones, updatedCurrent, newM] });
                }}
                onAddParallel={(id) => {
                   const source = selectedProject.milestones.find(x => x.id === id);
                   if (!source) return;
                   const newM: Milestone = {
                    id: generateId(),
                    name: 'Parallel Step',
                    subtasks: [],
                    dependsOn: source.dependsOn, // Same parent dependencies
                    estimatedDuration: 1,
                    x: (source.x || 0),
                    y: (source.y || 0) + 200
                  };
                  updateProject(selectedProjectId!, { milestones: [...selectedProject.milestones, newM] });
                }}
                onEditSubtask={(mId, sIndex) => {
                   // Simple toggle status for now or prompt name
                   const m = selectedProject.milestones.find(x => x.id === mId);
                   if (!m) return;
                   const task = m.subtasks[sIndex];
                   const nextStatus = task.status === 'Complete' ? 'Not started' : 'Complete';
                   const newSubtasks = [...m.subtasks];
                   newSubtasks[sIndex] = { 
                     ...task, 
                     status: nextStatus, 
                     completedAt: nextStatus === 'Complete' ? Date.now() : undefined 
                   };
                   handleUpdateMilestone(mId, { subtasks: newSubtasks });
                }}
                onUpdateName={(id, name) => handleUpdateMilestone(id, { name })}
                onUpdateDuration={(id, days) => handleUpdateMilestone(id, { estimatedDuration: days })}
                onDeleteMilestone={(id) => {
                   if (window.confirm("Delete this milestone?")) {
                      const updated = selectedProject.milestones.filter(m => m.id !== id);
                      // Remove dependencies on this
                      const cleaned = updated.map(m => ({
                        ...m,
                        dependsOn: m.dependsOn.filter(d => d !== id)
                      }));
                      updateProject(selectedProjectId!, { milestones: cleaned });
                   }
                }}
                onMove={handleMoveMilestone}
                onBrainstorm={handleBrainstormSubtasks}
                onHover={() => {}}
                onStartLinking={handleStartLinking}
                onCompleteLinking={handleCompleteLinking}
                isLinkingMode={!!linkingSourceId}
                isSource={linkingSourceId === milestone.id}
                dateFormat={settings.dateFormat}
                onClick={() => {}}
              />
            ))}
          </div>

          {linkingSourceId && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-indigo-600 text-white px-4 py-2 rounded-full shadow-lg text-sm font-semibold animate-bounce z-50">
              Select a target milestone to link
              <button onClick={() => setLinkingSourceId(null)} className="ml-3 opacity-75 hover:opacity-100 border-l border-indigo-400 pl-2">Cancel</button>
            </div>
          )}
        </div>
      </div>
    );
  }

  // Dashboard View
  return (
    <div className="min-h-screen bg-slate-50 p-6 md:p-8">
      <div className="max-w-7xl mx-auto">

        {/* Dashboard Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">ProjectFlow</h1>
            <p className="text-slate-500 mt-1">Manage your development milestones with AI assistance</p>
          </div>
          <div className="flex items-center gap-3">
             <div className="relative">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
               <input 
                 type="text" 
                 placeholder="Search projects..." 
                 className="pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none w-64 transition-all"
                 value={searchQuery}
                 onChange={(e) => setSearchQuery(e.target.value)}
               />
             </div>
             <button 
               onClick={() => setShowNewProjectModal(true)}
               className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-semibold shadow-sm flex items-center gap-2 transition-all hover:scale-105 active:scale-95"
             >
               <Plus size={18} /> New Project
             </button>
          </div>
        </div>

        {/* Project List */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProjects.map(p => {
            const allTasks = p.milestones.flatMap(m => m.subtasks || []);
            const totalTasks = allTasks.length;
            const completedTasks = allTasks.filter(t => t.status === 'Complete').length;
            const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
            const nextTask = allTasks.find(t => t.status === 'Not started');

            return (
              <div 
                key={p.id}
                className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow group relative flex flex-col"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex-1">
                    <h3 className="text-lg font-bold text-slate-900 leading-tight mb-1">{p.name}</h3>
                    <div className="flex items-center gap-1.5 text-slate-500 text-sm">
                      <Building size={14} />
                      <span>{p.company}</span>
                    </div>
                  </div>
                  <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {p.type}
                  </span>
                </div>

                <div className="flex items-center gap-2 text-[10px] text-slate-400 mb-4">
                  <RefreshCw size={10} />
                  <span>Last updated {formatDate(p.updatedAt)}</span>
                </div>

                {/* Progress & Next Task */}
                <div className="mb-5 space-y-3">
                  <div>
                    <div className="flex justify-between text-xs mb-1.5">
                        <span className="font-bold text-slate-500">Progress</span>
                        <span className="font-bold text-slate-900">{progress}%</span>
                    </div>
                    <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
                      <div 
                          className="bg-gradient-to-r from-indigo-500 to-emerald-500 h-full transition-all duration-500" 
                          style={{ width: `${progress}%` }}
                      />
                    </div>
                  </div>

                  {nextTask ? (
                    <div className="bg-slate-50 border border-slate-100 rounded-lg p-2.5">
                      <div className="flex items-center gap-1.5 text-[10px] font-bold text-indigo-600 uppercase tracking-wider mb-1">
                        <Clock size={10} /> Next Action
                      </div>
                      <div className="flex justify-between items-start gap-2">
                          <span className="text-xs font-semibold text-slate-800 line-clamp-2 leading-tight">
                            {nextTask.name}
                          </span>
                          {nextTask.assignedTo && (
                            <span className="shrink-0 text-[10px] px-2 py-0.5 bg-white border border-slate-200 rounded-full text-slate-500 flex items-center gap-1 shadow-sm">
                              <User size={10} /> {nextTask.assignedTo}
                            </span>
                          )}
                      </div>
                    </div>
                  ) : totalTasks > 0 && progress === 100 ? (
                      <div className="bg-emerald-50 border border-emerald-100 rounded-lg p-2.5 flex items-center gap-2 text-emerald-700">
                        <CheckCircle2 size={14} />
                        <span className="text-xs font-bold">Project Complete</span>
                      </div>
                  ) : (
                      <div className="bg-slate-50 border border-slate-100 rounded-lg p-2.5 text-xs text-slate-400 italic text-center">
                        No tasks pending
                      </div>
                  )}
                </div>

                <div className="flex gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide flex-1">
                  {(p.milestones || []).slice(0, 4).map(m => {
                    const safeSubtasks = m.subtasks || [];
                    const complete = safeSubtasks.filter((s: any) => s.status === 'Complete').length;
                    const total = safeSubtasks.length || 1;
                    const progressDeg = (complete / total) * 360;
                    return (
                      <div key={m.id} className="shrink-0 flex flex-col items-center">
                        <div className="w-8 h-8 rounded-full bg-slate-50 ring-1 ring-slate-100 flex items-center justify-center" title={m.name}>
                          <div 
                            className="w-5 h-5 rounded-full" 
                            style={{ background: `conic-gradient(#22c55e ${progressDeg}deg, #f1f5f9 0deg)` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="flex items-center gap-2 mt-auto">
                  <button 
                    onClick={() => { setSelectedProjectId(p.id); setPan({ x: 0, y: 0 }); }}
                    className="flex-1 bg-slate-50 hover:bg-indigo-50 hover:text-indigo-600 text-slate-700 font-semibold py-2 rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
                  >
                    <Eye size={16} /> Open
                  </button>
                  <button onClick={() => handleDuplicateProject(p.id)} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"><Copy size={16} /></button>
                  <button onClick={() => handleDeleteProject(p.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"><X size={16} /></button>
                </div>
              </div>
            );
          })}

          {/* Empty State */}
          {filteredProjects.length === 0 && (
            <div className="col-span-full py-12 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="font-semibold text-lg">No projects found</p>
              <p className="text-sm">Try creating a new project or adjust your search</p>
            </div>
          )}
        </div>
      </div>

      {/* New Project Modal */}
      {showNewProjectModal && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-xl font-bold text-slate-900">Create New Project</h2>
              <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1.5">Project Name</label>
                <input 
                  type="text" 
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="e.g. Downtown Office Complex"
                  value={newProjectName}
                  onChange={e => setNewProjectName(e.target.value)}
                  autoFocus
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1.5">Project Type</label>
                <div className="grid grid-cols-1 gap-2">
                  {settings.projectTypes.map(t => (
                    <label 
                      key={t}
                      className={`flex items-center px-3 py-2 rounded-lg border cursor-pointer transition-all ${newProjectType === t ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-200 hover:border-slate-300'}`}
                    >
                      <input 
                        type="radio" 
                        name="projectType" 
                        className="sr-only"
                        checked={newProjectType === t}
                        onChange={() => setNewProjectType(t as ProjectType)}
                      />
                      <span className="text-sm font-medium">{t}</span>
                      {newProjectType === t && <CheckCircle2 size={16} className="ml-auto" />}
                    </label>
                  ))}
                </div>
              </div>

              {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-start gap-2">
                  <AlertCircle size={16} className="mt-0.5 shrink-0" />
                  {error}
                </div>
              )}
            </div>

            <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
              <button 
                onClick={() => setShowNewProjectModal(false)}
                className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg"
              >
                Cancel
              </button>
              <button 
                onClick={handleCreateProject}
                disabled={isGenerating || !newProjectName}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-medium rounded-lg shadow-sm flex items-center gap-2"
              >
                {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Wand2Icon />}
                {isGenerating ? 'Generating Structure...' : 'Generate Project'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Helper component for the button icon
const Wand2Icon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="m21.64 3.64-1.28-1.28a1.21 1.21 0 0 0-1.72 0L2.36 18.64a1.21 1.21 0 0 0 0 1.72l1.28 1.28a1.2 1.2 0 0 0 1.72 0L21.64 5.36a1.2 1.2 0 0 0 0-1.72Z"/>
    <path d="m14 7 3 3"/>
    <path d="M5 6v4"/>
    <path d="M19 14v4"/>
    <path d="M10 2v2"/>
    <path d="M7 8H3"/>
    <path d="M21 16h-4"/>
  </svg>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Building, RefreshCw, Clock, User, CheckCircle2, Eye, Copy, X, 
  Plus, Search, Settings, Layout, Trash2, ChevronLeft, Save, 
  Share2, ZoomIn, ZoomOut, Maximize, AlertCircle, Loader2, Move,
  Map as MapIcon, EyeOff, Activity
} from 'lucide-react';
import { Project, Milestone, Subtask, AppSettings, ProjectType, SubtaskStatus, AppState } from './types';
import { geminiService } from './services/geminiService';
import { firebaseService } from './services/firebaseService';
import { MilestoneNode } from './components/MilestoneNode';
import { getStatusColor, getStatusBorderColor } from './constants';

// Helper to generate IDs
const generateId = () => Math.random().toString(36).substr(2, 9);

const DEFAULT_SETTINGS: AppSettings = {
  projectTypes: Object.values(ProjectType),
  companies: ['Acme Corp', 'Global Ind', 'TechStart'],
  people: ['Alice', 'Bob', 'Charlie', 'David'],
  statuses: Object.values(SubtaskStatus),
  dateFormat: 'DD/MM/YY'
};

const App: React.FC = () => {
  // --- State ---
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [error, setError] = useState<string | null>(null);

  // Dashboard State
  const [searchQuery, setSearchQuery] = useState('');
  const [showNewProjectModal, setShowNewProjectModal] = useState(false);
  const [newProjectName, setNewProjectName] = useState('');
  const [newProjectType, setNewProjectType] = useState<ProjectType>(ProjectType.OTHER);
  const [isGenerating, setIsGenerating] = useState(false);

  // Canvas/Project View State
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [isPanning, setIsPanning] = useState(false);
  const [showSubtasks, setShowSubtasks] = useState(true);
  const [showMinimap, setShowMinimap] = useState(true);
  const [linkingSourceId, setLinkingSourceId] = useState<string | null>(null);
  const [hoveredMilestoneId, setHoveredMilestoneId] = useState<string | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const isRemoteUpdate = useRef(false);

  // --- Effects ---

  // Load data from Firebase
  useEffect(() => {
    const unsubscribe = firebaseService.subscribe((data) => {
      if (data) {
        isRemoteUpdate.current = true;
        setProjects(data.projects || []);
        if (data.settings) setSettings(data.settings);
      }
    });
    return () => unsubscribe();
  }, []);

  // Save data to Firebase on change
  useEffect(() => {
    if (isRemoteUpdate.current) {
      isRemoteUpdate.current = false;
      return;
    }

    if (projects.length > 0) {
      const timer = setTimeout(() => {
        firebaseService.save({ projects, settings });
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [projects, settings]);

  // --- Computed ---

  const selectedProject = useMemo(() => 
    projects.find(p => p.id === selectedProjectId), 
    [projects, selectedProjectId]
  );

  const filteredProjects = useMemo(() => {
    if (!searchQuery) return projects;
    const lower = searchQuery.toLowerCase();
    return projects.filter(p => 
      p.name.toLowerCase().includes(lower) || 
      p.company.toLowerCase().includes(lower)
    );
  }, [projects, searchQuery]);

  // --- Layout Engine ---

  const canvasData = useMemo(() => {
    if (!selectedProject) return { milestones: [], width: 2500, height: 1800, bounds: { minX: 0, minY: 0, maxX: 0, maxY: 0 } };

    // Logic to calculate levels for auto-layout
    const levels: Record<string, number> = {};
    const getLevel = (id: string, visited: Set<string> = new Set()): number => {
      if (levels[id] !== undefined) return levels[id];
      if (visited.has(id)) return -1; // Cycle detected

      const m = selectedProject.milestones.find(mil => mil.id === id);
      if (!m || !m.dependsOn || m.dependsOn.length === 0) {
        levels[id] = 0;
        return 0;
      }

      visited.add(id);
      const parentLevels = m.dependsOn.map(parentId => getLevel(parentId, new Set(visited)));
      levels[id] = Math.max(...parentLevels) + 1;
      return levels[id];
    };

    selectedProject.milestones.forEach(m => getLevel(m.id));

    const groupedByLevel: Record<number, string[]> = {};
    Object.entries(levels).forEach(([id, level]) => {
      if (level === -1) return; // Skip circular deps or errors from layout grouping
      if (!groupedByLevel[level]) groupedByLevel[level] = [];
      groupedByLevel[level].push(id);
    });

    const HORIZONTAL_GAP = 360;
    const VERTICAL_GAP = 280;
    const PADDING_X = 400;
    const PADDING_Y = 400;

    // Default center
    const startX = PADDING_X;
    const centerY = 900; // arbitrary middle height

    const milestonesWithLayout = selectedProject.milestones.map(m => {
      const level = levels[m.id];
      let x = m.x;
      let y = m.y;

      // Apply auto-layout if position is undefined
      if (x === undefined || y === undefined) {
         if (level !== undefined && level !== -1) {
            const indexInLevel = groupedByLevel[level].indexOf(m.id);
            const totalInLevel = groupedByLevel[level].length;
            x = startX + level * HORIZONTAL_GAP;
            y = centerY + (indexInLevel - (totalInLevel - 1) / 2) * VERTICAL_GAP;
         } else {
            // Fallback for isolated nodes or cycles not resolved
            x = startX + (selectedProject.milestones.indexOf(m) * 50);
            y = centerY;
         }
      }

      return { ...m, x, y };
    });

    // Calculate content bounds
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    if (milestonesWithLayout.length === 0) {
        minX = 0; minY = 0; maxX = 0; maxY = 0;
    } else {
        milestonesWithLayout.forEach(m => {
            if (m.x < minX) minX = m.x;
            if (m.x > maxX) maxX = m.x;
            if (m.y < minY) minY = m.y;
            if (m.y > maxY) maxY = m.y;
        });
    }

    const width = Math.max((maxX - minX) + PADDING_X * 2, 2500);
    const height = Math.max((maxY - minY) + PADDING_Y * 2, 1800);

    return { 
        milestones: milestonesWithLayout, 
        width, 
        height,
        bounds: { minX, minY, maxX, maxY }
    };
  }, [selectedProject]);


  // --- View Control Handlers ---

  const centerView = () => {
    if (!containerRef.current || !canvasData.milestones.length) return;
    setZoom(1);

    // Center on the first milestone or 0,0
    const firstM = canvasData.milestones[0];
    const targetX = firstM?.x || 0;
    const targetY = firstM?.y || 0;

    const containerW = containerRef.current.clientWidth;
    const containerH = containerRef.current.clientHeight;

    setPan({
        x: (containerW / 2) - targetX,
        y: (containerH / 2) - targetY
    });
  };

  const handleZoomToExtents = () => {
    if (!containerRef.current || canvasData.milestones.length === 0) return;

    const { minX, minY, maxX, maxY } = canvasData.bounds;
    const padding = 100;
    const viewW = containerRef.current.clientWidth;
    const viewH = containerRef.current.clientHeight;

    const contentW = (maxX - minX) + padding * 2;
    const contentH = (maxY - minY) + padding * 2;

    const scaleX = viewW / contentW;
    const scaleY = viewH / contentH;

    const newZoom = Math.min(Math.min(scaleX, scaleY), 1.2); // Limit max zoom
    const clampedZoom = Math.max(newZoom, 0.1);

    setZoom(clampedZoom);

    const centerX = (minX + maxX) / 2;
    const centerY = (minY + maxY) / 2;

    setPan({
      x: (viewW / 2) - (centerX * clampedZoom),
      y: (viewH / 2) - (centerY * clampedZoom)
    });
  };

  const handleResetLayout = () => {
    if (!selectedProjectId) return;
    if (window.confirm("Reset layout to auto-generated grid? This will clear all manual positioning.")) return;

    const project = projects.find(p => p.id === selectedProjectId);
    if (!project) return;

    const resetMilestones = project.milestones.map(m => {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const { x, y, ...rest } = m;
      return rest;
    });

    updateProject(selectedProjectId, { milestones: resetMilestones });
    // Center view after render cycle
    setTimeout(handleZoomToExtents, 100);
  };

  // Center view on project load
  useEffect(() => {
    if (selectedProjectId) {
      setTimeout(handleZoomToExtents, 100);
    }
  }, [selectedProjectId]);


  // --- Helpers ---

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return settings.dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const updateProject = (projectId: string, updates: Partial<Project>) => {
    setProjects(prev => prev.map(p => 
      p.id === projectId 
        ? { ...p, ...updates, updatedAt: Date.now() } 
        : p
    ));
  };

  // --- Handlers ---

  const handleCreateProject = async () => {
    if (!newProjectName.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const structure = await geminiService.generateProjectStructure(newProjectName, newProjectType);

      if (!structure || !structure.milestones) {
        throw new Error("Failed to generate project structure");
      }

      const milestonesWithIds = structure.milestones.map((m: any) => ({
        ...m,
        id: m.id || generateId(),
        subtasks: m.subtasks?.map((s: any) => ({
          ...s,
          id: generateId(),
          status: 'Not started',
          assignedTo: ''
        })) || [],
        dependsOn: m.dependsOn || [],
        completedAt: undefined
      }));

      const newProject: Project = {
        id: generateId(),
        name: newProjectName,
        company: settings.companies[0] || 'Unknown',
        type: newProjectType,
        startDate: Date.now(),
        createdAt: Date.now(),
        updatedAt: Date.now(),
        milestones: milestonesWithIds
      };

      setProjects(prev => [...prev, newProject]);
      setShowNewProjectModal(false);
      setNewProjectName('');
    } catch (err) {
      setError("Failed to generate project. Please check your API key and try again.");
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDuplicateProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    const newProject = {
      ...project,
      id: generateId(),
      name: `${project.name} (Copy)`,
      createdAt: Date.now(),
      updatedAt: Date.now()
    };

    setProjects(prev => [...prev, newProject]);
  };

  const handleDeleteProject = (projectId: string) => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      setProjects(prev => prev.filter(p => p.id !== projectId));
      if (selectedProjectId === projectId) setSelectedProjectId(null);
    }
  };

  // --- Canvas Interaction ---

  const handleCanvasMouseDown = (e: React.MouseEvent) => {
    // Only pan if clicking on background (not bubble) and left mouse
    if (e.button === 0 && (e.target as HTMLElement).closest('.mindmap-container')) { 
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleCanvasMouseMove = (e: React.MouseEvent) => {
    if (isPanning) {
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;
      setPan(p => ({ x: p.x + dx, y: p.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const handleCanvasMouseUp = () => {
    setIsPanning(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey) {
      e.preventDefault();
      const delta = -e.deltaY * 0.001;
      setZoom(z => Math.min(Math.max(0.1, z + delta), 3));
    }
  };

  // --- Milestone Actions ---

  const handleMoveMilestone = (id: string, x: number, y: number, withSubtree: boolean) => {
    if (!selectedProjectId) return;

    const nodeInCanvas = canvasData.milestones.find(m => m.id === id);
    if (!nodeInCanvas) return;

    // Use current effective position from canvas data for delta
    const dx = x - (nodeInCanvas.x || 0);
    const dy = y - (nodeInCanvas.y || 0);

    const nodesToMove = new Set<string>();
    nodesToMove.add(id);

    if (withSubtree) {
       const addDescendants = (parentId: string) => {
         selectedProject?.milestones.filter(m => (m.dependsOn || []).includes(parentId)).forEach(child => {
           if (!nodesToMove.has(child.id)) {
             nodesToMove.add(child.id);
             addDescendants(child.id);
           }
         });
       };
       addDescendants(id);
    }

    const updatedMilestones = selectedProject?.milestones.map(m => {
       if (nodesToMove.has(m.id)) {
         // Get current effective pos from canvasData
         const currentEffective = canvasData.milestones.find(cm => cm.id === m.id);
         const startX = currentEffective?.x || 0;
         const startY = currentEffective?.y || 0;

         if (m.id === id) return { ...m, x, y };

         return { ...m, x: startX + dx, y: startY + dy };
       }
       return m;
    }) || [];

    updateProject(selectedProjectId, { milestones: updatedMilestones });
  };

  const handleUpdateMilestone = (milestoneId: string, updates: Partial<Milestone>) => {
    if (!selectedProjectId) return;
    const project = projects.find(p => p.id === selectedProjectId);
    if (!project) return;

    const updatedMilestones = project.milestones.map(m => 
      m.id === milestoneId ? { ...m, ...updates } : m
    );

    updateProject(selectedProjectId, { milestones: updatedMilestones });
  };

  const handleBrainstormSubtasks = async (milestoneId: string) => {
    if (!selectedProjectId || !selectedProject) return;

    const milestone = selectedProject.milestones.find(m => m.id === milestoneId);
    if (!milestone) return;

    const suggestions = await geminiService.brainstormSubtasks(
      milestone.name, 
      `${selectedProject.name} (${selectedProject.type})`
    );

    if (suggestions && suggestions.length > 0) {
      const newSubtasks = suggestions.map((s: any) => ({
        id: generateId(),
        name: s.name,
        description: s.description,
        assignedTo: '',
        status: 'Not started',
        notes: ''
      }));

      handleUpdateMilestone(milestoneId, {
        subtasks: [...(milestone.subtasks || []), ...newSubtasks]
      });
    }
  };

  const handleAddMilestone = () => {
    if (!selectedProjectId) return;

    // Calculate center of current view
    const centerX = (-pan.x + (window.innerWidth / 2)) / zoom;
    const centerY = (-pan.y + (window.innerHeight / 2)) / zoom;

    const newMilestone: Milestone = {
      id: generateId(),
      name: 'New Milestone',
      subtasks: [],
      dependsOn: [],
      estimatedDuration: 1,
      x: centerX,
      y: centerY
    };

    const project = projects.find(p => p.id === selectedProjectId);
    if (project) {
      updateProject(selectedProjectId, { milestones: [...project.milestones, newMilestone] });
    }
  };

  // Linking
  const handleStartLinking = (id: string) => setLinkingSourceId(id);
  const handleCompleteLinking = (targetId: string) => {
    if (linkingSourceId && linkingSourceId !== targetId && selectedProjectId) {
      const project = projects.find(p => p.id === selectedProjectId);
      if (project) {
        const targetMilestone = project.milestones.find(m => m.id === targetId);

        // Circular dependency check
        const isAncestor = (ancestorId: string, nodeId: string): boolean => {
          if (ancestorId === nodeId) return true;
          const node = project.milestones.find(m => m.id === nodeId);
          if (!node) return false;
          return (node.dependsOn || []).some(depId => isAncestor(ancestorId, depId));
        };

        if (isAncestor(targetId, linkingSourceId)) {
          alert("Cannot link: This would create a circular dependency.");
        } else if (targetMilestone && !targetMilestone.dependsOn.includes(linkingSourceId)) {
          handleUpdateMilestone(targetId, {
            dependsOn: [...targetMilestone.dependsOn, linkingSourceId]
          });
        }
      }
    }
    setLinkingSourceId(null);
  };

  // --- Render ---

  if (!firebaseService.isConfigured()) {
    return (
      <div className="flex items-center justify-center h-screen bg-slate-50">
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full">
          <h2 className="text-2xl font-bold mb-4 text-slate-900">Configure Firebase</h2>
          <p className="text-slate-600 mb-4">Paste your Firebase configuration object below to get started.</p>
          <textarea 
            className="w-full h-40 border border-slate-300 rounded p-2 text-xs font-mono mb-4"
            placeholder="{ apiKey: ... }"
            onBlur={(e) => firebaseService.configure(e.target.value)}
          />
        </div>
      </div>
    );
  }

  // Project View
  if (selectedProject) {
    const projectStats = (() => {
      let totalTasks = 0;
      let completedTasks = 0;
      selectedProject.milestones.forEach(m => {
        (m.subtasks || []).forEach(s => {
          totalTasks++;
          if (s.status === 'Complete') completedTasks++;
        });
      });
      return { totalTasks, completedTasks };
    })();

    return (
      <div className="flex flex-col h-screen overflow-hidden bg-slate-50">
        {/* Header */}
        <div className="bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between z-20 shadow-sm shrink-0">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setSelectedProjectId(null)}
              className="p-2 hover:bg-slate-100 rounded-full text-slate-500 transition-colors"
            >
              <ChevronLeft size={20} />
            </button>
            <div>
              <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
                {selectedProject.name}
                <span className="text-xs font-normal text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                  {selectedProject.type}
                </span>
              </h1>
              <div className="flex items-center gap-3 text-xs text-slate-500 mt-0.5">
                <span className="flex items-center gap-1"><Building size={12} /> {selectedProject.company}</span>
                <span className="flex items-center gap-1"><Clock size={12} /> Started {formatDate(selectedProject.startDate)}</span>
                <span className="flex items-center gap-1"><Activity size={12} /> {Math.round((projectStats.completedTasks / (projectStats.totalTasks || 1)) * 100)}% Complete</span>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3">
             <button 
                onClick={centerView}
                className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                title="Center View"
              >
                <ZoomIn size={18} />
              </button>
              <button 
                onClick={handleZoomToExtents}
                className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                title="Zoom to Extents"
              >
                <Maximize size={18} />
              </button>
              <button 
                onClick={handleResetLayout}
                className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                title="Reset Layout"
              >
                <Layout size={18} />
              </button>

            <div className="h-6 w-px bg-slate-200" />

            <button 
              onClick={() => setShowSubtasks(!showSubtasks)}
              className={`p-2 rounded-lg border text-sm font-medium transition-all flex items-center gap-2
                ${showSubtasks ? 'bg-indigo-50 border-indigo-200 text-indigo-700' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
            >
              {showSubtasks ? <Eye size={16} /> : <EyeOff size={16} />}
              Details
            </button>

            <button 
              onClick={handleAddMilestone}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-medium shadow-sm transition-all flex items-center gap-2"
            >
              <Plus size={16} /> Add Milestone
            </button>
          </div>
        </div>

        {/* Canvas */}
        <div 
          className="flex-1 relative overflow-hidden bg-[#fcfcfd] mindmap-container"
          ref={containerRef}
          onMouseDown={handleCanvasMouseDown}
          onMouseMove={handleCanvasMouseMove}
          onMouseUp={handleCanvasMouseUp}
          onMouseLeave={handleCanvasMouseUp}
          onWheel={handleWheel}
        >
          {/* Background Grid */}
          <div 
            className="absolute inset-0 pointer-events-none opacity-5"
            style={{
              backgroundImage: 'radial-gradient(#64748b 1px, transparent 1px)',
              backgroundSize: `${20 * zoom}px ${20 * zoom}px`,
              transform: `translate(${pan.x}px, ${pan.y}px)`
            }}
          />

           {/* Minimap */}
            <div className="absolute top-6 right-6 z-40 flex flex-col items-end gap-2 pointer-events-none">
              <div className="pointer-events-auto flex flex-col items-end gap-2">
                <button
                  onClick={() => setShowMinimap(!showMinimap)}
                  className="bg-white p-2 rounded-lg shadow-md border border-slate-200 text-slate-500 hover:text-indigo-600 transition-colors"
                  title={showMinimap ? "Hide Minimap" : "Show Minimap"}
                >
                  <MapIcon size={20} />
                </button>

                {showMinimap && (
                  <div className="bg-white border border-slate-200 shadow-xl rounded-xl p-2 w-64 animate-in fade-in slide-in-from-top-2 duration-200">
                      <div className="relative bg-slate-50 rounded-lg overflow-hidden border border-slate-100" style={{ height: '160px' }}>
                        {(() => {
                            const mapWidth = 240; 
                            const mapHeight = 160;
                            const { minX, minY, maxX, maxY } = canvasData.bounds;
                            const contentW = Math.max(maxX - minX + 800, 1000);
                            const contentH = Math.max(maxY - minY + 800, 1000);

                            const scaleX = mapWidth / contentW;
                            const scaleY = mapHeight / contentH;
                            const scale = Math.min(scaleX, scaleY);

                            const offsetX = (mapWidth - contentW * scale) / 2 - (minX - 400) * scale;
                            const offsetY = (mapHeight - contentH * scale) / 2 - (minY - 400) * scale;

                            // Viewport Rect calculation
                            const viewportX = ((-pan.x / zoom) * scale) + offsetX;
                            const viewportY = ((-pan.y / zoom) * scale) + offsetY;
                            const viewportW = ((containerRef.current?.clientWidth || 0) / zoom) * scale;
                            const viewportH = ((containerRef.current?.clientHeight || 0) / zoom) * scale;

                            const handleMinimapClick = (e: React.MouseEvent<SVGSVGElement>) => {
                              const rect = e.currentTarget.getBoundingClientRect();
                              const clickX = e.clientX - rect.left;
                              const clickY = e.clientY - rect.top;

                              // Inverse logic: clickX = (-pan.x / zoom) * scale + offsetX + viewportW/2 approx
                              // Simplified: move clicked point to center
                              const targetContentX = (clickX - offsetX) / scale;
                              const targetContentY = (clickY - offsetY) / scale;

                              const containerW = containerRef.current?.clientWidth || 0;
                              const containerH = containerRef.current?.clientHeight || 0;

                              setPan({
                                x: (containerW / 2) - targetContentX * zoom,
                                y: (containerH / 2) - targetContentY * zoom
                              });
                            };

                            return (
                              <svg 
                                width="100%" 
                                height="100%" 
                                viewBox={`0 0 ${mapWidth} ${mapHeight}`}
                                onClick={handleMinimapClick}
                                className="cursor-pointer"
                              >
                                <g transform={`translate(${offsetX}, ${offsetY}) scale(${scale})`}>
                                    {canvasData.milestones.map(m => (
                                      <React.Fragment key={m.id}>
                                        {(m.dependsOn || []).map(pid => {
                                          const parent = canvasData.milestones.find(p => p.id === pid);
                                          if (!parent) return null;
                                          const dx = (m.x || 0) - (parent.x || 0);
                                          const controlX = (parent.x || 0) + dx / 2;
                                          return (
                                            <path
                                              key={`mini-${pid}-${m.id}`}
                                              d={`M ${(parent.x || 0) + 50} ${parent.y!} C ${controlX} ${parent.y!}, ${controlX} ${m.y!}, ${(m.x || 0) - 50} ${m.y!}`}
                                              stroke="#cbd5e1"
                                              strokeWidth={6}
                                              fill="transparent"
                                            />
                                          )
                                        })}
                                      </React.Fragment>
                                    ))}
                                    {canvasData.milestones.map(m => {
                                      const isComplete = (m.subtasks || []).every((s: any) => s.status === 'Complete') && (m.subtasks || []).length > 0;
                                      return (
                                        <circle
                                          key={`mini-node-${m.id}`}
                                          cx={m.x!}
                                          cy={m.y!}
                                          r={40}
                                          fill={isComplete ? "#22c55e" : "#6366f1"}
                                        />
                                      );
                                    })}
                                </g>
                                <rect
                                  x={viewportX}
                                  y={viewportY}
                                  width={viewportW}
                                  height={viewportH}
                                  fill="rgba(99, 102, 241, 0.2)"
                                  stroke="#6366f1"
                                  strokeWidth="1"
                                />
                              </svg>
                            );
                        })()}
                      </div>
                  </div>
                )}
              </div>
            </div>

          <div 
            className="absolute inset-0 transform-gpu origin-top-left"
            style={{
              transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`
            }}
          >
            {/* Connection Lines */}
            <svg className="absolute top-0 left-0 w-[5000px] h-[5000px] pointer-events-none overflow-visible">
              <defs>
                <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                  <polygon points="0 0, 10 3.5, 0 7" fill="#cbd5e1" />
                </marker>
                <marker id="arrowhead-active" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                  <polygon points="0 0, 10 3.5, 0 7" fill="#6366f1" />
                </marker>
              </defs>
              {canvasData.milestones.map(m => 
                m.dependsOn?.map(targetId => {
                  const target = canvasData.milestones.find(t => t.id === targetId);
                  if (!target) return null;

                  // Safe accessors to prevent NaN in SVG path
                  const mx = m.x || 0;
                  const my = m.y || 0;
                  const tx = target.x || 0;
                  const ty = target.y || 0;
                  const isActive = hoveredMilestoneId === m.id || hoveredMilestoneId === targetId;

                  return (
                    <path
                      key={`${m.id}-${targetId}`}
                      d={`M ${tx + 50} ${ty} C ${tx + 150} ${ty}, ${mx - 150} ${my}, ${mx - 50} ${my}`}
                      stroke={isActive ? "#6366f1" : "#cbd5e1"}
                      strokeWidth={isActive ? "3" : "2"}
                      fill="none"
                      markerEnd={isActive ? "url(#arrowhead-active)" : "url(#arrowhead)"}
                      className="transition-all duration-300"
                    />
                  );
                })
              )}
               {linkingSourceId && (
                <div className="absolute top-0 left-0 text-indigo-500 font-bold bg-white px-2 rounded border border-indigo-200 shadow-sm pointer-events-none" style={{
                   left: (lastMousePos.current.x - pan.x) / zoom,
                   top: (lastMousePos.current.y - pan.y) / zoom
                }}>
                   Linking...
                </div>
              )}
            </svg>

            {/* Nodes */}
            {canvasData.milestones.map(milestone => (
              <MilestoneNode
                key={milestone.id}
                milestone={milestone}
                showSubtasks={showSubtasks}
                onAddSubtask={(id) => {
                   const m = selectedProject.milestones.find(x => x.id === id);
                   if (m) {
                     const newTask = { 
                       id: generateId(), 
                       name: 'New Task', 
                       description: '', 
                       status: 'Not started', 
                       assignedTo: '',
                       notes: '' 
                     };
                     handleUpdateMilestone(id, { subtasks: [...(m.subtasks || []), newTask] });
                   }
                }}
                onAddSequence={(id) => {
                  const source = canvasData.milestones.find(x => x.id === id);
                  if (!source) return;
                  const newM: Milestone = {
                    id: generateId(),
                    name: 'New Milestone',
                    subtasks: [],
                    dependsOn: [id],
                    estimatedDuration: 1,
                    // Pre-set X/Y so it doesn't jump, based on source calculated position
                    x: (source.x || 0) + 360, 
                    y: source.y || 0
                  };
                  updateProject(selectedProjectId!, { milestones: [...selectedProject.milestones, newM] });
                }}
                onAddPrevious={(id) => {
                   const source = canvasData.milestones.find(x => x.id === id);
                   if (!source) return;
                   const newM: Milestone = {
                    id: generateId(),
                    name: 'Previous Step',
                    subtasks: [],
                    dependsOn: [], // Will be depended ON by source
                    estimatedDuration: 1,
                    x: (source.x || 0) - 360,
                    y: source.y || 0
                  };
                  // Update current to depend on new
                  const updatedCurrent = { ...source, dependsOn: [...source.dependsOn, newM.id] };
                  // Must use original project milestones for filtering
                  const otherMilestones = selectedProject.milestones.filter(m => m.id !== id);
                  updateProject(selectedProjectId!, { milestones: [...otherMilestones, updatedCurrent, newM] });
                }}
                onAddParallel={(id) => {
                   const source = canvasData.milestones.find(x => x.id === id);
                   if (!source) return;
                   const newM: Milestone = {
                    id: generateId(),
                    name: 'Parallel Step',
                    subtasks: [],
                    dependsOn: source.dependsOn, 
                    estimatedDuration: 1,
                    x: (source.x || 0),
                    y: (source.y || 0) + 280
                  };
                  updateProject(selectedProjectId!, { milestones: [...selectedProject.milestones, newM] });
                }}
                onEditSubtask={(mId, sIndex) => {
                   const m = selectedProject.milestones.find(x => x.id === mId);
                   if (!m) return;
                   const task = m.subtasks[sIndex];
                   const nextStatus = task.status === 'Complete' ? 'Not started' : 'Complete';
                   const newSubtasks = [...m.subtasks];
                   newSubtasks[sIndex] = { 
                     ...task, 
                     status: nextStatus, 
                     completedAt: nextStatus === 'Complete' ? Date.now() : undefined 
                   };
                   handleUpdateMilestone(mId, { subtasks: newSubtasks });
                }}
                onUpdateName={(id, name) => handleUpdateMilestone(id, { name })}
                onUpdateDuration={(id, days) => handleUpdateMilestone(id, { estimatedDuration: days })}
                onDeleteMilestone={(id) => {
                   if (window.confirm("Delete this milestone?")) {
                      const updated = selectedProject.milestones.filter(m => m.id !== id);
                      const cleaned = updated.map(m => ({
                        ...m,
                        dependsOn: m.dependsOn.filter(d => d !== id)
                      }));
                      updateProject(selectedProjectId!, { milestones: cleaned });
                   }
                }}
                onMove={handleMoveMilestone}
                onBrainstorm={handleBrainstormSubtasks}
                onHover={setHoveredMilestoneId}
                onStartLinking={handleStartLinking}
                onCompleteLinking={handleCompleteLinking}
                isLinkingMode={!!linkingSourceId}
                isSource={linkingSourceId === milestone.id}
                dateFormat={settings.dateFormat}
                onClick={() => {}}
              />
            ))}
          </div>

          {linkingSourceId && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-indigo-600 text-white px-4 py-2 rounded-full shadow-lg text-sm font-semibold animate-bounce z-50">
              Select a target milestone to link
              <button onClick={() => setLinkingSourceId(null)} className="ml-3 opacity-75 hover:opacity-100 border-l border-indigo-400 pl-2">Cancel</button>
            </div>
          )}

          <div className="absolute bottom-6 left-6 bg-white/80 backdrop-blur-sm border border-slate-200 rounded-full px-4 py-2 text-[10px] font-bold text-slate-400 flex items-center gap-3 shadow-sm z-30 pointer-events-none">
             <div className="flex items-center gap-1"><Activity size={12} className="text-slate-300" /> DRAG TO PAN</div>
             <div className="w-px h-3 bg-slate-200" />
             <div className="flex items-center gap-1"><Move size={12} className="text-slate-300" /> SHIFT+DRAG TO MOVE BRANCH</div>
          </div>
        </div>
      </div>
    );
  }

  // Dashboard View
  return (
    <div className="min-h-screen bg-slate-50 p-6 md:p-8">
      <div className="max-w-7xl mx-auto">

        {/* Dashboard Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">ProjectFlow</h1>
            <p className="text-slate-500 mt-1">Manage your development milestones with AI assistance</p>
          </div>
          <div className="flex items-center gap-3">
             <div className="relative">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
               <input 
                 type="text" 
                 placeholder="Search projects..." 
                 className="pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg shadow-sm focus:ring-2 focus:ring-indigo-500 outline-none w-64 transition-all"
                 value={searchQuery}
                 onChange={(e) => setSearchQuery(e.target.value)}
               />
             </div>
             <button 
               onClick={() => setShowNewProjectModal(true)}
               className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-semibold shadow-sm flex items-center gap-2 transition-all hover:scale-105 active:scale-95"
             >
               <Plus size={18} /> New Project
             </button>
          </div>
        </div>

        {/* Project List */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProjects.map(p => {
            const allTasks = p.milestones.flatMap(m => m.subtasks || []);
            const totalTasks = allTasks.length;
            const completedTasks = allTasks.filter(t => t.status === 'Complete').length;
            const progress = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
            const nextTask = allTasks.find(t => t.status === 'Not started');

            return (
              <div 
                key={p.id}
                className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-shadow group relative flex flex-col"
              >
                <div className="flex justify-between items-start mb-2">
                  <div className="flex-1">
                    <h3 className="text-lg font-bold text-slate-900 leading-tight mb-1">{p.name}</h3>
                    <div className="flex items-center gap-1.5 text-slate-500 text-sm">
                      <Building size={14} />
                      <span>{p.company}</span>
                    </div>
                  </div>
                  <span className="text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-full bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {p.type}
                  </span>
                </div>

                <div className="flex items-center gap-2 text-[10px] text-slate-400 mb-4">
                  <RefreshCw size={10} />
                  <span>Last updated {formatDate(p.updatedAt)}</span>
                </div>

                {/* Progress & Next Task */}
                <div className="mb-5 space-y-3">
                  <div>
                    <div className="flex justify-between text-xs mb-1.5">
                        <span className="font-bold text-slate-500">Progress</span>
                        <span className="font-bold text-slate-900">{progress}%</span>
                    </div>
                    <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
                      <div 
                          className="bg-gradient-to-r from-indigo-500 to-emerald-500 h-full transition-all duration-500" 
                          style={{ width: `${progress}%` }}
                      />
                    </div>
                  </div>

                  {nextTask ? (
                    <div className="bg-slate-50 border border-slate-100 rounded-lg p-2.5">
                      <div className="flex items-center gap-1.5 text-[10px] font-bold text-indigo-600 uppercase tracking-wider mb-1">
                        <Clock size={10} /> Next Action
                      </div>
                      <div className="flex justify-between items-start gap-2">
                          <span className="text-xs font-semibold text-slate-800 line-clamp-2 leading-tight">
                            {nextTask.name}
                          </span>
                          {nextTask.assignedTo && (
                            <span className="shrink-0 text-[10px] px-2 py-0.5 bg-white border border-slate-200 rounded-full text-slate-500 flex items-center gap-1 shadow-sm">
                              <User size={10} /> {nextTask.assignedTo}
                            </span>
                          )}
                      </div>
                    </div>
                  ) : totalTasks > 0 && progress === 100 ? (
                      <div className="bg-emerald-50 border border-emerald-100 rounded-lg p-2.5 flex items-center gap-2 text-emerald-700">
                        <CheckCircle2 size={14} />
                        <span className="text-xs font-bold">Project Complete</span>
                      </div>
                  ) : (
                      <div className="bg-slate-50 border border-slate-100 rounded-lg p-2.5 text-xs text-slate-400 italic text-center">
                        No tasks pending
                      </div>
                  )}
                </div>

                <div className="flex gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide flex-1">
                  {(p.milestones || []).slice(0, 4).map(m => {
                    const safeSubtasks = m.subtasks || [];
                    const complete = safeSubtasks.filter((s: any) => s.status === 'Complete').length;
                    const total = safeSubtasks.length || 1;
                    const progressDeg = (complete / total) * 360;
                    return (
                      <div key={m.id} className="shrink-0 flex flex-col items-center">
                        <div className="w-8 h-8 rounded-full bg-slate-50 ring-1 ring-slate-100 flex items-center justify-center" title={m.name}>
                          <div 
                            className="w-5 h-5 rounded-full" 
                            style={{ background: `conic-gradient(#22c55e ${progressDeg}deg, #f1f5f9 0deg)` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="flex items-center gap-2 mt-auto">
                  <button 
                    onClick={() => { setSelectedProjectId(p.id); setPan({ x: 0, y: 0 }); }}
                    className="flex-1 bg-slate-50 hover:bg-indigo-50 hover:text-indigo-600 text-slate-700 font-semibold py-2 rounded-lg text-sm transition-colors flex items-center justify-center gap-2"
                  >
                    <Eye size={16} /> Open
                  </button>
                  <button onClick={() => handleDuplicateProject(p.id)} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors"><Copy size={16} /></button>
                  <button onClick={() => handleDeleteProject(p.id)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"><X size={16} /></button>
                </div>
              </div>
            );
          })}

          {/* Empty State */}
          {filteredProjects.length === 0 && (
            <div className="col-span-full py-12 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="font-semibold text-lg">No projects found</p>
              <p className="text-sm">Try creating a new project or adjust your search</p>
            </div>
          )}
        </div>
      </div>

      {/* New Project Modal */}
      {showNewProjectModal && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h2 className="text-xl font-bold text-slate-900">Create New Project</h2>
              <button onClick={() => setShowNewProjectModal(false)} className="text-slate-400 hover:text-slate-600"><X size={20} /></button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1.5">Project Name</label>
                <input 
                  type="text" 
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="e.g. Downtown Office Complex"
                  value={newProjectName}
                  onChange={e => setNewProjectName(e.target.value)}
                  autoFocus
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1.5">Project Type</label>
                <div className="grid grid-cols-1 gap-2">
                  {settings.projectTypes.map(t => (
                    <label 
                      key={t}
                      className={`flex items-center px-3 py-2 rounded-lg border cursor-pointer transition-all ${newProjectType === t ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-slate-200 hover:border-slate-300'}`}
                    >
                      <input 
                        type="radio" 
                        name="projectType" 
                        className="sr-only"
                        checked={newProjectType === t}
                        onChange={() => setNewProjectType(t as ProjectType)}
                      />
                      <span className="text-sm font-medium">{t}</span>
                      {newProjectType === t && <CheckCircle2 size={16} className="ml-auto" />}
                    </label>
                  ))}
                </div>
              </div>

              {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-start gap-2">
                  <AlertCircle size={16} className="mt-0.5 shrink-0" />
                  {error}
                </div>
              )}
            </div>

            <div className="p-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
              <button 
                onClick={() => setShowNewProjectModal(false)}
                className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg"
              >
                Cancel
              </button>
              <button 
                onClick={handleCreateProject}
                disabled={isGenerating || !newProjectName}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-medium rounded-lg shadow-sm flex items-center gap-2"
              >
                {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Wand2Icon />}
                {isGenerating ? 'Generating Structure...' : 'Generate Project'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

