    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p,
        updatedAt: Date.now(),
        milestones: p.milestones.map(m => m.id === mId ? { ...m, name: newName } : m)
      };
    }));
