const SettingsSection: React.FC<{ 
  title: string; 
  icon: React.ReactNode; 
  items: string[]; 
  onAdd: (v: string) => void; 
  onRemove: (v: string) => void 
}> = ({ title, icon, items, onAdd, onRemove }) => {
