};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [showSubtasks, setShowSubtasks] = useState(true);
  const [hoveredMilestoneId, setHoveredMilestoneId] = useState<string | null>(null);

  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [isPanning, setIsPanning] = useState(false);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [filterType, setFilterType] = useState<string>('ALL');
  const [filterCompany, setFilterCompany] = useState<string>('ALL');
  const [filterAssignee, setFilterAssignee] = useState<string>('ALL');

  const [isCreatingProject, setIsCreatingProject] = useState(false);
  const [isEditingSubtask, setIsEditingSubtask] = useState<{ mId: string, sIdx: number | null } | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCloudSetupOpen, setIsCloudSetupOpen] = useState(false);
  const [firebaseConfigInput, setFirebaseConfigInput] = useState('');
  const [configError, setConfigError] = useState<string | null>(null);

  const [isGenerating, setIsGenerating] = useState(false);
  const [milestoneToDelete, setMilestoneToDelete] = useState<string | null>(null);
  const [projectToDelete, setProjectToDelete] = useState<string | null>(null);
  const [editingProject, setEditingProject] = useState<Project | null>(null);

  const [linkingSourceId, setLinkingSourceId] = useState<string | null>(null);
  const [showMinimap, setShowMinimap] = useState(true);
  const [cloudStatus, setCloudStatus] = useState<'disconnected' | 'syncing' | 'connected'>('disconnected');
  const isRemoteUpdate = useRef(false);

  const [newProject, setNewProject] = useState({ 
    name: '', company: '', type: '', 
    startDate: new Date().toISOString().split('T')[0],
    cashRequirement: 0, debtRequirement: 0, valueAtCompletion: 0, profit: 0
  });

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return settings.dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const sanitizeProjects = (rawProjects: any): Project[] => {
    if (!rawProjects) return [];
    const projectsList = Array.isArray(rawProjects) ? rawProjects : Object.values(rawProjects);
    return projectsList.map((p: any) => ({
      ...p,
      milestones: (Array.isArray(p.milestones) ? p.milestones : Object.values(p.milestones || [])).map((m: any) => ({
        ...m,
        dependsOn: Array.isArray(m.dependsOn) ? m.dependsOn : Object.values(m.dependsOn || []),
        subtasks: (Array.isArray(m.subtasks) ? m.subtasks : Object.values(m.subtasks || [])).map((s: any) => ({
          ...s
        }))
      }))
    }));
  };

  useEffect(() => {
    if (!firebaseService.isConfigured()) {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          setProjects(sanitizeProjects(parsed.projects));
          setSettings({ ...DEFAULT_SETTINGS, ...parsed.settings });
        } catch (e) {
          console.error("Failed to load local state", e);
        }
      }
      return;
    }
    setCloudStatus('syncing');
    const unsubscribe = firebaseService.subscribe((data) => {
      setCloudStatus('connected');
      if (data) {
        isRemoteUpdate.current = true;
        setProjects(sanitizeProjects(data.projects));
        if (data.settings) {
          setSettings(prev => ({
            ...prev,
            ...data.settings,
            projectTypes: data.settings.projectTypes || prev.projectTypes || DEFAULT_SETTINGS.projectTypes,
            companies: data.settings.companies || prev.companies || DEFAULT_SETTINGS.companies,
            people: data.settings.people || prev.people || DEFAULT_SETTINGS.people,
            statuses: data.settings.statuses || prev.statuses || DEFAULT_SETTINGS.statuses,
          }));
        }
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (isRemoteUpdate.current) {
      isRemoteUpdate.current = false;
      return;
    }
    const saveData = async () => {
      if (firebaseService.isConfigured()) {
        setCloudStatus('syncing');
        await firebaseService.save({ projects, settings });
        setCloudStatus('connected');
      } else {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({ projects, settings }));
      }
    };
    const timer = setTimeout(saveData, 800);
    return () => clearTimeout(timer);
  }, [projects, settings]);

  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      const matchesAssignee = filterAssignee === 'ALL' || p.milestones.some(m => {
        const tasks = Array.isArray(m.subtasks) ? m.subtasks : [];
        return tasks.some(s => (s.assignedTo || '').trim().toLowerCase() === filterAssignee.trim().toLowerCase());
      });
      const matchesType = filterType === 'ALL' || p.type === filterType;
      const matchesCompany = filterCompany === 'ALL' || p.company === filterCompany;
      return matchesAssignee && matchesType && matchesCompany;
    });
  }, [projects, filterAssignee, filterType, filterCompany]);

  const activeProject = useMemo(() => projects.find(p => p.id === selectedProjectId), [projects, selectedProjectId]);

  const canvasData = useMemo(() => {
    if (!activeProject) return { milestones: [], width: 0, height: 0 };
    const levels: Record<string, number> = {};
    const getLevel = (id: string): number => {
      if (levels[id] !== undefined) return levels[id];
      const m = activeProject.milestones.find(mil => mil.id === id);
      if (!m || (m.dependsOn || []).length === 0) {
        levels[id] = 0;
        return 0;
      }
      const parentLevels = m.dependsOn.map(parentId => getLevel(parentId));
      levels[id] = Math.max(...parentLevels) + 1;
      return levels[id];
    };
    activeProject.milestones.forEach(m => getLevel(m.id));
    const groupedByLevel: Record<number, string[]> = {};
    Object.entries(levels).forEach(([id, level]) => {
      if (!groupedByLevel[level]) groupedByLevel[level] = [];
      groupedByLevel[level].push(id);
    });
    const HORIZONTAL_GAP = 360, VERTICAL_GAP = 280, PADDING_X = 400, PADDING_Y = 400;
    const maxLevel = Math.max(...Object.values(levels), 0), maxInLevel = Math.max(...Object.values(groupedByLevel).map(g => g.length), 0);
    const width = Math.max((maxLevel + 1) * HORIZONTAL_GAP + PADDING_X * 2, 2500);
    const height = Math.max((maxInLevel + 1) * VERTICAL_GAP + PADDING_Y * 2, 1800);
    const centerY = height / 2;

    const milestones = activeProject.milestones.map(m => {
      const level = levels[m.id];
      const indexInLevel = groupedByLevel[level].indexOf(m.id), totalInLevel = groupedByLevel[level].length;
      const autoX = PADDING_X + level * HORIZONTAL_GAP;
      const autoY = centerY + (indexInLevel - (totalInLevel - 1) / 2) * VERTICAL_GAP;
      return { ...m, x: m.x !== undefined ? m.x : autoX, y: m.y !== undefined ? m.y : autoY };
    });
    return { milestones, width, height };
  }, [activeProject]);

  const centerView = () => {
    setZoom(1);
    if (!containerRef.current || !canvasData.milestones.length) return;
    const firstM = canvasData.milestones[0];
    if (firstM) {
      setPan({ x: containerRef.current.clientWidth * 0.2 - (firstM.x || 0), y: containerRef.current.clientHeight / 2 - (firstM.y || 0) });
    }
  };

  const handleZoomToExtents = () => {
    if (!containerRef.current) return;
    const viewW = containerRef.current.clientWidth, viewH = containerRef.current.clientHeight;
    const newZoom = Math.min((viewW - 100) / canvasData.width, (viewH - 100) / canvasData.height, 1);
    setZoom(newZoom);
    setPan({ x: (viewW - canvasData.width * newZoom) / 2, y: (viewH - canvasData.height * newZoom) / 2 });
  };

  useEffect(() => { if (selectedProjectId) setTimeout(centerView, 50); }, [selectedProjectId]);

  const projectStats = useMemo(() => {
    if (!activeProject) return null;
    let totalTasks = 0, completedTasks = 0, totalEstimatedDays = 0;
    const statusCount: Record<string, number> = {};
    activeProject.milestones.forEach(m => {
      totalEstimatedDays += (m.estimatedDuration || 0);
      (m.subtasks || []).forEach(s => {
        totalTasks++;
        if (s.status === 'Complete') completedTasks++;
        statusCount[s.status] = (statusCount[s.status] || 0) + 1;
      });
    });
    const finishDate = new Date(activeProject.startDate);
    finishDate.setDate(finishDate.getDate() + totalEstimatedDays);
    return { totalTasks, completedTasks, statusCount, totalEstimatedDays, finishDate };
  }, [activeProject]);

  const handleCreateProject = async (useAI = false) => {
    if (!newProject.name) return;
    setIsGenerating(true);
    let milestones: Milestone[] = [];
    if (useAI) {
      const res = await geminiService.generateProjectStructure(newProject.name, newProject.type as any);
      if (res && res.milestones) {
        milestones = res.milestones.map((m: any) => ({
          ...m, estimatedDuration: 5, dependsOn: m.dependsOn || [],
          subtasks: (m.subtasks || []).map((s: any) => ({
            id: Math.random().toString(36).substr(2, 9), name: s.name, description: s.description, assignedTo: '', notes: '', status: 'Not started'
          }))
        }));
      }
    } else {
      milestones = [{ id: 'm1', name: 'Initial Concept', dependsOn: [], estimatedDuration: 7, subtasks: [{ id: 's1', name: 'Define Scope', description: 'Basic requirements gather', assignedTo: '', notes: '', status: 'Not started' }] }];
    }
    const now = Date.now();
    const project: Project = { 
      id: now.toString(), name: newProject.name, company: newProject.company || settings.companies[0], type: newProject.type || settings.projectTypes[0], 
      startDate: new Date(newProject.startDate).getTime(), cashRequirement: newProject.cashRequirement, debtRequirement: newProject.debtRequirement, 
      valueAtCompletion: newProject.valueAtCompletion, profit: newProject.profit, milestones, createdAt: now, updatedAt: now 
    };
    setProjects([...projects, project]);
    setSelectedProjectId(project.id);
    setIsCreatingProject(false);
    setIsGenerating(false);
  };

  const handleAddMilestone = (pId: string, parentId: string | null, isParallel: boolean) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== pId) return p;
      const newMilestone: Milestone = { id: `m-${Date.now()}`, name: isParallel ? 'New Parallel Branch' : 'Next Milestone', dependsOn: parentId ? [parentId] : [], estimatedDuration: 5, subtasks: [] };
      return { ...p, updatedAt: Date.now(), milestones: [...p.milestones, newMilestone] };
    }));
  };

  const updateSubtask = (mId: string, sIdx: number, updates: Partial<Subtask>) => {
    setProjects(prev => prev.map(p => {
      if (p.id !== selectedProjectId) return p;
      return {
        ...p, updatedAt: Date.now(),
        milestones: p.milestones.map(m => {
          if (m.id !== mId) return m;
          const newSubtasks = [...(m.subtasks || [])];
          newSubtasks[sIdx] = { ...newSubtasks[sIdx], ...updates, completedAt: (updates.status === 'Complete' && newSubtasks[sIdx].status !== 'Complete') ? Date.now() : newSubtasks[sIdx].completedAt };
          return { ...m, subtasks: newSubtasks, completedAt: newSubtasks.every(s => s.status === 'Complete') ? Date.now() : undefined };
        })
      };
    }));
  };

  const updateSettingsList = (key: keyof AppSettings, value: string, action: 'add' | 'remove') => {
    setSettings(prev => {
      let newList = [...(prev[key] as string[])];
      if (action === 'add' && value.trim() && !newList.includes(value)) newList.push(value);
      else if (action === 'remove') newList = newList.filter(i => i !== value);
      return { ...prev, [key]: newList };
    });
  };

  return (
    <div className="h-screen w-screen flex flex-col text-slate-900 bg-slate-50 overflow-hidden">
      <header className="bg-white border-b border-slate-200 px-4 md:px-6 py-4 flex items-center justify-between sticky top-0 z-50 shadow-sm shrink-0">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg text-white"><Layers size={24} /></div>
          <h1 className="text-xl font-bold text-slate-900 tracking-tight">ProjectFlow</h1>
          <button onClick={() => setIsCloudSetupOpen(true)} className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold border transition-colors ${firebaseService.isConfigured() ? (cloudStatus === 'connected' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-indigo-50 text-indigo-600 border-indigo-200') : 'bg-amber-50 text-amber-600 border-amber-200'}`}>
            {cloudStatus === 'syncing' ? <RefreshCw size={12} className="animate-spin" /> : <Cloud size={12} />}
            {firebaseService.isConfigured() ? (cloudStatus === 'syncing' ? 'SYNCING...' : 'CLOUD ACTIVE') : 'LOCAL ONLY'}
          </button>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"><Settings size={20} /></button>
          {selectedProjectId && <button onClick={() => setSelectedProjectId(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 font-medium px-3 py-1.5 rounded-lg transition-colors"><ChevronLeft size={18} /> Dashboard</button>}
          <button onClick={() => setIsCreatingProject(true)} className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-4 py-2 rounded-lg flex items-center gap-2 shadow-sm transition-all active:scale-95"><Plus size={18} /> New Project</button>
        </div>
      </header>

      <main className="flex-1 overflow-hidden relative flex">
        {!selectedProjectId ? (
          <div className="flex-1 p-4 md:p-8 max-w-7xl mx-auto h-full overflow-y-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
              <h2 className="text-2xl font-bold text-slate-800">Your Projects</h2>
              <div className="flex flex-wrap items-center gap-3">
                <div className="relative">
                  <User size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                  <select className="bg-white border border-slate-300 rounded-lg pl-9 pr-8 py-1.5 text-sm text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 w-56 shadow-sm appearance-none cursor-pointer" value={filterAssignee} onChange={(e) => setFilterAssignee(e.target.value)}>
                    <option value="ALL">All Team Members</option>
                    {(settings.people || []).map(p => <option key={p} value={p}>{p}</option>)}
                  </select>
                  <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                </div>
                <div className="flex items-center gap-2">
                  <Filter size={18} className="text-slate-400" />
                  <select className="bg-white border border-slate-300 rounded-lg px-3 py-1.5 text-sm text-slate-900 outline-none focus:ring-2 focus:ring-indigo-500 shadow-sm" value={filterType} onChange={(e) => setFilterType(e.target.value)}>
                    <option value="ALL">All Types</option>
