              <SettingsSection title="Project Types" icon={<Tags size={18} />} items={settings.projectTypes} onAdd={(v) => updateSettingsList('projectTypes', v, 'add')} onRemove={(v) => updateSettingsList('projectTypes', v, 'remove')} />
            </div>
