      {isCreatingProject && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl p-8 overflow-hidden relative border border-slate-200">
            <h3 className="text-2xl font-black text-slate-900 mb-6">Start New Project</h3>
            <div className="grid grid-cols-2 gap-6 mb-8">
              <div className="col-span-2"><label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Project Identity</label><input type="text" className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold" value={newProject.name} onChange={(e) => setNewProject({ ...newProject, name: e.target.value })} placeholder="Project Name" /></div>
              <div><label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Company</label><select className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold" value={newProject.company} onChange={(e) => setNewProject({ ...newProject, company: e.target.value })}><option value="">Select...</option>{(settings.companies || []).map(c => <option key={c} value={c}>{c}</option>)}</select></div>
              <div><label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Category</label><select className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-3 outline-none focus:border-indigo-500 text-slate-900 font-bold" value={newProject.type} onChange={(e) => setNewProject({ ...newProject, type: e.target.value })}><option value="">Select...</option>{(settings.projectTypes || []).map(t => <option key={t} value={t}>{t}</option>)}</select></div>
            </div>
            <div className="flex gap-4">
              <button onClick={() => setIsCreatingProject(false)} className="flex-1 bg-slate-100 hover:bg-slate-200 text-slate-700 font-black py-4 rounded-2xl transition-all">Cancel</button>
              <button onClick={() => handleCreateProject(false)} className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-black py-4 rounded-2xl transition-all">Create Project</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

