import { initializeApp } from 'firebase/app';
import { getDatabase, ref, set, onValue, push, query, limitToLast, get } from 'firebase/database';
import { Project, AppSettings, LogEntry } from '../types';

const CONFIG_STORAGE_KEY = 'projectflow_firebase_config';
const DISCONNECT_FLAG_KEY = 'projectflow_manual_disconnect';

let db: any = null;
let app: any = null;
let isConfigured = false;

// specific parsing to handle the user pasting the raw JS object from Firebase console
const parseConfig = (raw: string | null) => {
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (e) {
    try {
      const cleaned = raw
        .replace(/const\s+\w+\s*=\s*/, '') 
        .replace(/;/g, '') 
        .replace(/(\w+):/g, '"$1":') 
        .replace(/'/g, '"'); 
      return JSON.parse(cleaned);
    } catch (e2) {
      return null;
    }
  }
};

try {
  // Check if manually disconnected to prevent auto-reconnect loop
  const isManuallyDisconnected = localStorage.getItem(DISCONNECT_FLAG_KEY) === 'true';

  if (!isManuallyDisconnected) {
    // Check local storage only. No default fallback.
    const saved = localStorage.getItem(CONFIG_STORAGE_KEY);
    const config = parseConfig(saved);

    if (config && config.databaseURL) {
      try {
        app = initializeApp(config);
        db = getDatabase(app);
        isConfigured = true;
        console.log(`[Firebase] Initialized. Connected to Project: ${config.projectId}`);
      } catch(err) {
        console.error("[Firebase] Init Error:", err);
      }
    }
  } else {
    console.log("[Firebase] Manual disconnect flag found. Skipping auto-connection.");
  }
} catch (e) {
  console.error("[Firebase] Critical Error:", e);
}

// Internal helper to push logs
const internalLog = (type: 'INFO' | 'WARN' | 'ERROR' | 'SUCCESS', message: string, details?: any) => {
  if (!db) {
    console.log(`[Offline Log - ${type}] ${message}`, details);
    return;
  }
  try {
    const logsRef = ref(db, 'projectflow_logs');
    const entry: Omit<LogEntry, 'id'> = {
      timestamp: Date.now(),
      type,
      message,
      details: details ? JSON.stringify(details) : undefined,
      projectId: app?.options?.projectId || 'unknown'
    };
    push(logsRef, entry).catch(e => console.error("Failed to push log:", e));
  } catch(e) {
    console.error("Logging Error:", e);
  }
};

export const firebaseService = {
  isConfigured: () => isConfigured,

  getProjectId: () => {
    return app?.options?.projectId || 'Unknown';
  },

  // Expose log function to App.tsx
  logEvent: (type: 'INFO' | 'WARN' | 'ERROR' | 'SUCCESS', message: string, details?: any) => {
    internalLog(type, message, details);
  },

  getLogs: async (limit = 50): Promise<LogEntry[]> => {
    if (!db) return [];
    try {
      const logsRef = ref(db, 'projectflow_logs');
      const q = query(logsRef, limitToLast(limit));
      const snapshot = await get(q);
      const data = snapshot.val();
      if (!data) return [];

      // Convert object to array and sort descending (newest first)
      return Object.entries(data).map(([key, val]: [string, any]) => ({
        id: key,
        ...val
      })).sort((a, b) => b.timestamp - a.timestamp);
    } catch (e) {
      console.error("Failed to fetch logs:", e);
      return [];
    }
  },

  configure: (configString: string) => {
    console.log("[Firebase] Attempting to configure new credentials...");
    const config = parseConfig(configString);
    if (config && config.databaseURL) {
      console.log(`[Firebase] Configuration valid for project: ${config.projectId}`);
      localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(config));
      localStorage.removeItem(DISCONNECT_FLAG_KEY); // Clear manual disconnect flag
      window.location.reload();
      return true;
    }
    console.error("[Firebase] Invalid configuration provided.");
    return false;
  },

  disconnect: () => {
    console.log("[Firebase] Disconnecting...");
    internalLog('WARN', 'User manually disconnected from Firebase');
    localStorage.removeItem(CONFIG_STORAGE_KEY);
    localStorage.setItem(DISCONNECT_FLAG_KEY, 'true'); // Set manual disconnect flag
    window.location.reload();
  },

  subscribe: (
    onData: (data: { projects: Project[], settings: AppSettings } | null) => void,
    onError?: (error: Error) => void
  ) => {
    if (!db) {
      console.warn("[Firebase] Subscribe called but DB not initialized.");
      return () => {};
    }

    console.log("[Firebase] Subscribing to data stream...");
    const dataRef = ref(db, 'projectflow_v1');
    return onValue(dataRef, (snapshot) => {
      const data = snapshot.val();
      const projectCount = data?.projects ? (Array.isArray(data.projects) ? data.projects.length : Object.keys(data.projects).length) : 0;

      console.log(`[Firebase] Data received. Project count: ${projectCount}`);

      // Log significant state changes or empty states
      if (projectCount === 0) {
        internalLog('WARN', 'Received EMPTY project list from cloud.', { rawData: data });
      } else {
        // internalLog('INFO', `Received update from cloud. ${projectCount} projects.`);
      }

      onData(data);
    }, (error) => {
      console.error("[Firebase] Read Error:", error);
      internalLog('ERROR', 'Firebase Subscription Error', { error: error.message });
      if (onError) onError(error);
    });
  },

  save: async (data: { projects: Project[], settings: AppSettings }) => {
    if (!db) throw new Error("Database not initialized");

    // SAFETY GUARD: Prevent writing empty project lists
    if (!data.projects || data.projects.length === 0) {
      const msg = "SAFETY BLOCK: Attempted to write empty project list. Operation cancelled.";
      console.error(`[Firebase] ${msg}`);
      internalLog('ERROR', msg, { projectCount: data.projects?.length });
      throw new Error("Safety Block: Cannot save empty project list.");
    }

    const projectId = app?.options?.projectId;
    console.log(`[Firebase] Saving data... Projects: ${data.projects.length}. Project ID: ${projectId}`);

    const dataRef = ref(db, 'projectflow_v1');

    // Sanitize data to remove undefined values which Firebase rejects.
    const cleanData = JSON.parse(JSON.stringify({
      projects: data.projects || [],
      settings: data.settings,
      lastUpdated: Date.now()
    }));

    try {
      await set(dataRef, cleanData);
      internalLog('SUCCESS', `Saved ${data.projects.length} projects to cloud.`, { timestamp: Date.now() });
      console.log("[Firebase] Save successful.");
    } catch (e: any) {
      internalLog('ERROR', 'Failed to save data to cloud.', { error: e.message });
      throw e;
    }
  }
};

