import { initializeApp } from 'firebase/app';
import { getDatabase, ref, set, onValue, push, query, limitToLast, get, update } from 'firebase/database';
import { Project, AppSettings, LogEntry } from '../types';

const CONFIG_STORAGE_KEY = 'projectflow_firebase_config';
const DISCONNECT_FLAG_KEY = 'projectflow_manual_disconnect';

let db: any = null;
let app: any = null;
let isConfigured = false;

// Internal helper to push logs
const internalLog = (type: 'INFO' | 'WARN' | 'ERROR' | 'SUCCESS', message: string, details?: any) => {
  if (!db) {
    console.log(`[Offline Log - ${type}] ${message}`, details);
    return;
  }
  try {
    const logsRef = ref(db, 'projectflow_logs');

    // Construct object carefully to avoid 'undefined' values which Firebase rejects
    const entry: Record<string, any> = {
      timestamp: Date.now(),
      type,
      message,
      projectId: app?.options?.projectId || 'unknown'
    };

    if (details !== undefined && details !== null) {
      try {
        const stringified = typeof details === 'string' ? details : JSON.stringify(details);
        // JSON.stringify can return undefined for functions/symbols, ensuring we don't assign undefined to the object
        if (stringified) {
          entry.details = stringified;
        }
      } catch (e) {
        entry.details = "Circular or invalid details object";
      }
    }

    push(logsRef, entry).catch(e => console.error("Failed to push log:", e));
  } catch(e) {
    console.error("Logging Error:", e);
  }
};

// Robust parsing to handle raw JS objects pasted from Firebase console
const parseConfig = (raw: string | null) => {
  if (!raw) return null;
  try {
    // First try standard JSON parse
    return JSON.parse(raw);
  } catch (e) {
    try {
      // Heuristic parsing for JS object literal
      let cleaned = raw;

      // 1. Remove single-line comments (// ...) 
      // Match start of line or whitespace followed by // until end of line
      cleaned = cleaned.replace(/^\s*\/\/.*$/gm, '');

      // 2. Remove "const firebaseConfig =" and trailing semicolon
      cleaned = cleaned.replace(/const\s+\w+\s*=\s*/, '').replace(/;\s*$/, '');

      // 3. Wrap known keys in quotes. 
      // We use a specific list to avoid breaking URLs (like "https:" which looks like a key).
      const keys = ['apiKey', 'authDomain', 'databaseURL', 'projectId', 'storageBucket', 'messagingSenderId', 'appId', 'measurementId'];
      keys.forEach(key => {
        // Match key followed by colon, possibly with whitespace, ensuring it's a key property
        const regex = new RegExp(`(^|[\\s{,])(${key})\\s*:`, 'g');
        cleaned = cleaned.replace(regex, `$1"${key}":`);
      });

      // 4. Convert single quotes to double quotes for JSON compatibility
      // (Assuming values don't contain unescaped single quotes)
      cleaned = cleaned.replace(/'/g, '"');

      // 5. Remove trailing commas which invalidates JSON
      cleaned = cleaned.replace(/,(\s*})/g, '$1');

      console.log("[Firebase] Parsed config string:", cleaned);
      return JSON.parse(cleaned);
    } catch (e2) {
      console.error("Config Parse Error:", e2);
      internalLog('ERROR', 'Failed to parse configuration string', { error: String(e2) });
      return null;
    }
  }
};

try {
  // Check if manually disconnected to prevent auto-reconnect loop
  const isManuallyDisconnected = localStorage.getItem(DISCONNECT_FLAG_KEY) === 'true';

  if (!isManuallyDisconnected) {
    // Check local storage only. No default fallback.
    const saved = localStorage.getItem(CONFIG_STORAGE_KEY);
    const config = parseConfig(saved);

    if (config && config.databaseURL) {
      try {
        app = initializeApp(config);
        db = getDatabase(app);
        isConfigured = true;
        console.log(`[Firebase] Initialized. Connected to Project: ${config.projectId}`);
      } catch(err) {
        console.error("[Firebase] Init Error:", err);
      }
    }
  } else {
    console.log("[Firebase] Manual disconnect flag found. Skipping auto-connection.");
  }
} catch (e) {
  console.error("[Firebase] Critical Error:", e);
}

export const firebaseService = {
  isConfigured: () => isConfigured,

  getProjectId: () => {
    return app?.options?.projectId || 'Unknown';
  },

  // Expose log function to App.tsx
  logEvent: (type: 'INFO' | 'WARN' | 'ERROR' | 'SUCCESS', message: string, details?: any) => {
    internalLog(type, message, details);
  },

  getLogs: async (limit = 50): Promise<LogEntry[]> => {
    if (!db) return [];
    try {
      const logsRef = ref(db, 'projectflow_logs');
      const q = query(logsRef, limitToLast(limit));
      const snapshot = await get(q);
      const data = snapshot.val();
      if (!data) return [];

      // Convert object to array and sort descending (newest first)
      return Object.entries(data).map(([key, val]: [string, any]) => ({
        id: key,
        ...val
      })).sort((a, b) => b.timestamp - a.timestamp);
    } catch (e) {
      console.error("Failed to fetch logs:", e);
      return [];
    }
  },

  checkConnection: async () => {
    if (!db) return { success: false, message: "Database not initialized" };
    try {
      // Try to write a temporary test node
      const testId = 'test_' + Date.now();
      const testRef = ref(db, 'projectflow_diagnostics/' + testId);
      await set(testRef, { 
        timestamp: Date.now(), 
        status: 'OK', 
        userAgent: navigator.userAgent 
      });

      // If successful, clean it up immediately
      await set(testRef, null);

      internalLog('SUCCESS', 'Diagnostic connection test passed.');
      return { success: true, message: "Read/Write Access Confirmed" };
    } catch (e: any) {
      const msg = e.message || "Unknown Error";
      console.error("Diagnostic Test Failed:", e);
      internalLog('ERROR', 'Diagnostic connection test failed.', { error: msg });
      return { success: false, message: msg };
    }
  },

  configure: (configString: string) => {
    console.log("[Firebase] Attempting to configure new credentials...");
    const config = parseConfig(configString);
    if (config && config.databaseURL) {
      console.log(`[Firebase] Configuration valid for project: ${config.projectId}`);
      localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(config));
      localStorage.removeItem(DISCONNECT_FLAG_KEY); // Clear manual disconnect flag
      window.location.reload();
      return true;
    }
    console.error("[Firebase] Invalid configuration provided.");
