  getLogs: async (limit = 50) => {
    if (!db) return [];
    try {
      const logsRef = ref(db, 'projectflow_logs');
      const q = query(logsRef, limitToLast(limit));
      const snapshot = await get(q);
      const data = snapshot.val();
      if (!data) return [];
      return Object.entries(data).map(([key, val]: [string, any]) => ({
        id: key,
        ...val
      })).sort((a, b) => b.timestamp - a.timestamp);
    } catch (e) {
      console.error("Failed to fetch logs:", e);
      return [];
    }
  },

  checkConnection: async () => {
    if (!db) return { success: false, message: "Database not initialized" };
    try {
      const testRef = ref(db, 'projectflow_diagnostics/' + Date.now());
      await set(testRef, { status: 'OK' });
      await set(testRef, null);
      return { success: true, message: "Connected" };
    } catch (e: any) {
      return { success: false, message: e.message };
    }
  },

  configure: (configString: string) => {
    const config = parseConfig(configString);
    if (config && config.databaseURL) {
      localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(config));
      localStorage.removeItem(DISCONNECT_FLAG_KEY); // Clear manual disconnect flag
      window.location.reload();
      return true;
    }
    return false;
  },

  disconnect: () => {
    localStorage.removeItem(CONFIG_STORAGE_KEY);
    localStorage.setItem(DISCONNECT_FLAG_KEY, 'true'); // Set manual disconnect flag
    window.location.reload();
  },

  subscribe: (
    onData: (data: { projects: Project[], settings: AppSettings } | null) => void,
    onError?: (error: Error) => void
  ) => {
    if (!db) return () => {};

    const dataRef = ref(db, 'projectflow_v1');
    return onValue(dataRef, (snapshot) => {
      const data = snapshot.val();
      onData(data);
    }, (error) => {
      console.error("Firebase Read Error:", error);
      if (onError) onError(error);
    });
  },

  // NEW: Explicit delete method required because save() uses merge logic
  deleteProject: async (projectId: string) => {
    if (!db) return;
    try {
      // We must explicitly set this specific node to null to delete it
      // because the main save() method now uses 'update' which ignores missing keys
      const projectRef = ref(db, `projectflow_v1/projects/${projectId}`);
      await set(projectRef, null);
      internalLog('SUCCESS', `Deleted project ${projectId}`);
    } catch (e: any) {
      internalLog('ERROR', `Failed to delete project ${projectId}`, { error: e.message });
      throw e;
    }
  },

  save: async (data: { projects: Project[], settings: AppSettings }) => {
    if (!db) throw new Error("Database not initialized");

    // SAFETY GUARD: Prevent writing empty project lists
    if (!data.projects || data.projects.length === 0) {
      // With the new deleteProject strategy, we generally don't want to 
      // save an empty list anyway. Deletions should happen via deleteProject.
      return; 
    }

    // STRATEGY: Use atomic multi-path updates (Option B) instead of setting the root (Option A).
    // This allows us to update specific projects without wiping the entire tree.
    // It also converts the array to an object map for safer storage.

    const updates: Record<string, any> = {};
    const rootPath = 'projectflow_v1';

    // 1. Update Settings
    updates[`${rootPath}/settings`] = data.settings;
    updates[`${rootPath}/lastUpdated`] = Date.now();

    // 2. Update Projects (Map by ID)
    // We strictly use project IDs as keys. This prevents array index collisions.
    data.projects.forEach(project => {
      if (project.id) {
        updates[`${rootPath}/projects/${project.id}`] = project;
      }
    });

    // 3. Perform atomic update
    try {
      await update(ref(db), updates);
      internalLog('SUCCESS', `Saved ${data.projects.length} projects using atomic update.`);
    } catch (e: any) {
      internalLog('ERROR', 'Save Failed', { error: e.message });
      throw e;
    }
  }
};

