                 <defs>
                   <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                     <polygon points="0 0, 10 3.5, 0 7" fill="#cbd5e1" />
                   </marker>
                   <marker id="arrowhead-active" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
                     <polygon points="0 0, 10 3.5, 0 7" fill="#6366f1" />
                   </marker>
                 </defs>
                 {canvasData.milestones.map(m => (m.dependsOn || []).map(parentId => {
                   const parent = canvasData.milestones.find(p => p.id === parentId);
                   if (!parent) return null;

                   const isHovered = hoveredMilestoneId === m.id || hoveredMilestoneId === parent.id;

                   // Bezier Curve Logic
                   const startX = parent.x || 0;
                   const startY = parent.y || 0;
                   const endX = m.x || 0;
                   const endY = m.y || 0;

                   const dist = Math.sqrt(Math.pow(endX - startX, 2) + Math.pow(endY - startY, 2));
                   const curvature = Math.min(dist * 0.5, 150);

                   const path = `M ${startX} ${startY} C ${startX + curvature} ${startY}, ${endX - curvature} ${endY}, ${endX} ${endY}`;

                   return (
                     <g key={`${parent.id}-${m.id}`}>
                       <path 
                         d={path} 
                         fill="none" 
                         stroke={isHovered ? "#6366f1" : "#cbd5e1"} 
                         strokeWidth={isHovered ? 3 : 2} 
                         strokeDasharray={isHovered ? "none" : "5,5"}
                         markerEnd={isHovered ? "url(#arrowhead-active)" : "url(#arrowhead)"}
                         className="transition-all duration-300"
                       />
                     </g>
                   );
                 }))}

                 {/* Linking Mode Line Preview */}
                 {linkingSourceId && (
                   (() => {
                     const source = canvasData.milestones.find(m => m.id === linkingSourceId);
                     if (source) {
