            {configError && (
              <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 border border-red-200 flex items-start gap-2">
                <ShieldAlert size={16} className="mt-0.5 shrink-0" />
                {configError}
              </div>
            )}

            <textarea 
              className="w-full h-40 bg-slate-50 border border-slate-200 rounded-xl p-4 text-xs font-mono text-slate-600 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 transition-all resize-none"
              placeholder={`const firebaseConfig = {\n  apiKey: "...",\n  authDomain: "...",\n  databaseURL: "...",\n  ...\n};`}
              value={firebaseConfigInput}
              onChange={(e) => setFirebaseConfigInput(e.target.value)}
            />

            <div className="flex gap-3 mt-6">
              <button 
                onClick={() => setIsCloudSetupOpen(false)}
                className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={handleSaveFirebaseConfig}
                className="flex-1 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-700 shadow-md transition-all active:scale-95"
              >
                Connect
              </button>
            </div>

            <p className="mt-6 text-center text-xs text-slate-400">
              Don't have a database? <a href="#" className="underline hover:text-indigo-500">View Setup Guide</a>
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

