import { initializeApp, getApps, getApp } from 'firebase/app';
import { getDatabase, ref, set, onValue } from 'firebase/database';
import { Project, AppSettings } from '../types';

const CONFIG_STORAGE_KEY = 'projectflow_firebase_config';
const DISCONNECT_FLAG_KEY = 'projectflow_manual_disconnect';

// REMOVED DEFAULT CONFIG: Using hardcoded credentials causes all users to sync to the same 
// public database, leading to data overwrites/loss.
// The app will now default to LOCAL STORAGE unless the user explicitly provides their own credentials.
const DEFAULT_CONFIG = null;

let db: any = null;
let isConfigured = false;

// specific parsing to handle the user pasting the raw JS object from Firebase console
const parseConfig = (raw: string | null) => {
  if (!raw) return null;

  // 1. Remove comments
  let text = raw.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');

  // 2. Extract content between braces to ignore external assignments like "const firebaseConfig = "
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1) return null;

  const content = text.substring(firstBrace + 1, lastBrace);

  // Strategy A: Regex Extraction (Robust against JS syntax quirks)
  // Matches: key : "value" or 'key' : 'value' or "key": "value"
  // Handles multi-line values via [\s\S]
  const config: Record<string, string> = {};

  // Regex explanation:
  // (?:['"]?)          -> Optional opening quote for key
  // ([a-zA-Z0-9_]+)    -> Group 1: The key
  // (?:['"]?)          -> Optional closing quote for key
  // \s*:\s*            -> Colon with whitespace
  // (['"])             -> Group 2: The value's opening quote
  // ([\s\S]*?)         -> Group 3: The value (non-greedy, matches newlines)
  // \2                 -> Match the same quote as Group 2
  const regex = /(?:['"]?)([a-zA-Z0-9_]+)(?:['"]?)\s*:\s*(['"])([\s\S]*?)\2/g;

  let match;
  let matchesFound = false;
  while ((match = regex.exec(content)) !== null) {
    matchesFound = true;
    config[match[1]] = match[3];
  }

  // Check if we got a valid config object
  if (matchesFound && config.databaseURL) {
    return config;
  }

  // Strategy B: JSON Parse (Strict / Relaxed)
  // If Regex failed (maybe keys have dashes? or weird structure?), try parsing as JSON
  try {
    const jsonStr = text.substring(firstBrace, lastBrace + 1); 
    return JSON.parse(jsonStr);
  } catch (e) {
    try {
      // Relaxed JSON parsing
      let jsonString = text.substring(firstBrace, lastBrace + 1);

      // 1. Fix unquoted keys: identifier followed by colon
      jsonString = jsonString.replace(/(^|[\s{,])([a-zA-Z0-9_]+)\s*:/g, '$1"$2":');

      // 2. Fix single quotes to double quotes (safely-ish)
      // This is a naive replace, might break if value contains single quotes, 
      // but usually firebase config values are simple strings.
      jsonString = jsonString.replace(/'/g, '"');

      // 3. Remove trailing commas
      jsonString = jsonString.replace(/,(\s*})/g, '$1');

      // 4. CRITICAL FIX: Remove newlines to prevent "Bad control character" in JSON strings
      // Firebase config values (urls, keys) should not contain newlines anyway.
      // We replace with space to preserve separation if it was outside strings, 
      // but essentially we are flattening the object.
      jsonString = jsonString.replace(/[\n\r]/g, ' ');

      return JSON.parse(jsonString);
    } catch (e2) {
      console.error("Config Parsing Failed:", e2);
      return null;
    }
  }
};

try {
  // Check if manually disconnected to prevent auto-reconnect loop
  const isManuallyDisconnected = localStorage.getItem(DISCONNECT_FLAG_KEY) === 'true';

  // Check local storage first
  const saved = localStorage.getItem(CONFIG_STORAGE_KEY);

  // Only initialize if we have a valid SAVED config. 
  if (!isManuallyDisconnected && saved) {
    const config = parseConfig(saved);
    if (config && config.databaseURL) {
      try {
        // Check if already initialized to avoid "Firebase App named '[DEFAULT]' already exists" error
        const app = getApps().length === 0 ? initializeApp(config) : getApp();
