}

export const CloudSetupModal: React.FC<CloudSetupModalProps> = ({ 
  isOpen, onClose, cloudStatus, syncError, onDisconnect, onRestoreBackup 
}) => {
  const [firebaseConfigInput, setFirebaseConfigInput] = useState('');
