                  <button 
                    onClick={onRestoreBackup}
                    className="bg-white border-2 border-indigo-100 hover:border-indigo-600 text-indigo-700 font-bold px-4 py-2 rounded-lg transition-colors whitespace-nowrap active:scale-95"
