// specific parsing to handle the user pasting the raw JS object from Firebase console
const parseConfig = (raw: string | null) => {
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (e) {
    try {
      // 1. Remove comments (single line and multi-line)
      let cleaned = raw.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '');

      // 2. Remove variable declaration (const firebaseConfig = ...)
      cleaned = cleaned.replace(/const\s+\w+\s*=\s*/, '');

      // 3. Remove semicolons
      cleaned = cleaned.replace(/;/g, '');

      // 4. Quote keys that are not already quoted
      // We look for word chars followed by a colon, but ONLY if preceded by { or , or whitespace
      // This avoids matching "https:" inside a URL string
      cleaned = cleaned.replace(/(^|[\s,{])([a-zA-Z0-9_]+)\s*:/g, '$1"$2":');

      // 5. Replace single quotes with double quotes
      cleaned = cleaned.replace(/'/g, '"');

      // 6. Remove trailing commas before closing braces/brackets (invalid in JSON)
      cleaned = cleaned.replace(/,(\s*[}\]])/g, '$1');

      return JSON.parse(cleaned);
