                        </div>
                      </div>
                    </div>

                    {/* Linking Helper UI */}
                    {linkingSourceId && (
                      <div className="absolute top-6 left-1/2 -translate-x-1/2 bg-indigo-600 text-white rounded-full px-6 py-2.5 shadow-lg shadow-indigo-200 z-50 flex items-center gap-4 animate-in slide-in-from-top-4">
