        <div className="flex items-center gap-1 bg-slate-100 p-1 rounded-lg">
          <button 
            onClick={() => setIsKanbanMode(false)}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-bold transition-all ${
