        {/* Header Actions */}
        <div className="flex items-center gap-2 shrink-0">
          <button onClick={() => setIsSettingsOpen(true)} className="p-2 text-slate-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors" title="Settings">
            <Settings size={20} />
