// App.tsx
import React, { useState, useEffect } from 'react';
import './App.css';
import KanbanBoard from './components/KanbanBoard';
import { AppSettings, Task } from './types'; // Import Task type
import { mockTasks } from './mockTasks';
import { saveSettingsToLocalStorage, getSettingsFromLocalStorage } from './utils';

const DEFAULT_SETTINGS: AppSettings = {
  projectTypes: [
    "Subdivision",
    "Greenfield Development",
    "Commercial",
    "Residential",
    "Other",
    "Build",
    "Brownfield development",
    "Flip"
  ],
  companies: [
    "MyBuild",
    "LandmarX",
    "HealX"
  ],
  people: [
    "Jorian",
    "Kiera",
    "Beau",
    "Other",
    "Unassigned"
  ],
  statuses: [
    "Not started", // <--- CHANGE HERE
    "Started",
    "Held",
    "Complete"
  ],
  dateFormat: 'DD/MM/YY'
};

function App() {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [tasks, setTasks] = useState<Task[]>(mockTasks);
