      setProjects(prev => prev.map(p => p.id === selectedProjectId ? { ...p, updatedAt: Date.now(), milestones: p.milestones.map(m => m.id === targetId ? { ...m, dependsOn: [...(m.dependsOn || []), linkingSourceId] } : m) } : p));
