                             <div className="relative bg-slate-50 rounded-lg overflow-hidden border border-slate-100" style={{ height: '160px' }}>
                                {/* Minimap SVG Logic (Simplified re-render for brevity, same as original) */}
                                {(() => {
                                  const mapWidth=240, mapHeight=160;
                                  const scale = Math.min(mapWidth/Math.max(canvasData.width,1), mapHeight/Math.max(canvasData.height,1));
                                  const offsetX = (mapWidth - canvasData.width*scale)/2, offsetY = (mapHeight - canvasData.height*scale)/2;
                                  return (
                                    <svg width="100%" height="100%" viewBox={`0 0 ${mapWidth} ${mapHeight}`} className="cursor-pointer" onClick={(e) => {
                                       const rect = e.currentTarget.getBoundingClientRect();
                                       setPan({ x: (containerRef.current?.clientWidth||0)/2 - ((e.clientX - rect.left - offsetX)/scale)*zoom, y: (containerRef.current?.clientHeight||0)/2 - ((e.clientY - rect.top - offsetY)/scale)*zoom });
                                    }}>
                                       <g transform={`translate(${offsetX}, ${offsetY}) scale(${scale})`}>
                                          {canvasData.milestones.map(m => (m.dependsOn||[]).map(pid => {
                                            const p = canvasData.milestones.find(x=>x.id===pid);
                                            if(!p) return null;
                                            return <path key={`m-${pid}-${m.id}`} d={`M ${(p.x||0)+50} ${p.y} C ${(p.x||0)+((m.x||0)-(p.x||0))/2} ${p.y}, ${(p.x||0)+((m.x||0)-(p.x||0))/2} ${m.y}, ${(m.x||0)-50} ${m.y}`} stroke="#cbd5e1" strokeWidth="4" fill="none" />
                                          }))}
                                          {canvasData.milestones.map(m => <circle key={m.id} cx={m.x} cy={m.y} r={10} fill="#6366f1" />)}
                                       </g>
                                       <rect x={(-pan.x/zoom)*scale + offsetX} y={(-pan.y/zoom)*scale + offsetY} width={((containerRef.current?.clientWidth||0)/zoom)*scale} height={((containerRef.current?.clientHeight||0)/zoom)*scale} fill="none" stroke="#6366f1" strokeWidth="2" />
                                    </svg>
                                  )
                                })()}
                             </div>
                           </div>
                        )}
                      </div>
                    </div>

                    {/* MAIN SVG CANVAS */}
                    <div className="absolute transition-transform duration-300 ease-out" style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`, transformOrigin: '0 0' }}>
                      <div style={{ width: canvasData.width, height: canvasData.height }}>
                        <svg className="absolute inset-0 pointer-events-none" width={canvasData.width} height={canvasData.height}>
                          <defs>
                            <marker id="arrow" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#cbd5e1" /></marker>
                            <marker id="arrow-active" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#6366f1" /></marker>
                          </defs>
                          {canvasData.milestones.map(m => (m.dependsOn || []).map(parentId => {
                            const parent = canvasData.milestones.find(mil => mil.id === parentId);
                            if (!parent) return null;
                            const isActive = hoveredMilestoneId === m.id || hoveredMilestoneId === parentId;
                            const dx = (m.x || 0) - (parent.x || 0);
                            return (
                              <path key={`${parentId}-${m.id}`} d={`M ${(parent.x || 0) + 50} ${parent.y!} C ${(parent.x || 0) + dx / 2} ${parent.y!}, ${(parent.x || 0) + dx / 2} ${m.y!}, ${(m.x || 0) - 50} ${m.y!}`} stroke={isActive ? "#6366f1" : "#cbd5e1"} strokeWidth={isActive ? "3" : "2"} fill="transparent" markerEnd={isActive ? "url(#arrow-active)" : "url(#arrow)"} className="transition-all duration-300" />
                            );
                          }))}
                        </svg>
                        <div className="absolute inset-0 pointer-events-none">
                          {canvasData.milestones.map(m => (
                            <div key={m.id} className="pointer-events-auto">
                              <MilestoneNode 
                                milestone={m}
                                showSubtasks={showSubtasks}
                                onAddSubtask={handleAddSubtask}
                                onAddSequence={(id) => handleAddMilestone(activeProject!.id, id, false)}
                                onAddPrevious={(id) => handleAddPreviousStep(activeProject!.id, id)}
                                onAddParallel={(id) => handleAddMilestone(activeProject!.id, id, true)}
                                onEditSubtask={(mId, sIdx) => setIsEditingSubtask({ mId, sIdx })}
                                onUpdateName={handleUpdateMilestoneName}
                                onUpdateDuration={handleUpdateMilestoneDuration}
                                onDeleteMilestone={handleDeleteMilestone}
                                onMove={handleMoveMilestone}
                                onBrainstorm={handleBrainstormSubtasks}
                                onHover={setHoveredMilestoneId}
                                onStartLinking={handleStartLinking}
                                onCompleteLinking={handleCompleteLinking}
                                isLinkingMode={!!linkingSourceId}
                                isSource={linkingSourceId === m.id}
                                targetDate={milestoneTimeline.get(m.id)?.targetDate}
                                dateFormat={settings.dateFormat}
                                onClick={() => {}}
                              />
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>

                    {/* Linking Helper UI */}
                    {linkingSourceId && (
                      <div className="absolute top-6 left-1/2 -translate-x-1/2 bg-indigo-600 text-white rounded-full px-6 py-2.5 shadow-lg shadow-indigo-200 z-50 flex items-center gap-4 animate-in slide-in-from-top-4">
                         <div className="flex items-center gap-2 text-sm font-bold"><LinkIcon size={16} className="animate-pulse" /> <span>Select a target milestone...</span></div>
                         <button onClick={() => setLinkingSourceId(null)} className="bg-indigo-700 hover:bg-indigo-800 rounded-full px-3 py-1 text-xs font-bold transition-colors">Cancel</button>
                      </div>
                    )}

                    {/* Instructions overlay */}
                    <div className="absolute bottom-6 left-6 bg-white/80 backdrop-blur-sm border border-slate-200 rounded-full px-4 py-2 text-[10px] font-bold text-slate-400 flex items-center gap-3 shadow-sm z-30">
                      <div className="flex items-center gap-1"><Activity size={12} className="text-slate-300" /> DRAG TO PAN</div>
                      <div className="w-px h-3 bg-slate-200" />
                      <div className="flex items-center gap-1"><Info size={12} className="text-slate-300" /> SHIFT+DRAG TO MOVE BRANCH</div>
                    </div>
                  </div>
                </div>
                <ProjectSidebar stats={projectStats} settings={settings} formatDate={formatDate} />
              </div>
            )}
          </>
        )}
      </main>

      {/* Modals */}
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} onUpdateSettings={setSettings} onExportBackup={handleExportBackup} onImportBackup={handleImportBackup} />
      <CloudSetupModal isOpen={isCloudSetupOpen} onClose={() => setIsCloudSetupOpen(false)} cloudStatus={cloudStatus} syncError={syncError} onDisconnect={handleDisconnectFirebase} onRestoreBackup={handleRestoreFromBackup} />
      <CreateProjectModal isOpen={isCreatingProject} onClose={() => setIsCreatingProject(false)} settings={settings} isGenerating={isGenerating} onCreate={handleCreateProject} />
      {editingProject && <EditProjectModal project={editingProject} isOpen={!!editingProject} onClose={() => setEditingProject(null)} onSave={handleSaveProjectEdit} settings={settings} />}

      {/* Subtask Modal - Used by both Map and Kanban */}
      {isEditingSubtask && selectedProjectId && activeProject && (
         <EditTaskModal 
           isOpen={!!isEditingSubtask}
           onClose={() => setIsEditingSubtask(null)}
           task={activeProject.milestones.find(m => m.id === isEditingSubtask.mId)?.subtasks[isEditingSubtask.sIdx!]!}
           milestoneName={activeProject.milestones.find(m => m.id === isEditingSubtask.mId)?.name || 'Unknown'}
           settings={settings}
           onUpdate={(updates) => updateSubtask(isEditingSubtask.mId, isEditingSubtask.sIdx!, updates)}
           onDelete={() => { deleteSubtask(isEditingSubtask.mId, isEditingSubtask.sIdx!); setIsEditingSubtask(null); }}
         />
      )}

      {/* Delete Confirmation Dialogs */}
      {milestoneToDelete && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 border border-slate-200 animate-in zoom-in duration-200">
            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600 mx-auto"><Trash2 size={24} /></div>
            <h3 className="text-lg font-bold text-slate-900 text-center mb-2">Delete Milestone?</h3>
            <div className="flex gap-3 mt-6"><button onClick={() => setMilestoneToDelete(null)} className="flex-1 bg-slate-100 font-bold py-2.5 rounded-xl">Cancel</button><button onClick={confirmDeleteMilestone} className="flex-1 bg-red-600 text-white font-bold py-2.5 rounded-xl">Delete</button></div>
          </div>
        </div>
      )}
      {projectToDelete && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 border border-slate-200 animate-in zoom-in duration-200">
            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600 mx-auto"><Trash2 size={24} /></div>
            <h3 className="text-lg font-bold text-slate-900 text-center mb-2">Delete Project?</h3>
             <div className="flex gap-3 mt-6"><button onClick={() => setProjectToDelete(null)} className="flex-1 bg-slate-100 font-bold py-2.5 rounded-xl">Cancel</button><button onClick={confirmDeleteProject} className="flex-1 bg-red-600 text-white font-bold py-2.5 rounded-xl">Delete</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Milestone } from '../types';
import { MilestonePieChart } from './PieChart';
import { Plus, ChevronRight, ChevronLeft, User, Edit2, Wand2, Clock, CalendarCheck, Trash2, ExternalLink, Link as LinkIcon, Move, X, ArrowRight, ArrowLeft } from 'lucide-react';
import { getStatusBorderColor } from '../constants';

interface MilestoneNodeProps {
  milestone: Milestone;
  showSubtasks: boolean;
  onAddSubtask: (milestoneId: string) => void;
  onAddSequence: (milestoneId: string) => void;
  onAddPrevious: (milestoneId: string) => void;
  onAddParallel: (milestoneId: string) => void;
  onEditSubtask: (milestoneId: string, subtaskIndex: number) => void;
  onUpdateName: (milestoneId: string, newName: string) => void;
  onUpdateDuration: (milestoneId: string, days: number) => void;
  onDeleteMilestone: (milestoneId: string) => void;
  onMove: (id: string, x: number, y: number, withSubtree: boolean) => void;
  onBrainstorm: (milestoneId: string) => void;
  onHover: (milestoneId: string | null) => void;

  // Linking props
  onStartLinking: (milestoneId: string) => void;
  onCompleteLinking: (milestoneId: string) => void;
  onRemoveLink: (otherId: string, type: 'parent' | 'child') => void;
  parents: { id: string, name: string }[];
  children: { id: string, name: string }[];
  isLinkingMode: boolean;
  isSource: boolean;

  targetDate?: Date;
  dateFormat: 'DD/MM/YY' | 'MM/DD/YY';
  onClick: () => void;
}

export const MilestoneNode: React.FC<MilestoneNodeProps> = ({
  milestone,
  showSubtasks,
  onAddSubtask,
  onAddSequence,
  onAddPrevious,
  onAddParallel,
  onEditSubtask,
  onUpdateName,
  onUpdateDuration,
  onDeleteMilestone,
  onMove,
  onBrainstorm,
  onHover,
  onStartLinking,
  onCompleteLinking,
  onRemoveLink,
  parents,
  children,
  isLinkingMode,
  isSource,
  targetDate,
  dateFormat,
  onClick
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempName, setTempName] = useState(milestone.name);
  const [isThinking, setIsThinking] = useState(false);
  const [showLinkMenu, setShowLinkMenu] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const linkMenuRef = useRef<HTMLDivElement>(null);

  // Dragging state
  const [isDragging, setIsDragging] = useState(false);
  const [currentPos, setCurrentPos] = useState({ x: milestone.x || 0, y: milestone.y || 0 });
  const dragStartMouse = useRef({ x: 0, y: 0 });
  const dragStartNode = useRef({ x: 0, y: 0 });

  // Sync prop position changes when not dragging (e.g. auto layout update)
  useEffect(() => {
    if (!isDragging) {
      setCurrentPos({ x: milestone.x || 0, y: milestone.y || 0 });
    }
  }, [milestone.x, milestone.y, isDragging]);

  useEffect(() => {
    if (isEditing) {
      inputRef.current?.focus();
      inputRef.current?.select();
    }
  }, [isEditing]);

  // Close link menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (linkMenuRef.current && !linkMenuRef.current.contains(event.target as Node)) {
        setShowLinkMenu(false);
      }
    };
    if (showLinkMenu) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showLinkMenu]);

  const formatDate = (date: Date | number | undefined) => {
    if (!date) return 'N/A';
    const d = new Date(date);
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = String(d.getFullYear()).slice(-2);
    return dateFormat === 'DD/MM/YY' ? `${day}/${month}/${year}` : `${month}/${day}/${year}`;
  };

  const handleBlur = () => {
    setIsEditing(false);
    if (tempName.trim() && tempName !== milestone.name) {
      onUpdateName(milestone.id, tempName);
    } else {
      setTempName(milestone.name);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleBlur();
    if (e.key === 'Escape') {
      setIsEditing(false);
      setTempName(milestone.name);
    }
  };

  const handleBrainstorm = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsThinking(true);
    await onBrainstorm(milestone.id);
    setIsThinking(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isLinkingMode || e.button !== 0 || isEditing || showLinkMenu) return;

    e.stopPropagation(); // Prevent canvas panning

    setIsDragging(true);
    dragStartMouse.current = { x: e.clientX, y: e.clientY };
    dragStartNode.current = { x: currentPos.x, y: currentPos.y };
  };

  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e: MouseEvent) => {
      const dx = e.clientX - dragStartMouse.current.x;
      const dy = e.clientY - dragStartMouse.current.y;
      setCurrentPos({
        x: dragStartNode.current.x + dx,
        y: dragStartNode.current.y + dy
      });
    };

    const handleMouseUp = (e: MouseEvent) => {
      setIsDragging(false);
      const dx = e.clientX - dragStartMouse.current.x;
      const dy = e.clientY - dragStartMouse.current.y;

      // If moved more than a few pixels, consider it a drag operation
      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
        onMove(milestone.id, dragStartNode.current.x + dx, dragStartNode.current.y + dy, e.shiftKey);
      } else {
        // Otherwise treat as click (reset position to snap back if needed, though usually same)
        setCurrentPos({ x: milestone.x || 0, y: milestone.y || 0 });
        if (!isLinkingMode) onClick();
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, milestone.id, onMove, isLinkingMode, onClick, milestone.x, milestone.y]);

  const handleClick = (e: React.MouseEvent) => {
    if (isLinkingMode) {
      e.stopPropagation();
      if (!isSource) {
        onCompleteLinking(milestone.id);
      }
    }
    // Normal click is handled via mouseUp to distinguish from drag
  };

  const subtasks = milestone.subtasks || [];
  const isComplete = subtasks.length > 0 && subtasks.every(s => s.status === 'Complete');

  return (
    <div 
      className={`absolute flex flex-col items-center group z-10 transition-opacity ${isLinkingMode && !isSource ? 'opacity-90 hover:opacity-100' : ''}`}
      style={{ left: currentPos.x, top: currentPos.y, transform: 'translate(-50%, -50%)', cursor: isDragging ? 'grabbing' : 'auto' }}
      onMouseEnter={() => onHover(milestone.id)}
      onMouseLeave={() => onHover(null)}
    >
      <div className="mb-2 h-7 flex flex-col items-center justify-center">
        {isEditing ? (
          <input
            ref={inputRef}
            type="text"
            className="text-sm font-semibold text-slate-900 bg-white border border-indigo-300 rounded px-2 py-0.5 shadow-sm outline-none focus:ring-2 focus:ring-indigo-500 min-w-[120px]"
            value={tempName}
            onChange={(e) => setTempName(e.target.value)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
            onClick={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
          />
        ) : (
          <div 
            onClick={(e) => { e.stopPropagation(); setIsEditing(true); }}
            className="flex items-center gap-1.5 cursor-pointer hover:bg-white hover:shadow-sm px-2 py-0.5 rounded-full transition-all group/name"
          >
            <span className="text-sm font-semibold text-slate-700 whitespace-nowrap">
              {milestone.name}
            </span>
            <Edit2 size={10} className="text-slate-400 opacity-0 group-hover/name:opacity-100 transition-opacity" />
          </div>
        )}
      </div>

      {/* Wrapper for Circle and Buttons */}
      <div className="relative z-50 group/circle">

        {/* The Circle - Draggable Target */}
        <div 
          className={`rounded-full bg-white shadow-xl ring-2 transition-all duration-300 active:scale-95 
            ${isThinking ? 'ring-indigo-400 animate-pulse' : ''}
            ${isLinkingMode && isSource ? 'ring-4 ring-indigo-500 scale-110' : ''}
            ${isLinkingMode && !isSource ? 'ring-slate-100 hover:ring-indigo-400 hover:scale-110' : 'ring-slate-100 group-hover:ring-indigo-300 group-hover:scale-110'}
            ${isDragging ? 'cursor-grabbing scale-105 shadow-2xl ring-indigo-400' : 'cursor-grab'}
          `}
          onMouseDown={handleMouseDown}
          onClick={handleClick}
        >
          <MilestonePieChart subtasks={subtasks} size={100} />

          {/* Drag Handle Indicator on Hover */}
          {!isLinkingMode && !isDragging && !showLinkMenu && (
            <div className="absolute inset-0 rounded-full bg-black/0 group-hover:bg-black/5 flex items-center justify-center transition-colors pointer-events-none">
               <Move size={20} className="text-white opacity-0 group-hover:opacity-50" />
            </div>
          )}

          {/* Visual indicator for valid drop target during linking */}
          {isLinkingMode && !isSource && (
            <div className="absolute inset-0 rounded-full bg-indigo-500/10 animate-pulse pointer-events-none" />
          )}
        </div>

        {/* Floating Tooltip for Timeline */}
        {!isLinkingMode && !isDragging && !showLinkMenu && (
          <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[10px] px-2 py-1 rounded opacity-0 group-hover/circle:opacity-100 transition-opacity whitespace-nowrap z-50 pointer-events-none flex flex-col items-center shadow-lg">
            <div className="flex items-center gap-1">
              <Clock size={10} className="text-indigo-400" />
              <span>Target: {formatDate(targetDate)}</span>
            </div>
            {isComplete && milestone.completedAt && (
              <div className="flex items-center gap-1 mt-1 text-emerald-400">
                <CalendarCheck size={10} />
                <span>Actual: {formatDate(milestone.completedAt)}</span>
              </div>
            )}
            <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-900" />
          </div>
        )}

        {/* Quick Actions Panel - Hide during linking mode and dragging */}
        {!isLinkingMode && !isDragging && (
          <div className={`absolute left-full top-1/2 -translate-y-1/2 pl-3 flex flex-col gap-1.5 transition-all transform duration-300 z-50 ${showLinkMenu ? 'opacity-100 translate-x-1' : 'opacity-0 group-hover/circle:opacity-100 group-hover/circle:translate-x-1'}`}>
            <button 
              onClick={handleBrainstorm}
              disabled={isThinking}
              className="p-2 bg-gradient-to-tr from-amber-400 to-amber-500 text-white rounded-full shadow-lg hover:from-amber-500 hover:to-amber-600 active:scale-90 transition-all border border-amber-300/50"
              title="AI Brainstorm Subtasks"
            >
              <Wand2 size={14} className={`pointer-events-none ${isThinking ? 'animate-spin' : ''}`} />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onAddPrevious(milestone.id); }}
              className="p-2 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 active:scale-90 transition-all border border-blue-500"
              title="Previous Step"
            >
              <ChevronLeft size={14} className="pointer-events-none" />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onAddSequence(milestone.id); }}
              className="p-2 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 active:scale-90 transition-all border border-blue-500"
              title="Next Step"
            >
              <ChevronRight size={14} className="pointer-events-none" />
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); onAddParallel(milestone.id); }}
              className="p-2 bg-indigo-600 text-white rounded-full shadow-lg hover:bg-indigo-700 active:scale-90 transition-all border border-indigo-500"
              title="Parallel Step"
            >
              <Plus size={14} className="pointer-events-none" />
            </button>
            <div className="relative">
              <button 
                onClick={(e) => { 
                    e.stopPropagation();
                    setShowLinkMenu(!showLinkMenu);
                }}
                className={`p-2 rounded-full shadow-lg active:scale-90 transition-all border ${showLinkMenu ? 'bg-violet-700 text-white border-violet-800' : 'bg-violet-600 text-white hover:bg-violet-700 border-violet-500'}`}
                title="Manage Links"
              >
                {showLinkMenu ? <X size={14} /> : <LinkIcon size={14} />}
              </button>

              {/* Link Management Menu */}
              {showLinkMenu && (
                <div 
                  ref={linkMenuRef}
                  className="absolute left-full top-0 ml-3 bg-white rounded-xl shadow-xl border border-slate-200 p-2 min-w-[200px] z-[100] animate-in slide-in-from-left-2 fade-in duration-200"
                  onMouseDown={(e) => e.stopPropagation()} 
                >
                   <button 
                     onClick={(e) => {
                       e.stopPropagation();
                       setShowLinkMenu(false);
                       onStartLinking(milestone.id);
                     }}
                     className="w-full flex items-center gap-2 px-3 py-2 text-xs font-bold text-violet-600 hover:bg-violet-50 rounded-lg transition-colors mb-1"
                   >
                     <Plus size={14} /> Add New Link
                   </button>

                   {(parents.length > 0 || children.length > 0) && <div className="h-px bg-slate-100 my-1" />}

                   {/* Parents (Incoming) */}
                   {parents.length > 0 && (
                     <div className="mb-2">
                       <div className="text-[9px] font-black text-slate-400 uppercase tracking-wider px-2 py-1">Incoming (Parents)</div>
                       {parents.map(p => (
                         <div key={p.id} className="flex items-center justify-between px-2 py-1.5 hover:bg-slate-50 rounded-lg group/item">
                           <div className="flex items-center gap-2 text-xs text-slate-600 truncate max-w-[120px]">
                             <ArrowLeft size={10} className="text-slate-400 shrink-0" />
                             <span className="truncate" title={p.name}>{p.name}</span>
                           </div>
                           <button 
                             onClick={() => onRemoveLink(p.id, 'parent')}
                             className="text-slate-300 hover:text-red-500 transition-colors"
                             title="Remove Link"
                           >
                             <Trash2 size={12} />
                           </button>
                         </div>
                       ))}
                     </div>
                   )}

                   {/* Children (Outgoing) */}
                   {children.length > 0 && (
                     <div>
                       <div className="text-[9px] font-black text-slate-400 uppercase tracking-wider px-2 py-1">Outgoing (Children)</div>
                       {children.map(c => (
                         <div key={c.id} className="flex items-center justify-between px-2 py-1.5 hover:bg-slate-50 rounded-lg group/item">
                           <div className="flex items-center gap-2 text-xs text-slate-600 truncate max-w-[120px]">
                             <ArrowRight size={10} className="text-slate-400 shrink-0" />
                             <span className="truncate" title={c.name}>{c.name}</span>
                           </div>
                           <button 
                             onClick={() => onRemoveLink(c.id, 'child')}
                             className="text-slate-300 hover:text-red-500 transition-colors"
                             title="Remove Link"
                           >
                             <Trash2 size={12} />
                           </button>
                         </div>
                       ))}
                     </div>
                   )}
                </div>
              )}
            </div>

            <button 
              onClick={(e) => { 
                  e.preventDefault();
                  e.stopPropagation(); 
                  onDeleteMilestone(milestone.id); 
              }}
              className="p-2 bg-red-100 text-red-600 rounded-full shadow-lg hover:bg-red-200 active:scale-90 transition-all border border-red-200"
              title="Delete Milestone"
            >
              <Trash2 size={14} className="pointer-events-none" />
            </button>
          </div>
        )}
      </div>

      {showSubtasks && !isLinkingMode && !isDragging && (
        <div className="mt-4 w-52 bg-white rounded-xl shadow-xl border border-slate-100 p-2 z-10 animate-in fade-in slide-in-from-top-2 duration-200">
          <div className="flex items-center justify-between border-b border-slate-50 pb-1.5 px-1 mb-2">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              Tasks ({subtasks.length})
            </div>
            <div className="flex items-center gap-1">
               <input 
                type="number" 
                className="w-8 bg-slate-100 rounded text-[9px] font-bold text-slate-600 text-center outline-none focus:ring-1 focus:ring-indigo-500"
                value={milestone.estimatedDuration || 0}
                onChange={(e) => onUpdateDuration(milestone.id, parseInt(e.target.value) || 0)}
                onClick={(e) => e.stopPropagation()}
                title="Estimated Days"
              />
              <span className="text-[9px] font-bold text-slate-400">DAYS</span>
            </div>
          </div>
          <div className="flex flex-col gap-1.5 max-h-48 overflow-y-auto pr-1">
            {subtasks.map((task, idx) => (
              <div 
                key={task.id} 
                onClick={(e) => { e.stopPropagation(); onEditSubtask(milestone.id, idx); }}
                className="text-xs p-2 rounded-lg bg-slate-50 hover:bg-indigo-50 hover:shadow-sm cursor-pointer flex items-center justify-between group/task transition-all"
              >
                <div className="flex flex-col flex-1 min-w-0 pr-2">
                  <div className="flex items-center justify-between">
                    <span className="font-semibold truncate text-slate-800">{task.name}</span>
                    {task.link && (
                      <a 
                        href={task.link.startsWith('http') ? task.link : `https://${task.link}`} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        onClick={(e) => e.stopPropagation()}
                        className="ml-2 p-1 text-indigo-400 hover:text-indigo-600 hover:bg-indigo-50 rounded transition-all"
                        title="Open Resource Link"
                      >
                        <ExternalLink size={12} />
                      </a>
                    )}
                  </div>
                  <span className="text-[9px] text-slate-500 flex items-center gap-1 mt-0.5">
                    <User size={9} /> {task.assignedTo || 'Unassigned'}
                  </span>
                  {task.status === 'Complete' && task.completedAt && (
                    <span className="text-[8px] text-emerald-600 font-medium">Done {formatDate(task.completedAt)}</span>
                  )}
                </div>
                <div 
                  className="w-2.5 h-2.5 rounded-full shrink-0 shadow-sm border border-white" 
                  style={{ backgroundColor: getStatusBorderColor(task.status) }} 
                />
              </div>
            ))}
            <button 
              onClick={(e) => { e.stopPropagation(); onAddSubtask(milestone.id); }}
              className="mt-1 w-full py-1.5 border border-dashed border-slate-200 rounded-lg text-[10px] text-slate-400 font-bold hover:border-indigo-300 hover:text-indigo-500 transition-colors flex items-center justify-center gap-1"
            >
              <Plus size={10} /> NEW TASK
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

