            assignedTo: '',
            notes: '',
            status: 'Not started'
          }));
          return { ...m, subtasks: [...(m.subtasks || []), ...formattedTasks] };
        })
      };
    }));
  };

  const handleCreateProject = async (newProjectData: any, useAI: boolean) => {
    setIsGenerating(true);
    let milestones: Milestone[] = [];
    const defaultMilestones = [{
      id: 'm1',
      name: 'Initial Concept',
      dependsOn: [],
      estimatedDuration: 7,
